RP_LITERAL_2_text += "n. Beobachte Wiederholungen mit Metriken oder Logs, sonst bleiben Störungen unsichtbar. Für komplexere Anforderungen (Circuit Breaker) gibt es spezialisierte Bibliotheken; die Annotationen im Framework sind bewusst einfach gehalten.\",\"exercises\":[{\"level\":1,\"task\":\"Ändere maxRetries auf 4 und passe die Tests an. Berechne vorher, wie viele Aufrufe bei dauerhaftem 503 stattfinden.\",\"acceptance\":\"Erwartung 5 Aufrufe; die Tests bestätigen es.\"},{\"level\":2,\"task\":\"Grenzfall: Setze read-timeout im Test auf 2 s und die Serververzögerung auf 1,5 s. Was passiert, und warum gibt es keine Wiederholung?\",\"acceptance\":\"Aufruf gelingt ohne Wiederholung (1 Aufruf), weil die Antwort vor dem Timeout eintrifft.\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne @EnableResilientMethods und führe den Retry-Test aus. Beschreibe das Ergebnis.\",\"acceptance\":\"Beobachtet: nur 1 Aufruf, Ausnahme sofort; ohne Aktivierung gibt es keine Wiederholung und keine Fehlermeldung.\"}],\"sources\":[{\"url\":\"https://docs.spring.io/spring-framework/reference/core/resilience.html\",\"title\":\"Spring Framework: Resilience-Features (@Retryable, @ConcurrencyLimit)\"},{\"url\":\"https://docs.spring.io/spring-boot/reference/io/rest-client.html\",\"title\":\"Spring Boot Referenz: REST Clients\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Alle vier Tests laufen im Lab grün (JDK 21.0.11 und 26.0.1) gegen einen lokalen JDK-HttpServer. Kein Test gegen ein echtes Fremdsystem; @ConcurrencyLimit wurde nicht unter Last getestet.\"},\"quiz\":[{\"q\":\"Ein Client mit @Retryable(maxRetries = 2) trifft auf einen dauerhaft ausgefallenen Dienst (503). Wie viele Aufrufe finden statt?\",\"options\":[\"2\",\"3\",\"1\"],\"correct\":1,\"explain\":\"Gesamtversuche = 1 + maxRetries.\",\"rationales\":[\"maxRetries zählt nur die Wiederholungen, der erste Versuch kommt hinzu.\",\"Ein Versuch plus zwei Wiederholungen ergibt drei Aufrufe (im Lab-Test belegt).\",\"Mit einem Aufruf würde nie wiederholt; der Fall ist dafür gedacht.\"],\"sources\":[\"https://docs.spring.io/spring-framework/reference/core/resilience.html\",\"https://docs.spring.io/spring-boot/reference/io/rest-client.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum sollte ein POST, der eine Zahlung auslöst, nicht blind wiederholt werden?\",\"options\":[\"Weil POST immer einen Timeout auslöst.\",\"Weil die Zahlung doppelt ausgelöst werden könnte, wenn nur die Antwort verloren ging.\",\"Weil @Retryable keine Methoden mit Rückgabewert unterstützt.\"],\"correct\":1,\"explain\":\"Nicht idempotente Aufrufe brauchen einen Idempotenzschlüssel, bevor sie wiederholt werden dürfen.\",\"rationales\":[\"POST hat keine besondere Timeout-Eigenschaft.\",\"Nicht-idempotente Operationen dürfen nur mit Idempotenzschlüssel wiederholt werden.\",\"Rückgabewerte sind kein Hindernis (das Lab liefert ein BigDecimal).\"],\"sources\":[\"https://docs.spring.io/spring-framework/reference/core/resilience.html\",\"https://docs.spring.io/spring-boot/reference/io/rest-client.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Welche Wirkung hat @ConcurrencyLimit(4) auf eine Methode?\",\"options\":[\"Sie darf höchstens 4-mal insgesamt aufgerufen werden.\",\"Höchstens 4 Threads dürfen sie gleichzeitig ausführen.\",\"Sie wird bei Fehler 4-mal wiederholt.\"],\"correct\":1,\"explain\":\"@ConcurrencyLimit begrenzt die Zahl gleichzeitiger Aufrufe.\",\"rationales\":[\"Das wäre eine Gesamtbegrenzung; es geht um Gleichzeitigkeit.\",\"Die Zahl begrenzt die parallele Ausführung und schützt das Fremdsystem.\",\"Wiederholungen steuert @Retryable.\"],\"sources\":[\"https://docs.spring.io/spring-framework/reference/core/resilience.html\",\"https://docs.spring.io/spring-boot/reference/io/rest-client.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"@Component\\npublic class ExchangeRateClient {\\n\\n\\trecord RateResponse(String currency, BigDecimal rate) {}\\n\\n\\tprivate final RestClient restClient;\\n\\n\\tExchangeRateClient(RestClient.Builder builder, @Value(\\\"${lab.rates.base-url}\\\") String baseUrl) {\\n\\t\\tthis.restClient = builder.baseUrl(baseUrl).build();\\n\\t}\\n\\n\\t/** Wiederholt nur Fehler, bei denen ein weiterer Versuch sinnvoll sein kann (Netz, 5xx), nie 4xx. */\\n\\t@Retryable(includes = { ResourceAccessException.class, HttpServerErrorException.class },\\n\\t\\t\\tmaxRetries = 2, delay = 20, multiplier = 2, jitter = 5)\\n\\t@ConcurrencyLimit(4)\\n\\tpublic BigDecimal rateFor(String currency) {\\n\\t\\tRateResponse response = restClient.get().uri(\\\"/rates/{currency}\\\", currency)\\n\\t\\t\\t\\t.retrieve().body(RateResponse.class);\\n\\t\\tif (response == null || response.rate() == null) {\\n\\t\\t\\tthrow new IllegalStateException(\\\"Antwort ohne Kurs\\\");\\n\\t\\t}\\n\\t\\treturn response.rate();\\n\\t}\\n}\",\"codeLang\":\"Java\",\"code2\":\"\\t@Test\\n\\tvoid retriesServerErrorsAndSucceeds() {\\n\\t\\tfailFirst = 2;\\n\\t\\tassertThat(client.rateFor(\\\"USD\\\")).isEqualByComparingTo(new BigDecimal(\\\"1.0842\\\"));\\n\\t\\tassertThat(calls.get()).isEqualTo(3);            // 1 Versuch + 2 Wiederholungen\\n\\t}\\n\\n\\t@Test\\n\\tvoid givesUpAfterMaxRetries() {\\n\\t\\tfailFirst = 10;\\n\\t\\tassertThatThrownBy(() -> client.rateFor(\\\"USD\\\")).isInstanceOf(HttpServerErrorException.class);\\n\\t\\tassertThat(calls.get()).isEqualTo(3);\\n\\t}\\n\\n\\t@Test\\n\\tvoid doesNotRetryClientErrors() {\\n\\t\\tfailFirst = 10;\\n\\t\\tfailStatus = 404;\\n\\t\\tassertThatThrownBy(() -> client.rateFor(\\\"XXX\\\")).isInstanceOf(HttpClientErrorException.class);\\n\\t\\tassertThat(calls.get()).isEqualTo(1);\\n\\t}\",\"code2Lang\":\"Java\"}]},{\"id\":\"js-m2\",\"course\":\"javascript\",\"part\":23,\"partTitle\":\"JavaScript & Vue · Vollständiger Lernpfad\",\"title\":\"Vue-Komponenten-Architektur · v-model, Slots, Dialoge und Typen\",\"lessons\":[{\"id\":\"js-m2-l1\",\"title\":\"defineModel: eigene Komponenten mit v-model\",\"minutes\":30,\"objectives\":[\"Erklären, was v-model auf einer Komponente tatsächlich tut (Prop plus Ereignis)\",\"Mit defineModel eine Komponente schreiben, die einen Wert zweiseitig bindet\",\"Mehrere benannte Models (v-model:title, v-model:done) einsetzen\",\"Mit der set-Option und einem eigenen Modifikator (.clamp) Werte vor der Weitergabe prüfen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, was v-model auf einer Komponente tatsächlich tut (Prop plus Ereignis)</li><li>Mit defineModel eine Komponente schreiben, die einen Wert zweiseitig bindet</li><li>Mehrere benannte Models (v-model:title, v-model:done) einsetzen</li><li>Mit der set-Option und einem eigenen Modifikator (.clamp) Werte vor der Weitergabe prüfen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Props, Emits, Slots und zugängliche Formulare“ (js-m1-l10); Composition API.</p><h2>In einfachen Worten</h2><p>Mit v-model bindest du ein Eingabefeld an eine Variable: Tippt jemand etwas ein, ändert sich die Variable, und umgekehrt. Bei eigenen Komponenten willst du dasselbe: &lt;QuantityField v-model=\\\"menge\\\" /&gt;.</p><p>Dahinter steckt keine Magie, sondern ein Vertrag aus zwei Teilen: Das Kind bekommt einen Wert über eine Prop (modelValue) und meldet Änderungen über ein Ereignis (update:modelValue) zurück. Früher musstest du beides von Hand schreiben.</p><p>Seit Vue 3.4 gibt es dafür das Makro defineModel(). Es liefert dir eine Variable, die sich wie eine normale ref benutzen lässt: Liest du sie, bekommst du den Wert vom Elternteil; schreibst du sie, geht die Änderung per Ereignis zurück. Du denkst nur noch in „lesen und schreiben“, nicht mehr in „Prop und Emit“.</p><h2>Schritt für Schritt</h2><ol><li>const quantity = defineModel&lt;number&gt;({ required: true }) ersetzt die Prop modelValue und das Ereignis update:modelValue.</li><li>Im Template bindest du das Eingabefeld direkt: v-model.number=\\\"quantity\\\". Der Modifikator .number wandelt die Eingabe in eine Zahl um.</li><li>Mit einem Namen, z. B. defineModel(\\\"title\\\"), entsteht ein benanntes Model. Der Elternteil schreibt dann v-model:title=\\\"...\\\" – so kann eine Komponente mehrere zweiseitige Werte haben (EditableTitle: title und done).</li><li>Die set-Option läuft, bevor der Wert nach außen gemeldet wird. So kannst du Werte korrigieren: ganze Zahl erzwingen und mit .clamp in den erlaubten Bereich klemmen.</li><li>Modifikatoren des Elternteils (v-model.clamp=\\\"menge\\\") erhältst du als zweiten Rückgabewert: const [quantity, modifiers] = defineModel&lt;number, \\\"clamp\\\"&gt;(...).</li><li>Der Test mountet die Komponente und prüft das emittierte Ereignis update:modelValue. Ohne .clamp wird 4 gemeldet; mit .clamp werden 99 → 10 und -5 → 0 gemeldet.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>QuantityField.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>EditableTitle.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (tests/components.spec.ts, Block „defineModel“): 3 Tests grün\\n - meldet Änderungen über update:modelValue         -&gt; [[4]]\\n - begrenzt mit Modifikator .clamp (Grenz-/Fehlerfall) -&gt; [[10], [0]]\\n - mehrere benannte Models                          -&gt; update:done [[true]], update:title [[\\\"Neu\\\"]]</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Die Prop direkt im Kind verändern (props.modelValue = 5).<br><strong>Warum:</strong> Props sind „von oben“ vorgegeben und schreibgeschützt. Das Verändern wird von Vue gemeldet und führt zu unvorhersehbarem Zustand.<br><strong>Besser:</strong> defineModel verwenden (oder ein Ereignis auslösen). Die Änderung läuft zum Elternteil, der entscheidet.</li><li><strong>Falsch:</strong> Im Kind eine lokale ref mit dem Anfangswert aus der Prop anlegen und danach nicht mehr synchron halten.<br><strong>Warum:</strong> Ändert der Elternteil den Wert, zeigt das Kind weiter den alten. Zwei Quellen der Wahrheit laufen auseinander.<br><strong>Besser:</strong> Mit defineModel bleibt es eine Quelle. Für bewusste lokale Kopien (Entwurf) ein eigenes „Übernehmen“-Ereignis vorsehen.</li><li><strong>Falsch:</strong> Eingaben nicht prüfen, weil „das Feld ja type=number hat“.<br><strong>Warum:</strong> Der Browser lässt Zahlenfelder leer oder mit Grenzwerten zu; auch NaN ist möglich. Die Komponente muss sich selbst schützen.<br><strong>Besser:</strong> Mit set die Werte normalisieren (ganze Zahl, Grenzen). Prüfe Normalfall, Grenzfall und Fehlerfall im Test, wie hier gezeigt.</li></ul><h2>Praxis</h2><p>Ein gutes Model-Interface ist klein: ein Wert, ein Name, ein klarer Typ. Wenn eine Komponente sechs v-models braucht, ist sie meist zu groß und besser in kleinere Komponenten zu teilen. Dokumentiere Einheiten und Grenzen (Prop min/max) im Komponentenvertrag.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Baue eine Komponente RatingInput mit defineModel&lt;number&gt; (1 bis 5) und nativen Radio-Buttons mit Beschriftung. Schreibe einen Test, der ein Klick-Ereignis prüft.<br><em>Abnahme:</em> Klick auf „3“ meldet update:modelValue mit 3; Beschriftungen sind mit den Eingaben verknüpft.</li><li><strong>Grenzfall:</strong> Prüfe QuantityField mit .clamp bei min und max genau (0 und 10) sowie bei 10.9 und -0.5.<br><em>Abnahme:</em> 0 und 10 bleiben; 10.9 wird zu 10; -0.5 wird zu 0 (Math.trunc und Klemmen sind erklärt).</li><li><strong>Fehlerfall:</strong> Gib in QuantityField einen Text („abc“) ein, der type=number nicht zulässt. Beschreibe, welcher Wert gemeldet wird und warum der Nutzer das nicht merkt. Schlage eine Fehlermeldung vor.<br><em>Abnahme:</em> Beobachtung dokumentiert; ein Vorschlag mit sichtbarer Textmeldung (nicht nur Farbe) ist formuliert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/components/v-model.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Component v-model</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/api/sfc-script-setup.html#definemodel\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: defineModel (Makro)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Code und Tests im vue-lab (Vue 3.5.45, Vitest 5.1.0, jsdom 31): tests/components.spec.ts mit 15 Tests grün; vue-tsc fehlerfrei. Verhalten in echten Browsern und mit Screenreadern nicht automatisiert geprüft.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Ein gutes Model-Interface ist klein: ein Wert, ein Name, ein klarer Typ. Wenn eine Komponente sechs v-models braucht, ist sie meist zu groß und besser in kleinere Komponenten zu teilen. Dokumentiere Einheiten und Grenzen (Prop min/max) im Komponentenvertrag.\",\"exercises\":[{\"level\":1,\"task\":\"Baue eine Komponente RatingInput mit defineModel<number> (1 bis 5) und nativen Radio-Buttons mit Beschriftung. Schreibe einen Test, der ein Klick-Ereignis prüft.\",\"acceptance\":\"Klick auf „3“ meldet update:modelValue mit 3; Beschriftungen sind mit den Eingaben verknüpft.\"},{\"level\":2,\"task\":\"Grenzfall: Prüfe QuantityField mit .clamp bei min und max genau (0 und 10) sowie bei 10.9 und -0.5.\",\"acceptance\":\"0 und 10 bleiben; 10.9 wird zu 10; -0.5 wird zu 0 (Math.trunc und Klemmen sind erklärt).\"},{\"level\":3,\"task\":\"Fehlerfall: Gib in QuantityField einen Text („abc“) ein, der type=number nicht zulässt. Beschreibe, welcher Wert gemeldet wird und warum der Nutzer das nicht merkt. Schlage eine Fehlermeldung vor.\",\"acceptance\":\"Beobachtung dokumentiert; ein Vorschlag mit sichtbarer Textmeldung (nicht nur Farbe) ist formuliert.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/components/v-model.html\",\"title\":\"Vue: Component v-model\"},{\"url\":\"https://vuejs.org/api/sfc-script-setup.html#definemodel\",\"title\":\"Vue: defineModel (Makro)\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Code und Tests im vue-lab (Vue 3.5.45, Vitest 5.1.0, jsdom 31): tests/components.spec.ts mit 15 Tests grün; vue-tsc fehlerfrei. Verhalten in echten Browsern und mit Screenreadern nicht automatisiert geprüft.\"},\"quiz\":[{\"q\":\"Was verbirgt sich hinter <MyInput v-model=\\\"name\\\" />?\",\"options\":[\"Eine Prop modelValue und ein Ereignis update:modelValue.\",\"Eine globale Variable, die Vue im Hintergrund verwaltet.\",\"Ein automatisches Kopieren des Werts bei jedem Tastendruck in den Store.\"],\"correct\":0,\"explain\":\"v-model ist Kurzschreibweise für Prop modelValue plus Ereignis update:modelValue.\",\"rationales\":[\"So ist der Vertrag definiert; defineModel erzeugt beides für dich.\",\"Es gibt keine globale Variable; der Wert gehört dem Elternteil.\",\"Ein Store ist nicht beteiligt; die Bindung läuft über Prop und Ereignis.\"],\"sources\":[\"https://vuejs.org/guide/components/v-model.html\",\"https://vuejs.org/api/sfc-script-setup.html#definemodel\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Eine Komponente setzt im Kind props.modelValue = 5. Was ist das Problem?\",\"options\":[\"Props sind schreibgeschützt; Änderungen müssen per Ereignis oder defineModel zum Elternteil gehen.\",\"Es gibt kein Problem, solange der Wert eine Zahl ist und im Kind bleibt.\",\"Vue gibt die Änderung automatisch an den Elternteil weiter, ohne Hinweis.\"],\"correct\":0,\"explain\":\"Props sind schreibgeschützt; defineModel oder ein Emit ist der richtige Weg.\",\"rationales\":[\"Einseitiger Datenfluss: Daten laufen nach unten, Änderungen als Ereignisse nach oben.\",\"Der Typ ist nicht entscheidend; das Schreiben auf Props ist unzulässig.\",\"Vue warnt und synchronisiert nichts automatisch; dafür gibt es Ereignisse und defineModel.\"],\"sources\":[\"https://vuejs.org/guide/components/v-model.html\",\"https://vuejs.org/api/sfc-script-setup.html#definemodel\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Wozu dient die Option set in defineModel?\",\"options\":[\"Sie legt den Anfangswert fest, solange der Elternteil noch keinen übergibt.\",\"Sie verändert den Wert, bevor er an den Elternteil gemeldet wird (z. B. Normalisieren oder Klemmen).\",\"Sie sperrt das Feld für weitere Eingaben, sobald ein Wert gesetzt wurde.\"],\"correct\":1,\"explain\":\"set transformiert den Wert vor dem Emit; typisch für Normalisierung.\",\"rationales\":[\"Der Anfangswert kommt aus default bzw. vom Elternteil; set wirkt erst beim Schreiben.\",\"Damit setzt die Komponente ihre eigenen Regeln durch, bevor der Elternteil den Wert sieht.\",\"Das Sperren übernehmen disabled und readonly.\"],\"sources\":[\"https://vuejs.org/guide/components/v-model.html\",\"https://vuejs.org/api/sfc-script-setup.html#definemodel\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\n// Lektion \\\"defineModel und v-model\\\": eine Zahl mit optionalem .clamp-Modifikator.\\nconst props = withDefaults(defineProps<{ label: string; min?: number; max?: number }>(), { min: 0, max: 10 });\\n\\nconst [quantity, modifiers] = defineModel<number, 'clamp'>({\\n  required: true,\\n  // set() läuft, bevor der Wert an den Parent gemeldet wird.\\n  set(value) {\\n    const number = Number.isFinite(value) ? Math.trunc(value) : props.min;\\n    return modifiers.clamp ? Math.min(Math.max(number, props.min), props.max) : number;\\n  },\\n});\\n</script>\\n\\n<template>\\n  <label>\\n    {{ label }}\\n    <input type=\\\"number\\\" inputmode=\\\"numeric\\\" :min=\\\"min\\\" :max=\\\"max\\\" v-model.number=\\\"quantity\\\">\\n  </label>\\n</template>\",\"codeLang\":\"Vue\",\"code2\":\"<script setup lang=\\\"ts\\\">\\n// Mehrere v-models: v-model:title und v-model:done sind getrennte Verträge.\\nconst title = defineModel<string>('title', { required: true });\\nconst done = defineModel<boolean>('done', { default: false });\\n</script>\\n\\n<template>\\n  <div>\\n    <label>\\n      Titel\\n      <input v-model.trim=\\\"title\\\" maxlength=\\\"120\\\">\\n    </label>\\n    <label>\\n      <input v-model=\\\"done\\\" type=\\\"checkbox\\\">\\n      erledigt\\n    </label>\\n  </div>\\n</template>\",\"code2Lang\":\"Vue\"},{\"id\":\"js-m2-l2\",\"title\":\"provide und inject mit Typ und Fehlervertrag\",\"minutes\":30,\"objectives\":[\"Erklären, wann provide/inject sinnvoller ist als Props durch viele Ebenen („Prop Drilling“)\",\"Einen typisierten InjectionKey und eine Kontext-Schnittstelle definieren\",\"Kindern lesenden Zugriff geben und Änderungen nur über eine Funktion zulassen\",\"Einen fehlenden Provider mit einer verständlichen Fehlermeldung abfangen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, wann provide/inject sinnvoller ist als Props durch viele Ebenen („Prop Drilling“)</li><li>Einen typisierten InjectionKey und eine Kontext-Schnittstelle definieren</li><li>Kindern lesenden Zugriff geben und Änderungen nur über eine Funktion zulassen</li><li>Einen fehlenden Provider mit einer verständlichen Fehlermeldung abfangen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „defineModel“; Reaktivität (ref, readonly).</p><h2>In einfachen Worten</h2><p>Stell dir ein Formular vor, das tief in anderen Komponenten verschachtelt ist. Die oberste Komponente kennt das aktuelle Farbschema („hell“ oder „dunkel“), und eine kleine Komponente ganz unten braucht es. Mit Props müsstest du den Wert durch jede Ebene reichen, auch durch die, die ihn gar nicht brauchen.</p><p>provide und inject sind wie ein Aushang im Treppenhaus: Der Elternteil hängt eine Information auf (provide), und jede Komponente darunter kann sie sich holen (inject) – egal, wie viele Etagen dazwischen liegen.</p><p>Damit daraus keine unsichtbare Abhängigkeit wird, gibst du dem Aushang einen eindeutigen Schlüssel mit Typ (InjectionKey) und baust die Funktion so, dass ein fehlender „Aushang“ sofort mit einer klaren Fehlermeldung auffällt.</p><h2>Schritt für Schritt</h2><ol><li>const themeKey: InjectionKey&lt;ThemeContext&gt; = Symbol(\\\"theme\\\") erzeugt einen eindeutigen, typisierten Schlüssel. Ein Symbol kollidiert nicht mit anderen Schlüsseln.</li><li>ThemeContext ist eine Schnittstelle mit zwei Dingen: mode (nur lesbar) und toggle() (die einzige Möglichkeit, es zu ändern).</li><li>provideTheme() erstellt die ref, übergibt readonly(mode) und die Funktion an provide und gibt den Kontext zurück.</li><li>useTheme() holt den Kontext mit inject(themeKey, null) und wirft einen Fehler, wenn er fehlt („useTheme() benötigt provideTheme() …“).</li><li>ThemeProvider.vue ruft provideTheme auf und rendert die Slot-Inhalte; ThemeToggle.vue ruft useTheme auf und zeigt einen Schalter mit aria-pressed.</li><li>Die Tests prüfen: Klick wechselt data-theme von light zu dark, und ohne Provider wird die verständliche Fehlermeldung geworfen.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>injection/<wbr>theme.ts</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>ThemeToggle.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „provide/inject“): 2 Tests grün\\n - Kontext bereitgestellt, Klick -&gt; data-theme \\\"dark\\\", aria-pressed \\\"true\\\"\\n - ohne Provider -&gt; Fehler \\\"useTheme() benötigt provideTheme() in einer Eltern-Komponente.\\\"</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> inject(\\\"theme\\\") mit einem Textschlüssel und ohne Typ verwenden.<br><strong>Warum:</strong> Tippfehler im Schlüssel fallen erst zur Laufzeit auf, und der Rückgabetyp ist unbekannt.<br><strong>Besser:</strong> Einen typisierten InjectionKey in einer eigenen Datei exportieren und nur über useXyz() zugreifen.</li><li><strong>Falsch:</strong> Beim Provide die schreibbare ref weiterreichen, sodass jedes Kind den Wert ändern kann.<br><strong>Warum:</strong> Niemand weiß mehr, wer den Wert verändert hat. Fehlersuche wird schwierig.<br><strong>Besser:</strong> readonly(…) bereitstellen und Änderungen nur über benannte Funktionen (toggle) zulassen.</li><li><strong>Falsch:</strong> inject(key, defaultValue) mit einem Standardwert verwenden, um die Fehlermeldung „loszuwerden“.<br><strong>Warum:</strong> Ein vergessener Provider fällt dann nicht mehr auf; die Komponente arbeitet still mit einem falschen Wert.<br><strong>Besser:</strong> Bei Pflicht-Abhängigkeiten einen Fehler werfen. Standardwerte nur für wirklich optionale Kontexte.</li><li><strong>Falsch:</strong> provide/inject als Ersatz für globalen Anwendungszustand benutzen.<br><strong>Warum:</strong> Er ist an einen Teilbaum gebunden und schwer zu inspizieren. Für anwendungsweiten Zustand gibt es Stores (Pinia, siehe js-m1-l13).<br><strong>Besser:</strong> provide/inject für Bereichs-Kontext (Theme, Formular, Tabs); Pinia für gemeinsamen Anwendungszustand.</li></ul><h2>Praxis</h2><p>Typische gute Einsatzfälle: Formular-Kontext (Feldfehler für verschachtelte Felder), Tabs/Akkordeon (Elternteil koordiniert Kinder), Theme. Halte den Kontext schmal und benenne Funktionen nach Fachlichkeit (toggle, select), nicht nach Technik.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Baue einen FormContext mit errors (readonly Record) und setError(field, message). Eine verschachtelte Komponente FieldMessage zeigt den Fehler für ein Feld.<br><em>Abnahme:</em> Fehler gesetzt → FieldMessage zeigt den Text; ohne Provider erscheint die verständliche Fehlermeldung.</li><li><strong>Grenzfall:</strong> Verschachtele zwei ThemeProvider (innen „dark“, außen „light“). Welchen Wert sieht ein ThemeToggle im inneren Provider? Prüfe es im Test.<br><em>Abnahme:</em> Innerer Provider gewinnt („dark“); die Regel „nächster Provider darüber“ ist beschrieben.</li><li><strong>Fehlerfall:</strong> Mounte ThemeToggle ohne Provider und fange den Fehler im Test ab. Prüfe den Text der Meldung.<br><em>Abnahme:</em> Fehlertext nennt provideTheme; kein stiller Standardwert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/components/provide-inject.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Provide / Inject</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/guide/typescript/composition-api.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: TypeScript mit Composition API (Typing provide/inject)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab (tests/components.spec.ts) grün, vue-tsc fehlerfrei. In der Testausgabe erscheint eine bewusst unterdrückte Vue-Warnung für den Fall ohne Provider.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Typische gute Einsatzfälle: Formular-Kontext (Feldfehler für verschachtelte Felder), Tabs/Akkordeon (Elternteil koordiniert Kinder), Theme. Halte den Kontext schmal und benenne Funktionen nach Fachlichkeit (toggle, select), nicht nach Technik.\",\"exercises\":[{\"level\":1,\"task\":\"Baue einen FormContext mit errors (readonly Record) und setError(field, message). Eine verschachtelte Komponente FieldMessage zeigt den Fehler für ein Feld.\",\"acceptance\":\"Fehler gesetzt → FieldMessage zeigt den Text; ohne Provider erscheint die verständliche Fehlermeldung.\"},{\"level\":2,\"task\":\"Grenzfall: Verschachtele zwei ThemeProvider (innen „dark“, außen „light“). Welchen Wert sieht ein ThemeToggle im inneren Provider? Prüfe es im Test.\",\"acceptance\":\"Innerer Provider gewinnt („dark“); die Regel „nächster Provider darüber“ ist beschrieben.\"},{\"level\":3,\"task\":\"Fehlerfall: Mounte ThemeToggle ohne Provider und fange den Fehler im Test ab. Prüfe den Text der Meldung.\",\"acceptance\":\"Fehlertext nennt provideTheme; kein stiller Standardwert.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/components/provide-inject.html\",\"title\":\"Vue: Provide / Inject\"},{\"url\":\"https://vuejs.org/guide/typescript/composition-api.html\",\"title\":\"Vue: TypeScript mit Composition API (Typing provide/inject)\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab (tests/components.spec.ts) grün, vue-tsc fehlerfrei. In der Testausgabe erscheint eine bewusst unterdrückte Vue-Warnung für den Fall ohne Provider.\"},\"quiz\":[{\"q\":\"Warum verwendet man bei provide/inject einen InjectionKey statt eines Textschlüssels?\",\"options\":[\"Textschlüssel sind in Vue verboten und führen zu einem Fehler beim Start.\",\"Er trägt den Typ der bereitgestellten Werte und kann nicht versehentlich kollidieren.\",\"Er ist beim Nachschlagen deutlich schneller als ein Textschlüssel.\"],\"correct\":1,\"explain\":\"InjectionKey verbindet Schlüssel und Typ und verhindert Namenskollisionen.\",\"rationales\":[\"Textschlüssel funktionieren technisch, sind aber fehleranfällig und ohne Typ.\",\"Ein Symbol-Schlüssel ist eindeutig und macht inject typsicher.\",\"Geschwindigkeit ist hier kein relevanter Unterschied.\"],\"sources\":[\"https://vuejs.org/guide/components/provide-inject.html\",\"https://vuejs.org/guide/typescript/composition-api.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Ein Entwickler ergänzt bei inject einen Standardwert, damit der Fehler bei fehlendem Provider verschwindet. Was ist das Risiko?\",\"options\":[\"Es gibt kein Risiko, weil der Standardwert für den Kontext immer passend ist.\",\"Ein vergessener Provider fällt nicht mehr auf und die Komponente arbeitet unbemerkt mit falschen Daten.\",\"Vue kann Standardwerte bei inject nicht lesen und bricht daher ab.\"],\"correct\":1,\"explain\":\"Bei Pflicht-Kontext lieber ein klarer Fehler als ein stiller Standard.\",\"rationales\":[\"Ein Standardwert kann fachlich falsch sein und verdeckt die fehlende Voraussetzung.\",\"Pflicht-Abhängigkeiten sollen laut und deutlich scheitern.\",\"Vue unterstützt Standardwerte bei inject; das ist nicht das Problem.\"],\"sources\":[\"https://vuejs.org/guide/components/provide-inject.html\",\"https://vuejs.org/guide/typescript/composition-api.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum gibt provideTheme den Modus als readonly und die Änderung als Funktion weiter?\",\"options\":[\"Damit nur eine Stelle den Wert ändern darf und jede Änderung nachvollziehbar bleibt.\",\"Weil Vue keine schreibbaren refs bereitstellen kann.\",\"Damit der Wert nicht in Templates verwendet werden darf.\"],\"correct\":0,\"explain\":\"Lesender Zugriff plus benannte Änderungsfunktionen halten den Datenfluss nachvollziehbar.\",\"rationales\":[\"Kontrollierte Änderungen verhindern verteilte, schwer auffindbare Mutationen.\",\"Vue kann es, aber es wäre ein schlechter Entwurf.\",\"Lesen im Template ist ausdrücklich erlaubt.\"],\"sources\":[\"https://vuejs.org/guide/components/provide-inject.html\",\"https://vuejs.org/guide/typescript/composition-api.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"import { inject, provide, readonly, ref, type InjectionKey, type Ref } from 'vue';\\n\\nexport type ThemeMode = 'light' | 'dark';\\n\\nexport interface ThemeContext {\\n  mode: Readonly<Ref<ThemeMode>>;\\n  toggle: () => void;\\n}\\n\\n// Der Symbol-Schlüssel verhindert Namenskollisionen und trägt den Typ des Vertrags.\\nexport const themeKey: InjectionKey<ThemeContext> = Symbol('theme');\\n\\nexport function provideTheme(initial: ThemeMode = 'light'): ThemeContext {\\n  const mode = ref<ThemeMode>(initial);\\n  const context: ThemeContext = {\\n    mode: readonly(mode),                       // Kinder lesen, ändern nur über toggle()\\n    toggle: () => { mode.value = mode.value === 'light' ? 'dark' : 'light'; },\\n  };\\n  provide(themeKey, context);\\n  return context;\\n}\\n\\nexport function useTheme(): ThemeContext {\\n  const context = inject(themeKey, null);\\n  if (!context) throw new Error('useTheme() benötigt provideTheme() in einer Eltern-Komponente.');\\n  return context;\\n}\",\"codeLang\":\"TypeScript\",\"code2\":\"<script setup lang=\\\"ts\\\">\\nimport { useTheme } from '../injection/theme';\\n\\nconst { mode, toggle } = useTheme();\\n</script>\\n\\n<template>\\n  <button type=\\\"button\\\" :aria-pressed=\\\"mode === 'dark'\\\" @click=\\\"toggle\\\">Dunkles Design</button>\\n</template>\",\"code2Lang\":\"Vue\"},{\"id\":\"js-m2-l3\",\"title\":\"Slots mit Vertrag: Scoped Slots und defineSlots\",\"minutes\":35,\"objectives\":[\"Zwischen einfachen Slots, benannten Slots und Scoped Slots unterscheiden\",\"Eine wiederverwendbare Liste bauen, die das Aussehen jedes Eintrags dem Elternteil überlässt\",\"Slot-Daten mit defineSlots typisieren und Fallback-Inhalt vorsehen\",\"Stabile Keys und einen zugänglichen Leerzustand umsetzen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Zwischen einfachen Slots, benannten Slots und Scoped Slots unterscheiden</li><li>Eine wiederverwendbare Liste bauen, die das Aussehen jedes Eintrags dem Elternteil überlässt</li><li>Slot-Daten mit defineSlots typisieren und Fallback-Inhalt vorsehen</li><li>Stabile Keys und einen zugänglichen Leerzustand umsetzen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „provide und inject“; Slots-Grundlagen aus js-m1-l10; TypeScript-Generics (Grundlagen).</p><h2>In einfachen Worten</h2><p>Eine Liste soll an vielen Stellen verwendet werden, aber jedes Mal anders aussehen: einmal als Name mit Foto, einmal als Aufgabe mit Haken. Würdest du für jede Variante eine eigene Komponente schreiben, hättest du viel doppelten Code.</p><p>Ein Slot ist ein Platzhalter in einer Komponente, den der Elternteil füllt. Bei einem Scoped Slot gibt die Komponente dem Elternteil zusätzlich Daten mit, hier das aktuelle Element und seinen Index. Der Elternteil entscheidet, wie das Element aussieht; die Komponente kümmert sich um Schleife, Schlüssel und Leerzustand.</p><p>Mit defineSlots legst du fest, welche Slots es gibt und welche Daten sie liefern. TypeScript prüft dann im Elternteil, ob du auf item.name zugreifst, obwohl das Feld gar nicht existiert.</p><h2>Schritt für Schritt</h2><ol><li>ItemList ist generisch: generic=\\\"T extends { id: string | number }\\\". Jedes Element braucht eine id, die als Key dient.</li><li>defineSlots&lt;{ default(props: { item: T; index: number }): unknown; empty?(): unknown }&gt;() beschreibt die Slots. Der Standard-Slot ist ein Scoped Slot mit item und index.</li><li>Im Template: &lt;slot :item=\\\"item\\\" :index=\\\"index\\\" /&gt; reicht die Daten pro Zeile an den Elternteil.</li><li>Der Elternteil schreibt &lt;template #default=\\\"{ item, index }\\\"&gt;{{ index + 1 }}. {{ item.name }}&lt;/template&gt;. Das ist die Kurzschreibweise von v-slot.</li><li>Der Slot empty hat Fallback-Inhalt („Keine Einträge vorhanden.“). Ein eigener Inhalt überschreibt ihn. Die Meldung steht in einem Element mit role=\\\"status\\\".</li><li>Die Tests prüfen: nummerierte Zeilen, Fallback-Text und eigener Empty-Slot.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>ItemList.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Slots und generische Komponenten“):\\n - Scoped Slot liefert [\\\"1. Alpha\\\", \\\"2. Beta\\\"]\\n - Fallback \\\"Keine Einträge vorhanden.\\\" und eigener Empty-Slot \\\"Nichts da\\\"</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Den Index als Key verwenden (:key=\\\"index\\\").<br><strong>Warum:</strong> Wird die Liste umsortiert oder gefiltert, ordnet Vue DOM-Elemente und Zustand falsch zu (z. B. Eingaben „wandern“ zur falschen Zeile).<br><strong>Besser:</strong> Eine stabile fachliche id als Key verwenden; im Beispiel ist sie per Typ vorgeschrieben.</li><li><strong>Falsch:</strong> Slot-Inhalte ändern, indem man die übergebenen Objekte verändert (item.name = …).<br><strong>Warum:</strong> Der Elternteil verändert Daten, die ihm nicht gehören. Der Datenfluss wird undurchsichtig.<br><strong>Besser:</strong> Änderungen als Ereignis oder über eine Funktion an den Besitzer der Daten melden.</li><li><strong>Falsch:</strong> Einen leeren Zustand komplett weglassen.<br><strong>Warum:</strong> Nutzer sehen eine leere Fläche und wissen nicht, ob geladen wird, die Liste leer ist oder ein Fehler vorliegt.<br><strong>Besser:</strong> Einen Leerzustand mit Text vorsehen; role=\\\"status\\\" lässt Screenreader Änderungen höflich melden.</li><li><strong>Falsch:</strong> Alles in Slots auslagern, auch Dinge, die zur Komponente gehören.<br><strong>Warum:</strong> Die Komponente wird zur leeren Hülle, und jede Verwendung muss alles neu schreiben.<br><strong>Besser:</strong> Slots nur für variable Darstellung; Verhalten (Schleife, Keys, Leerzustand) bleibt in der Komponente.</li></ul><h2>Praxis</h2><p>Wiederverwendbare Komponenten sind ein Vertrag: Was bestimmt die Komponente (Struktur, Verhalten, Zugänglichkeit), und was bestimmt der Nutzer (Darstellung)? Schreibe diesen Vertrag in Typen (defineProps, defineSlots), nicht nur in Kommentare.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Verwende ItemList für eine Aufgabenliste mit Checkbox im Slot. Zeige Aufgabentitel und Fälligkeit.<br><em>Abnahme:</em> Jede Zeile zeigt Checkbox und Titel; die Liste hat stabile Keys.</li><li><strong>Grenzfall:</strong> Übergib eine leere Liste mit und ohne eigenen Empty-Slot. Beschreibe beide Ergebnisse.<br><em>Abnahme:</em> Ohne Slot: Standardtext; mit Slot: eigener Text. Beide stehen in role=\\\"status\\\".</li><li><strong>Fehlerfall:</strong> Greife im Slot auf item.titel zu, obwohl das Feld name heißt. Was meldet vue-tsc?<br><em>Abnahme:</em> Typfehler „Property titel does not exist“ ist beobachtet; Zeile ist korrigiert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/components/slots.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Slots (inkl. Scoped Slots)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/api/sfc-script-setup.html#defineslots\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: defineSlots</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab grün; vue-tsc prüft die Slot-Typen. Die Beobachtung „Typfehler bei item.titel“ in Übung 3 ist als Aufgabe formuliert und nicht in einer eigenen Testdatei hinterlegt.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"body2\"],\"tip\":\"Wiederverwendbare Komponenten sind ein Vertrag: Was bestimmt die Komponente (Struktur, Verhalten, Zugänglichkeit), und was bestimmt der Nutzer (Darstellung)? Schreibe diesen Vertrag in Typen (defineProps, defineSlots), nicht nur in Kommentare.\",\"exercises\":[{\"level\":1,\"task\":\"Verwende ItemList für eine Aufgabenliste mit Checkbox im Slot. Zeige Aufgabentitel und Fälligkeit.\",\"acceptance\":\"Jede Zeile zeigt Checkbox und Titel; die Liste hat stabile Keys.\"},{\"level\":2,\"task\":\"Grenzfall: Übergib eine leere Liste mit und ohne eigenen Empty-Slot. Beschreibe beide Ergebnisse.\",\"acceptance\":\"Ohne Slot: Standardtext; mit Slot: eigener Text. Beide stehen in role=\\\"status\\\".\"},{\"level\":3,\"task\":\"Fehlerfall: Greife im Slot auf item.titel zu, obwohl das Feld name heißt. Was meldet vue-tsc?\",\"acceptance\":\"Typfehler „Property titel does not exist“ ist beobachtet; Zeile ist korrigiert.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/components/slots.html\",\"title\":\"Vue: Slots (inkl. Scoped Slots)\"},{\"url\":\"https://vuejs.org/api/sfc-script-setup.html#defineslots\",\"title\":\"Vue: defineSlots\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab grün; vue-tsc prüft die Slot-Typen. Die Beobachtung „Typfehler bei item.titel“ in Übung 3 ist als Aufgabe formuliert und nicht in einer eigenen Testdatei hinterlegt.\"},\"quiz\":[{\"q\":\"Wozu dient ein Scoped Slot gegenüber einem einfachen Slot?\",\"options\":[\"Die Komponente übergibt Daten an den Slot-Inhalt, den der Elternteil damit gestaltet.\",\"Er rendert schneller als ein einfacher Slot, weil er zwischengespeichert wird.\",\"Er ersetzt Props vollständig, sodass keine Props mehr nötig sind.\"],\"correct\":0,\"explain\":\"Scoped Slots reichen Daten der Komponente an den Slot-Inhalt weiter.\",\"rationales\":[\"Der Datenfluss geht hier vom Kind zum Slot-Inhalt des Elternteils.\",\"Es geht nicht um Geschwindigkeit, sondern um Datenübergabe.\",\"Props bleiben nötig; Scoped Slots ergänzen sie.\"],\"sources\":[\"https://vuejs.org/guide/components/slots.html\",\"https://vuejs.org/api/sfc-script-setup.html#defineslots\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Eine Liste wird nach dem Hinzufügen neu sortiert, und eingegebene Texte in Zeilen springen zur falschen Zeile. Was ist die wahrscheinlichste Ursache?\",\"options\":[\"Der Index wird als Key verwendet.\",\"Der Slot hat keinen Fallback.\",\"Die Liste ist zu lang.\"],\"correct\":0,\"explain\":\"Stabile ids als Key verhindern falsche Zuordnung bei Umsortierung.\",\"rationales\":[\"Mit Index als Key erkennt Vue Zeilen nach Position, nicht nach Inhalt; Zustand wandert mit.\",\"Fallback betrifft den Leerzustand, nicht die Zuordnung.\",\"Die Länge allein verursacht dieses Verhalten nicht.\"],\"sources\":[\"https://vuejs.org/guide/components/slots.html\",\"https://vuejs.org/api/sfc-script-setup.html#defineslots\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Was bewirkt defineSlots in TypeScript-Projekten?\",\"options\":[\"Es erzeugt die Slot-Inhalte automatisch aus den Props der Komponente.\",\"Es beschreibt Slots mit ihren Daten, sodass der Elternteil typgeprüft darauf zugreifen kann.\",\"Es verhindert, dass der Elternteil die Slots überhaupt füllen kann.\"],\"correct\":1,\"explain\":\"defineSlots typisiert Slot-Namen und Slot-Props.\",\"rationales\":[\"Inhalte kommen vom Elternteil, nicht von defineSlots.\",\"vue-tsc nutzt die Typen, um Fehler wie falsche Feldnamen zu melden.\",\"Es besch";
RP_LITERAL_2_text += "reibt Slots, es sperrt sie nicht.\"],\"sources\":[\"https://vuejs.org/guide/components/slots.html\",\"https://vuejs.org/api/sfc-script-setup.html#defineslots\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\" generic=\\\"T extends { id: string | number }\\\">\\n// Lektion \\\"Slots mit Vertrag\\\": Der Parent bekommt typisierte Daten, die Komponente bleibt generisch.\\ndefineProps<{ items: readonly T[] }>();\\n\\ndefineSlots<{\\n  default(props: { item: T; index: number }): unknown;   // Scoped Slot: Daten fließen zum Parent\\n  empty?(): unknown;                                      // optionaler Slot mit Fallback\\n}>();\\n</script>\\n\\n<template>\\n  <ul v-if=\\\"items.length\\\">\\n    <li v-for=\\\"(item, index) in items\\\" :key=\\\"item.id\\\">\\n      <slot :item=\\\"item\\\" :index=\\\"index\\\" />\\n    </li>\\n  </ul>\\n  <p v-else role=\\\"status\\\"><slot name=\\\"empty\\\">Keine Einträge vorhanden.</slot></p>\\n</template>\",\"codeLang\":\"Vue\"},{\"id\":\"js-m2-l4\",\"title\":\"Teleport und natives <dialog>: zugängliche Modale\",\"minutes\":40,\"objectives\":[\"Erklären, wofür Teleport gut ist und welche Probleme er löst (Stapelreihenfolge, abgeschnittene Inhalte)\",\"Einen modalen Dialog mit dem nativen <dialog>-Element und showModal() bauen\",\"Schließen über Esc und Schaltflächen mit dem Zustand der Komponente synchron halten\",\"Den Fokus nach dem Schließen auf das auslösende Element zurücksetzen und die Grenzen des Tests benennen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, wofür Teleport gut ist und welche Probleme er löst (Stapelreihenfolge, abgeschnittene Inhalte)</li><li>Einen modalen Dialog mit dem nativen &lt;dialog&gt;-Element und showModal() bauen</li><li>Schließen über Esc und Schaltflächen mit dem Zustand der Komponente synchron halten</li><li>Den Fokus nach dem Schließen auf das auslösende Element zurücksetzen und die Grenzen des Tests benennen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „defineModel“; Grundlagen von Tastaturbedienung und Fokus (HTML &amp; CSS-Pfad).</p><h2>In einfachen Worten</h2><p>Ein modaler Dialog („Wirklich löschen?“) soll über allem liegen, den Rest der Seite sperren und per Tastatur bedienbar sein: Tab bleibt im Dialog, Esc schließt ihn, danach landet der Fokus wieder dort, wo man herkam.</p><p>Früher hat man das mühsam mit Skripten nachgebaut. Heute kann der Browser es selbst: Das HTML-Element &lt;dialog&gt; mit der Methode showModal() liefert Fokusfalle, Esc-Taste, Abdunklung des Hintergrunds (::backdrop) und macht den Rest der Seite inaktiv. Du schreibst viel weniger Code und bekommst weniger Fehler.</p><p>Vue steuert dabei nur den Zustand („offen oder zu“) und mit Teleport den Ort im DOM: Der Dialog wird logisch in deiner Komponente definiert, aber technisch direkt unter &lt;body&gt; gerendert. So schneiden Eltern mit overflow: hidden oder eigenem z-index ihn nicht ab.</p><h2>Schritt für Schritt</h2><ol><li>&lt;Teleport to=\\\"body\\\"&gt; rendert den Inhalt unter &lt;body&gt;, während Daten und Ereignisse weiter zur Komponente gehören.</li><li>Ein defineModel&lt;boolean&gt;(\\\"open\\\") bildet den Zustand ab: v-model:open=\\\"zeigeDialog\\\" im Elternteil.</li><li>Beim Wechsel von open auf true merkt sich die Komponente das aktuell fokussierte Element (opener) und ruft showModal() auf.</li><li>Das Element &lt;dialog&gt; löst das Ereignis close aus, wenn Esc gedrückt, über form[method=dialog] bestätigt oder close() aufgerufen wird. Der Handler onClose setzt open auf false und fokussiert den opener.</li><li>Schaltflächen Abbrechen/Bestätigen liegen in &lt;form method=\\\"dialog\\\"&gt;; sie schließen den Dialog ohne eigenen Code und lösen die Ereignisse cancel/confirm aus.</li><li>aria-labelledby verknüpft den Dialog mit seiner Überschrift.</li><li>Der Test beweist: Der Dialog steht im body (nicht in der Komponenten-Wurzel), nach Öffnen hat er das Attribut open, und nach dem close-Ereignis ist der Zustand false und der Fokus beim Auslöser.</li><li>Wichtige Grenze: jsdom (die Testumgebung) kennt showModal und close nicht. Der Test ersetzt sie durch eine Minimalversion. Er prüft deshalb nur unsere Logik, nicht das echte Browserverhalten (Fokusfalle, Esc).</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>ConfirmDialog.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Teleport und &lt;dialog&gt;“): 1 Test grün\\n - Dialog liegt unter &lt;body&gt;, bekommt open, aria-labelledby=\\\"dialog-title\\\"\\n - close-Ereignis -&gt; open=false, Fokus zurück auf den Auslöser\\nHinweis: showModal/close sind im Test nachgebildet (jsdom). Echtes Verhalten (Tab-Falle, Esc) manuell im Browser prüfen.</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Den Dialog mit v-if ein- und ausblenden und mit show() statt showModal() öffnen.<br><strong>Warum:</strong> show() öffnet einen nicht-modalen Dialog ohne Fokusfalle und ohne Sperre des Hintergrunds. Die Vorteile des Elements gehen verloren.<br><strong>Besser:</strong> showModal() für modale Dialoge; der Zustand wird über das Attribut open des Elements gesteuert.</li><li><strong>Falsch:</strong> Nur auf die eigenen Schaltflächen reagieren und die Esc-Taste ignorieren.<br><strong>Warum:</strong> Esc schließt den Dialog im Browser, aber der Vue-Zustand bleibt „offen“. Beim nächsten Klick passiert nichts.<br><strong>Besser:</strong> Auf das close-Ereignis des Dialogs hören und den Zustand dort zurücksetzen (wie im Beispiel).</li><li><strong>Falsch:</strong> Den Fokus nach dem Schließen nicht zurücksetzen.<br><strong>Warum:</strong> Tastaturnutzer verlieren ihre Position und müssen sich erneut durch die Seite tabben. Das verletzt die Erwartungen aus den Barrierefreiheitsrichtlinien (WCAG 2.2).<br><strong>Besser:</strong> Auslöser merken und nach close fokussieren (Browser tun das oft selbst; verlass dich nicht darauf und teste es).</li><li><strong>Falsch:</strong> Dem Testbericht „grün“ als Beweis für Barrierefreiheit trauen.<br><strong>Warum:</strong> Die Tests simulieren den Dialog. Echte Tastaturbedienung und Screenreader sind damit nicht geprüft.<br><strong>Besser:</strong> Manuell testen: Tab bleibt im Dialog, Esc schließt, Fokus kehrt zurück. Zusätzlich einen automatischen Zugänglichkeitscheck laufen lassen.</li></ul><h2>Praxis</h2><p>Für Teleport: Wähle ein festes Ziel (body oder ein eigenes Container-Element) und achte auf Server-Side-Rendering (das Ziel muss existieren). Für Dialoge: Eine klare Überschrift, eine ehrliche Beschriftung der Aktion („Aufgabe löschen“ statt „OK“) und Standardfokus auf die sichere Aktion.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Baue eine Seite mit einer Schaltfläche „Löschen“, die den Dialog öffnet. Prüfe im Browser: Tab bleibt im Dialog, Esc schließt, Fokus kehrt zur Schaltfläche zurück.<br><em>Abnahme:</em> Alle drei Beobachtungen sind notiert; das Ergebnis stammt aus dem echten Browser, nicht aus dem Test.</li><li><strong>Grenzfall:</strong> Öffne den Dialog zweimal hintereinander (öffnen, Esc, öffnen). Funktioniert der zweite Versuch? Erkläre, warum der close-Handler dafür wichtig ist.<br><em>Abnahme:</em> Zweites Öffnen funktioniert, weil der Zustand nach Esc auf false zurückgesetzt wurde.</li><li><strong>Fehlerfall:</strong> Entferne @close und öffne, schließe mit Esc und öffne erneut. Beschreibe das Fehlverhalten.<br><em>Abnahme:</em> Beobachtet: Zustand bleibt true, erneutes Öffnen scheint wirkungslos; Ursache ist erklärt.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/built-ins/teleport.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Teleport</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">MDN: &lt;dialog&gt;-Element</a> – MDN-Webdokumentation (Texte unter CC BY-SA); hier nur verlinkt und zusammengefasst.</li><li><a href=\\\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">W3C ARIA Authoring Practices: Modal Dialog Pattern</a> – W3C-Muster; nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Test im vue-lab grün (mit nachgebildetem showModal). NICHT geprüft: echte Fokusfalle, Esc und Screenreader in einem Browser; bitte mit Übung 1 manuell nachholen.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"body2\"],\"tip\":\"Für Teleport: Wähle ein festes Ziel (body oder ein eigenes Container-Element) und achte auf Server-Side-Rendering (das Ziel muss existieren). Für Dialoge: Eine klare Überschrift, eine ehrliche Beschriftung der Aktion („Aufgabe löschen“ statt „OK“) und Standardfokus auf die sichere Aktion.\",\"exercises\":[{\"level\":1,\"task\":\"Baue eine Seite mit einer Schaltfläche „Löschen“, die den Dialog öffnet. Prüfe im Browser: Tab bleibt im Dialog, Esc schließt, Fokus kehrt zur Schaltfläche zurück.\",\"acceptance\":\"Alle drei Beobachtungen sind notiert; das Ergebnis stammt aus dem echten Browser, nicht aus dem Test.\"},{\"level\":2,\"task\":\"Grenzfall: Öffne den Dialog zweimal hintereinander (öffnen, Esc, öffnen). Funktioniert der zweite Versuch? Erkläre, warum der close-Handler dafür wichtig ist.\",\"acceptance\":\"Zweites Öffnen funktioniert, weil der Zustand nach Esc auf false zurückgesetzt wurde.\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne @close und öffne, schließe mit Esc und öffne erneut. Beschreibe das Fehlverhalten.\",\"acceptance\":\"Beobachtet: Zustand bleibt true, erneutes Öffnen scheint wirkungslos; Ursache ist erklärt.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/built-ins/teleport.html\",\"title\":\"Vue: Teleport\"},{\"url\":\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog\",\"title\":\"MDN: <dialog>-Element\"},{\"url\":\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\",\"title\":\"W3C ARIA Authoring Practices: Modal Dialog Pattern\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Test im vue-lab grün (mit nachgebildetem showModal). NICHT geprüft: echte Fokusfalle, Esc und Screenreader in einem Browser; bitte mit Übung 1 manuell nachholen.\"},\"quiz\":[{\"q\":\"Nach Esc ist der Dialog geschlossen, aber die Schaltfläche „Öffnen“ reagiert nicht mehr. Was fehlt am wahrscheinlichsten?\",\"options\":[\"Ein Listener auf das close-Ereignis, der den Vue-Zustand zurücksetzt.\",\"Ein zusätzliches Teleport-Ziel.\",\"Ein CSS-Reset für den Dialog.\"],\"correct\":0,\"explain\":\"Das close-Ereignis hält Zustand und Element synchron.\",\"rationales\":[\"Esc schließt das Element, aber der Vue-Zustand bleibt true; close synchronisiert beides.\",\"Teleport bestimmt den Ort im DOM, nicht den Zustand.\",\"CSS beeinflusst das Aussehen, nicht die Ereigniskette.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/teleport.html\",\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog\",\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Welchen Vorteil hat showModal() gegenüber einem selbstgebauten Overlay aus div-Elementen?\",\"options\":[\"Der Browser liefert Fokusfalle, Esc-Behandlung und Sperre des Hintergrunds mit.\",\"Es ist nur in alten Browsern verfügbar.\",\"Es braucht kein HTML.\"],\"correct\":0,\"explain\":\"Der native Dialog erspart viel Eigenbau und potenzielle Fehler.\",\"rationales\":[\"Diese Funktionen sind im nativen Dialog eingebaut und müssen nicht nachgebaut werden.\",\"Das Element ist in aktuellen Browsern unterstützt; das Gegenteil trifft zu.\",\"Es ist ein HTML-Element.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/teleport.html\",\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog\",\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Der Test mit jsdom ist grün. Was sagt er über die echte Tastaturbedienung aus?\",\"options\":[\"Er beweist, dass die Fokusfalle im echten Browser einwandfrei funktioniert.\",\"Er prüft nur die eigene Logik; echte Tastaturbedienung bleibt manuell zu prüfen.\",\"Er ersetzt den manuellen Barrierefreiheitstest vollständig.\"],\"correct\":1,\"explain\":\"Tests mit Nachbildungen belegen Logik; Browser- und Screenreaderverhalten braucht eigene Prüfungen.\",\"rationales\":[\"Das Verhalten der Fokusfalle gehört dem Browser und wird im Test nicht ausgeführt.\",\"Ehrlich ist: Logiktest ja, Browserverhalten nein.\",\"Automatische Tests decken nur einen Teil der Anforderungen ab.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/teleport.html\",\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog\",\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\n// Lektion \\\"Teleport und natives <dialog>\\\": Fokusfalle, Esc und Hintergrund liefert der Browser.\\nimport { nextTick, ref, watch } from 'vue';\\n\\ndefineProps<{ title: string }>();\\nconst open = defineModel<boolean>('open', { required: true });\\nconst emit = defineEmits<{ confirm: []; cancel: [] }>();\\n\\nconst dialog = ref<HTMLDialogElement | null>(null);\\nlet opener: HTMLElement | null = null;\\n\\nwatch(open, async (isOpen) => {\\n  await nextTick();\\n  const element = dialog.value;\\n  if (!element) return;\\n  if (isOpen && !element.open) {\\n    opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;\\n    element.showModal();\\n  } else if (!isOpen && element.open) {\\n    element.close();\\n  }\\n});\\n\\n// \\\"close\\\" feuert bei Esc, form[method=dialog] und close(): Zustand bleibt synchron, Fokus kehrt zurück.\\nfunction onClose() {\\n  open.value = false;\\n  opener?.focus();\\n  opener = null;\\n}\\n</script>\\n\\n<template>\\n  <Teleport to=\\\"body\\\">\\n    <dialog ref=\\\"dialog\\\" aria-labelledby=\\\"dialog-title\\\" @close=\\\"onClose\\\" @cancel=\\\"emit('cancel')\\\">\\n      <form method=\\\"dialog\\\">\\n        <h2 id=\\\"dialog-title\\\">{{ title }}</h2>\\n        <slot />\\n        <button value=\\\"cancel\\\" @click=\\\"emit('cancel')\\\">Abbrechen</button>\\n        <button value=\\\"confirm\\\" @click=\\\"emit('confirm')\\\">Bestätigen</button>\\n      </form>\\n    </dialog>\\n  </Teleport>\\n</template>\",\"codeLang\":\"Vue\"},{\"id\":\"js-m2-l5\",\"title\":\"Suspense und asynchrone Komponenten\",\"minutes\":35,\"objectives\":[\"Eine asynchrone Komponente mit Top-Level-await schreiben und ihren Ladezustand mit <Suspense> anzeigen\",\"Fehler bei asynchroner Einrichtung mit onErrorCaptured behandeln\",\"Mit defineAsyncComponent schwere Komponenten erst bei Bedarf laden und Lade- und Fehlerzustand festlegen\",\"Den Status von Suspense (experimentell) bei Entscheidungen berücksichtigen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Eine asynchrone Komponente mit Top-Level-await schreiben und ihren Ladezustand mit &lt;Suspense&gt; anzeigen</li><li>Fehler bei asynchroner Einrichtung mit onErrorCaptured behandeln</li><li>Mit defineAsyncComponent schwere Komponenten erst bei Bedarf laden und Lade- und Fehlerzustand festlegen</li><li>Den Status von Suspense (experimentell) bei Entscheidungen berücksichtigen</li></ul><p><strong>Voraussetzungen:</strong> Promises und async/await (js-m1-l4); Fehlerzustände aus js-m1-l11.</p><h2>In einfachen Worten</h2><p>Manche Komponenten müssen erst Daten holen, bevor sie etwas anzeigen können. Du kannst das selbst mit isLoading und v-if lösen. Vue bietet eine zweite Möglichkeit: Die Komponente wartet ihren Aufbau mit await ab (ein „Top-Level await“ in script setup), und ein Elternteil mit &lt;Suspense&gt; zeigt währenddessen einen Platzhalter („Bericht wird geladen …“).</p><p>Eine zweite, verwandte Technik ist Lazy Loading: Eine große Komponente (ein Diagramm, ein Editor) soll gar nicht erst im Haupt-Bundle stecken, sondern erst geladen werden, wenn sie gebraucht wird. Das macht defineAsyncComponent mit einem dynamischen import().</p><p>Beide Techniken brauchen eine Antwort auf „Was, wenn es schiefgeht?“. Hier gibt es eine wichtige Besonderheit: &lt;Suspense&gt; behandelt Fehler nicht selbst.</p><h2>Schritt für Schritt</h2><ol><li>AsyncReport.vue ruft const lines = await props.load() im script setup auf. Damit ist die Komponente „asynchron“: Vue wartet mit dem Rendern, bis das Promise fertig ist.</li><li>ReportHost.vue umschließt sie mit &lt;Suspense&gt;. Im Slot #fallback steht der Ladezustand (role=\\\"status\\\"). Der Standard-Slot ist die eigentliche Komponente.</li><li>Fehler: &lt;Suspense&gt; bietet keine eigene Fehlerbehandlung. Im Elternteil fängt onErrorCaptured den Fehler und setzt einen Fehlertext (role=\\\"alert\\\"); return false verhindert, dass der Fehler weiter nach oben gemeldet wird.</li><li>createLazyPanel(loader) kapselt defineAsyncComponent mit loadingComponent, errorComponent, delay: 200 und timeout: 3000.</li><li>delay legt fest, wann die Ladeanzeige erscheint (hier 200 ms, das ist auch der Standard), damit schnelle Ladevorgänge nicht flackern. Ohne timeout wartet Vue unbegrenzt (Standard: Infinity).</li><li>Die Tests prüfen: Fallback sichtbar → nach Auflösung Inhalt; abgelehntes Promise → Fehlertext; fehlgeschlagener Import → errorComponent.</li><li>Status: Die Vue-Dokumentation bezeichnet Suspense weiterhin als experimentell. Es gibt keine Garantie, dass es stabil wird; die API kann sich ändern.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>ReportHost.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>lazyPanel.ts</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Suspense und async Komponenten“): 3 Tests grün\\n - Fallback \\\"Bericht wird geladen …\\\" -&gt; danach [\\\"Zeile A\\\", \\\"Zeile B\\\"]\\n - abgelehntes Promise -&gt; role=\\\"alert\\\": \\\"Bericht nicht verfügbar: 503\\\"\\n - fehlgeschlagener Import -&gt; \\\"Panel konnte nicht geladen werden.\\\"</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Erwarten, dass &lt;Suspense&gt; Fehler selbst abfängt.<br><strong>Warum:</strong> Laut Dokumentation bietet die Komponente keine eigene Fehlerbehandlung. Ein abgelehntes Promise im setup würde sonst als unbehandelter Fehler hochblubbern.<br><strong>Besser:</strong> Im Elternteil onErrorCaptured (oder errorCaptured) nutzen und einen Fehlerzustand anzeigen.</li><li><strong>Falsch:</strong> Suspense für anwendungskritische Funktionen verwenden, ohne den experimentellen Status zu beachten.<br><strong>Warum:</strong> Die API kann sich ändern. Ein Update kann Anpassungen erfordern.<br><strong>Besser:</strong> Bewusst entscheiden; für kritische Stellen kann ein eigener Ladezustand (isLoading, v-if) die stabilere Wahl sein. Kapsele die Verwendung an wenigen Stellen.</li><li><strong>Falsch:</strong> Ladeanzeigen sofort einblenden, auch für Vorgänge von wenigen Millisekunden.<br><strong>Warum:</strong> Es entsteht ein Flackern; Nutzer nehmen die Seite als unruhig wahr.<br><strong>Besser:</strong> Mit delay (z. B. 200 ms) arbeiten, wie bei defineAsyncComponent. Und Platz reservieren, damit sich das Layout nicht verschiebt.</li><li><strong>Falsch:</strong> Lazy Loading für winzige Komponenten.<br><strong>Warum:</strong> Jeder zusätzliche Chunk kostet einen Request. Für sehr kleine Komponenten ist der Nutzen null.<br><strong>Besser:</strong> Nur bei messbar großen oder selten genutzten Teilen (Diagramme, Editoren, Admin-Bereiche) einsetzen und das Bundle messen.</li></ul><h2>Praxis</h2><p>Entscheide pro Fall: Gehört das Laden zur Komponente (async setup + Suspense) oder zum aufrufenden Code (Composable, siehe js-m1-l11, mit Query-Cache aus Modul js-m3)? Für Daten mit Cache, Wiederholung und Aktualisierung ist ein Query-Cache meist die bessere Wahl; Suspense passt eher für einmaliges Initialisieren oder Lazy-Komponenten.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Baue die Beispiele mit einem Ladeparameter, der nach 500 ms auflöst. Beobachte den Fallback und stelle den Ablauf in einem Sequenzdiagramm dar.<br><em>Abnahme:</em> Diagramm zeigt: Mount → Fallback → Promise fertig → Inhalt; Zeiten sind notiert.</li><li><strong>Grenzfall:</strong> Setze timeout auf 100 ms und lass den Import 500 ms dauern. Was sieht der Nutzer? Wann erscheint die Ladeanzeige (delay)?<br><em>Abnahme:</em> Nach 100 ms erscheint der Fehlerzustand; eine Ladeanzeige erscheint nach delay, falls der Wert kleiner als das Timeout ist.</li><li><strong>Fehlerfall:</strong> Entferne onErrorCaptured und lass load ablehnen. Beschreibe, was in der Konsole und auf der Seite passiert.<br><em>Abnahme:</em> Beobachtung dokumentiert (unbehandelter Fehler, keine verständliche Meldung); Ergänzung des Handlers behebt es.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/built-ins/suspense.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Suspense</a> – Dort steht der Hinweis „experimental feature“ (am 12.11.2026 gelesen). Inhalt hier eigenständig zusammengefasst; CC BY 4.0.</li><li><a href=\\\"https://vuejs.org/guide/components/async.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Async Components (defineAsyncComponent)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab grün. Der experimentelle Status wurde auf der Dokumentationsseite am 12.11.2026 gelesen; spätere Änderungen sind möglich.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Entscheide pro Fall: Gehört das Laden zur Komponente (async setup + Suspense) oder zum aufrufenden Code (Composable, siehe js-m1-l11, mit Query-Cache aus Modul js-m3)? Für Daten mit Cache, Wiederholung und Aktualisierung ist ein Query-Cache meist die bessere Wahl; Suspense passt eher für einmaliges Initialisieren oder Lazy-Komponenten.\",\"exercises\":[{\"level\":1,\"task\":\"Baue die Beispiele mit einem Ladeparameter, der nach 500 ms auflöst. Beobachte den Fallback und stelle den Ablauf in einem Sequenzdiagramm dar.\",\"acceptance\":\"Diagramm zeigt: Mount → Fallback → Promise fertig → Inhalt; Zeiten sind notiert.\"},{\"level\":2,\"task\":\"Grenzfall: Setze timeout auf 100 ms und lass den Import 500 ms dauern. Was sieht der Nutzer? Wann erscheint die Ladeanzeige (delay)?\",\"acceptance\":\"Nach 100 ms erscheint der Fehlerzustand; eine Ladeanzeige erscheint nach delay, falls der Wert kleiner als das Timeout ist.\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne onErrorCaptured und lass load ablehnen. Beschreibe, was in der Konsole und auf der Seite passiert.\",\"acceptance\":\"Beobachtung dokumentiert (unbehandelter Fehler, keine verständliche Meldung); Ergänzung des Handlers behebt es.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/built-ins/suspense.html\",\"title\":\"Vue: Suspense\"},{\"url\":\"https://vuejs.org/guide/components/async.html\",\"title\":\"Vue: Async Components (defineAsyncComponent)\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab grün. Der experimentelle Status wurde auf der Dokumentationsseite am 12.11.2026 gelesen; spätere Änderungen sind möglich.\"},\"quiz\":[{\"q\":\"Eine async Komponente im <Suspense> wirft beim Laden einen Fehler. Auf der Seite erscheint nichts Verständliches. Was ist der richtige Weg?\",\"options\":[\"In einem Elternteil mit onErrorCaptured den Fehler fangen und einen Fehlerzustand anzeigen.\",\"Suspense mit dem Attribut error ergänzen.\",\"Den Fehler ignorieren, Vue zeigt automatisch eine Meldung an.\"],\"correct\":0,\"explain\":\"Suspense behandelt Fehler nicht selbst; onErrorCaptured im Elternteil übernimmt das.\",\"rationales\":[\"Laut Vue-Dokumentation bietet Suspense keine eigene Fehlerbehandlung; der Hook im Elternteil ist der vorgesehene Weg.\",\"Ein solches Attribut gibt es nicht.\",\"Es gibt keine automatische Meldung für Nutzer.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/suspense.html\",\"https://vuejs.org/guide/components/async.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Was bewirkt delay: 200 bei defineAsyncComponent?\",\"options\":[\"Die Komponente wird erst nach 200 ms verzögert vom Server geladen.\",\"Die Ladeanzeige erscheint erst nach 200 ms, damit schnelle Ladevorgänge nicht flackern.\",\"Der Ladevorgang wird nach 200 ms abgebrochen und als Fehler gemeldet.\"],\"correct\":1,\"explain\":\"delay verzögert die Ladeanzeige, nicht den Ladevorgang.\",\"rationales\":[\"Geladen wird sofort; nur die Ladeanzeige wird verzögert.\",\"So steht es in der Vue-Dokumentation (Standard 200 ms).\",\"Abbrechen steuert timeout, nicht delay.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/suspense.html\",\"https://vuejs.org/guide/components/async.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Welcher Status gilt laut Vue-Dokumentation (Stand 12.11.2026) für <Suspense>?\",\"options\":[\"Es ist stabil und nicht mehr änderbar.\",\"Es ist ein experimentelles Feature; die API kann sich ändern.\",\"Es wurde entfernt.\"],\"correct\":1,\"explain\":\"Die Dokumentation markiert Suspense als experimentell; Verwendung bewusst entscheiden.\",\"rationales\":[\"Die Dokumentation nennt es ausdrücklich experimentell.\",\"Der Hinweis auf der Seite lautet „experimental feature“ und „API may change“.\",\"Die Seite existiert und beschreibt das Feature weiterhin.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/suspense.html\",\"https://vuejs.org/guide/components/async.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\nimport { onErrorCaptured, ref } from 'vue';\\nimport AsyncReport from './AsyncReport.vue';\\n\\ndefineProps<{ load: () => Promise<string[]> }>();\\nconst failure = ref('');\\n\\n// Suspense fängt Fehler NICHT selbst ab: Fehlergrenze per onErrorCaptured.\\nonErrorCaptured((error) => {\\n  failure.value = error instanceof Error ? error.message : 'Unbekannter Fehler';\\n  return false;                                   // Fehler hier behandelt, nicht weiter nach oben melden\\n});\\n</script>\\n\\n<template>\\n  <p v-if=\\\"failure\\\" role=\\\"alert\\\">Bericht nicht verfügbar: {{ failure }}</p>\\n  <Suspense v-else>\\n    <AsyncReport :load=\\\"load\\\" />\\n    <template #fallback><p role=\\\"status\\\">Bericht wird geladen …</p></template>\\n  </Suspense>\\n</template>\",\"codeLang\":\"Vue\",\"code2\":\"import { defineAsyncComponent, h, type AsyncComponentLoader } from 'vue';\\n\\n// Lazy Loading einer schweren Komponente mit eigenem Lade- und Fehlerzustand.\\nexport function createLazyPanel(loader: AsyncComponentLoader) {\\n  return defineAsyncComponent({\\n    loader,\\n    delay: 200,                                   // Ladeanzeige erst nach 200 ms (kein Flackern)\\n    timeout: 3000,\\n    loadingComponent: { render: () => h('p', { role: 'status' }, 'Panel wird geladen …') },\\n    errorComponent: { render: () => h('p', { role: 'alert' }, 'Panel konnte nicht geladen werden.') },\\n  });\\n}\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m2-l6\",\"title\":\"Transition, TransitionGroup und reduzierte Bewegung\",\"minutes\":30,\"objectives\":[\"Mit TransitionGroup das Hinzufügen und Entfernen von Listeneinträgen animieren\",\"Nur transform und opacity animieren und begründen, warum\",\"prefers-reduced-motion per CSS und per Composable berücksichtigen\",\"Verstehen, warum stabile Keys und absolute Positionierung beim Entfernen nötig sind\"],\"body\":\"<h2>Lernziele</h2><ul><li>Mit TransitionGroup das Hinzufügen und Entfernen von Listeneinträgen animieren</li><li>Nur transform und opacity animieren und begründen, warum</li><li>prefers-reduced-motion per CSS und per Composable berücksichtigen</li><li>Verstehen, warum stabile Keys und absolute Positionierung beim Entfernen nötig sind</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Slots mit Vertrag“; CSS-Grundlagen (Transitions) aus dem HTML &amp; CSS-Pfad.</p><h2>In einfachen Worten</h2><p>Kleine Animationen helfen, Änderungen zu verstehen: Ein neuer Eintrag blendet ein, ein gelöschter blendet aus. Vue macht das einfach: Du packst die Liste in &lt;TransitionGroup&gt;, und Vue setzt zu den richtigen Zeitpunkten CSS-Klassen, die du gestaltest.</p><p>Zwei Regeln machen Animationen gut: Animiere nur Dinge, die der Browser billig zeichnen kann (transform und opacity), sonst ruckelt es. Und nimm Rücksicht auf Menschen, denen Bewegung Unwohlsein bereitet: Wer in seinem Betriebssystem „Bewegung reduzieren“ eingestellt hat, soll keine unnötigen Animationen sehen. Das Medium-Query prefers-reduced-motion verrät dir diese Einstellung.</p><h2>Schritt für Schritt</h2><ol><li>&lt;TransitionGroup tag=\\\"ul\\\" name=\\\"fade\\\"&gt; rendert eine Liste und animiert jedes Kind beim Erscheinen, Verschwinden und Verschieben. Jeder Eintrag braucht einen stabilen :key.</li><li>Vue setzt Klassen mit dem Präfix fade-: fade-enter-from/-active/-to für Einblenden, fade-leave-… für Ausblenden, fade-move für das Verschieben.</li><li>Im CSS stehen nur opacity und transform (translateY): Sie verändern kein Layout und laufen flüssig.</li><li>Beim Ausblenden bekommt .fade-leave-active position: absolute. So rücken die übrigen Einträge animiert nach, statt zu springen.</li><li>Per CSS: @media (prefers-reduced-motion: reduce) setzt die Übergänge auf none.</li><li>Per Composable: usePrefersReducedMotion liest matchMedia(\\\"(prefers-reduced-motion: reduce)\\\"), reagiert auf Änderungen und räumt den Listener mit onScopeDispose auf. FadeList schaltet damit :css=\\\"!reduced\\\" und den Namen um.</li><li>Die Tests prüfen das Composable (Anfangswert, Live-Änderung, Aufräumen) und die Listenlogik (Entfernen über Keys). Die Animation selbst prüft der Test nicht; @vue/test-utils ersetzt Transition-Komponenten standardmäßig durch Stubs.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>FadeList.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>usePrefersReducedMotion.ts</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Transition und reduzierte Bewegung“): 2 Tests grün\\n - Systemeinstellung folgt live (false -&gt; true); removeEventListener wird beim Aufräumen genau einmal aufgerufen\\n - Eintrag mit id 1 wird entfernt; [\\\"B\\\"] bleibt</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> width, height, top oder margin animieren.<br><strong>Warum:</strong> Diese Eigenschaften zwingen den Browser, das Layout neu zu berechnen. Das kann ruckeln, besonders auf schwächeren Geräten.<br><strong>Besser:</strong> transform und opacity verwenden (wie im Beispiel).</li><li><strong>Falsch:</strong> Animationen ohne Rücksicht auf prefers-reduced-motion einsetzen.<br><strong>Warum:</strong> Für manche Menschen lösen Bewegungen Schwindel oder Übelkeit aus. Die Betriebssystem-Einstellung ist ein klares Signal.<br><strong>Besser:</strong> Bewegung bei reduce abschalten oder stark vereinfachen (z. B. nur Einblenden ohne Verschieben). WCAG 2.2 verlangt zudem, dass Bewegung abschaltbar ist, wenn sie nicht wesentlich ist.</li><li><strong>Falsch:</strong> Den Listenindex als Key verwenden.<br><strong>Warum:</strong> Beim Entfernen eines Elements animiert Vue das falsche Element hinaus, weil sich alle Keys verschieben.<br><strong>Besser:</strong> Stabile ids als Key verwenden.</li><li><strong>Falsch:</strong> Dem Test „TransitionGroup funktioniert“ vertrauen.<br><strong>Warum:</strong> Test-Utils ersetzen Transition-Komponenten durch Stubs; die echte Animation läuft nicht.<br><strong>Besser:</strong> Logik testen (Keys, Einträge) und die Animation einmal manuell im Browser mit und ohne „Bewegung reduzieren“ prüfen.</li></ul><h2>Praxis</h2><p>Animationen sollen Bedeutung transportieren (neu, weg, verschoben), nicht dekorieren. Halte sie kurz (unter etwa 300 ms), vermeide Endlosschleifen und plane den Platzbedarf, damit sich nichts verschiebt, wenn Inhalt erscheint.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Baue eine Seite, auf der man Einträge hinzufügen und löschen kann. Prüfe im Browser die Animation. Schalte dann im Betriebssystem „Bewegung reduzieren“ ein und prüfe, dass sie entfällt.<br><em>Abnahme:</em> Mit Standardeinstellung: Einblenden/Ausblenden sichtbar; mit reduzierter Bewegung: keine Animation, Funktion bleibt.</li><li><strong>Grenzfall:</strong> Füge schnell hintereinander zehn Einträge hinzu. Ruckelt etwas? Was hilft?<br><em>Abnahme:</em> Beobachtung dokumentiert; transform/opacity-Hinweis und kurze Dauer sind als Maßnahmen genannt.</li><li><strong>Fehlerfall:</strong> Ersetze den Key durch den Index und lösche den ersten Eintrag. Beschreibe, welches Element animiert hinausfliegt.<br><em>Abnahme:</em> Falsches Element animiert hinaus; Erklärung nennt die verschobenen Keys.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/built-ins/transition.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Transition und TransitionGroup</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">MDN: prefers-reduced-motion</a> – MDN-Webdokumentation (Texte unter CC BY-SA); hier nur verlinkt und zusammengefasst.</li><li><a href=\\\"https://www.w3.org/WAI/WCAG22/Techniques/css/C39\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">W3C WCAG 2.2: Technik C39 – prefers-reduced-motion</a> – W3C-Technik; nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Composable und Listenlogik im vue-lab getestet (matchMedia im Test nachgebildet). Die visuelle Animation wurde nicht automatisiert geprüft.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Animationen sollen Bedeutung transportieren (neu, weg, verschoben), nicht dekorieren. Halte sie kurz (unter etwa 300 ms), vermeide Endlosschleifen und plane den Platzbedarf, damit sich nichts verschiebt, wenn Inhalt erscheint.\",\"exercises\":[{\"level\":1,\"task\":\"Baue eine Seite, auf der man Einträge hinzufügen und löschen kann. Prüfe im Browser die Animation. Schalte dann im Betriebssystem „Bewegung reduzieren“ ein und prüfe, dass sie entfällt.\",\"acceptance\":\"Mit Standardeinstellung: Einblenden/Ausblenden sichtbar; mit reduzierter Bewegung: keine Animation, Funktion bleibt.\"},{\"level\":2,\"task\":\"Grenzfall: Füge schnell hintereinander zehn Einträge hinzu. Ruckelt etwas? Was hilft?\",\"acceptance\":\"Beobachtung dokumentiert; transform/opacity-Hinweis und kurze Dauer sind als Maßnahmen genannt.\"},{\"level\":3,\"task\":\"Fehlerfall: Ersetze den Key durch den Index und lösche den ersten Eintrag. Beschreibe, welches Element animiert hinausfliegt.\",\"acceptance\":\"Falsches Element animiert hinaus; Erklärung nennt die verschobenen Keys.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/built-ins/transition.html\",\"title\":\"Vue: Transition und TransitionGroup\"},{\"url\":\"https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion\",\"title\":\"MDN: prefers-reduced-motion\"},{\"url\":\"https://www.w3.org/WAI/WCAG22/Techniques/css/C39\",\"title\":\"W3C WCAG 2.2: Technik C39 – prefers-reduced-motion\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Composable und Listenlogik im vue-lab getestet (matchMedia im Test nachgebildet). Die visuelle Animation wurde nicht automatisiert geprüft.\"},\"quiz\":[{\"q\":\"Warum animiert man bevorzugt transform und opacity?\",\"options\":[\"Weil andere CSS-Eigenschaften nicht animierbar sind.\",\"Weil sie das Layout nicht neu berechnen müssen und deshalb flüssig laufen.\",\"Weil Vue nur diese beiden Eigenschaften kennt.\"],\"correct\":1,\"explain\":\"transform und opacity sind günstig für den Browser und vermeiden Layout-Neuberechnung.\",\"rationales\":[\"Viele Eigenschaften sind animierbar; der Unterschied liegt im Aufwand.\",\"Layout-Eigenschaften wie width oder top lösen aufwendige Neuberechnungen aus.\",\"Vue setzt lediglich Klassen; was du animierst, entscheidet das CSS.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/transition.html\",\"https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion\",\"https://www.w3.org/WAI/WCAG22/Techniques/css/C39\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Ein Nutzer hat im Betriebssystem „Bewegung reduzieren“ aktiviert. Was ist die passende Reaktion der Anwendung?\",\"options\":[\"Alle Animationen verstärken, damit sie auffallen.\",\"Nicht wesentliche Animationen abschalten oder stark vereinfachen.\",\"Die Einstellung ignorieren, da Browser sie nicht auslesen können.\"],\"correct\":1,\"explain\":\"Die Einstellung respektieren: Bewegung abschalten oder reduzieren.\",\"rationales\":[\"Das wäre das Gegenteil des Nutzerwunsches.\",\"prefers-reduced-motion ist genau dafür gedacht und wird vom Browser bereitgestellt.\",\"Browser stellen die Einstellung über prefers-reduced-motion zur Verfügung.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/transition.html\",\"https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion\",\"https://www.w3.org/WAI/WCAG22/Techniques/css/C39\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Wozu dient onScopeDispose in usePrefersReducedMotion?\",\"options\":[\"Um den matchMedia-Listener aufzuräumen, wenn der Kontext (Komponente oder Scope) endet.\",\"Um die Animation zu beschleunigen, wenn die Komponente entfernt wird.\",\"Um den Wert der Einstellung dauerhaft im Browser zu speichern.\"],\"correct\":0,\"explain\":\"onScopeDispose beendet Listener und Ressourcen sauber.\",\"rationales\":[\"Ohne Aufräumen bliebe der Listener nach dem Unmount bestehen (Speicherleck).\",\"Mit der Geschwindigkeit hat der Hook nichts zu tun.\",\"Speichern ist nicht seine Aufgabe; er räumt auf.\"],\"sources\":[\"https://vuejs.org/guide/built-ins/transition.html\",\"https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion\",\"https://www.w3.org/WAI/WCAG22/Techniques/css/C39\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\nimport { usePrefersReducedMotion } from './usePrefersReducedMotion';\\n\\ndefineProps<{ items: readonly { id: number; label: string }[] }>();\\nconst reduced = usePrefersReducedMotion();\\n</script>\\n\\n<template>\\n  <!-- Stabile Keys sind Pflicht, sonst weiß TransitionGroup nicht, welches Element geht oder kommt. -->\\n  <TransitionGroup tag=\\\"ul\\\" :name=\\\"reduced ? '' : 'fade'\\\" :css=\\\"!reduced\\\">\\n    <li v-for=\\\"item in items\\\" :key=\\\"item.id\\\">{{ item.label }}</li>\\n  </TransitionGroup>\\n</template>\\n\\n<style scoped>\\n/* Nur transform und opacity animieren: Das vermeidet Layout-Neuberechnung. */\\n.fade-enter-active, .fade-leave-active { transition: opacity 0.2s ease, transform 0.2s ease; }\\n.fade-enter-from, .fade-leave-to { opacity: 0; transform: translateY(-6px); }\\n.fade-leave-active { position: absolute; }\\n.fade-move { transition: transform 0.2s ease; }\\n@media (prefers-reduced-motion: reduce) {\\n  .fade-enter-active, .fade-leave-active, .fade-move { transition: none; }\\n}\\n</style>\",\"codeLang\":\"Vue\",\"code2\":\"import { onScopeDispose, ref } from 'vue';\\n\\n// Lektion \\\"Transition und reduzierte Bewegung\\\": reagiert live auf die Systemeinstellung.\\nexport function usePrefersReducedMotion() {\\n  const reduced = ref(false);\\n  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return reduced;\\n\\n  const query = window.matchMedia('(prefers-reduced-motion: reduce)');\\n  reduced.value = query.matches;\\n  con";
RP_LITERAL_2_text += "st onChange = (event: MediaQueryListEvent) => { reduced.value = event.matches; };\\n  query.addEventListener('change', onChange);\\n  onScopeDispose(() => query.removeEventListener('change', onChange));\\n  return reduced;\\n}\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m2-l7\",\"title\":\"Generische Komponenten mit TypeScript\",\"minutes\":35,\"objectives\":[\"Eine Komponente mit generic=\\\"T …\\\" schreiben, die für unterschiedliche Datentypen funktioniert\",\"Mit einer Einschränkung (extends) erzwingen, dass jeder Typ eine id hat\",\"Den Typ T durch defineProps, defineModel und defineEmits laufen lassen\",\"Typfehler im Template mit vue-tsc und @vue-expect-error sichtbar und testbar machen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Eine Komponente mit generic=\\\"T …\\\" schreiben, die für unterschiedliche Datentypen funktioniert</li><li>Mit einer Einschränkung (extends) erzwingen, dass jeder Typ eine id hat</li><li>Den Typ T durch defineProps, defineModel und defineEmits laufen lassen</li><li>Typfehler im Template mit vue-tsc und @vue-expect-error sichtbar und testbar machen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Slots mit Vertrag“; TypeScript-Generics (js-m1-l7).</p><h2>In einfachen Worten</h2><p>Ein Auswahlfeld (&lt;select&gt;) braucht immer dasselbe: eine Liste von Optionen, eine Beschriftung und die gewählte Option. Ob die Optionen Projekte, Personen oder Länder sind, ist egal. Schreibst du es ohne Generics, verlierst du den Typ: Die gewählte Option ist „irgendein Objekt“.</p><p>Mit einem generischen Typ T sagst du: „Diese Komponente funktioniert für jeden Typ T, der mindestens eine id hat.“ Übergibt der Elternteil Projekte, ist T = Projekt, und überall (Beschriftungsfunktion, v-model, Ereignis) kennt TypeScript den echten Typ. Tippfehler wie p.nmae fallen sofort auf.</p><p>Wichtig zu verstehen: Diese Prüfung findet beim Entwickeln und Bauen statt (mit vue-tsc), nicht im Browser. Zur Laufzeit gibt es keine Typen mehr.</p><h2>Schritt für Schritt</h2><ol><li>&lt;script setup lang=\\\"ts\\\" generic=\\\"T extends { id: string | number }\\\"&gt; deklariert den Typparameter und die Einschränkung.</li><li>defineProps&lt;{ label: string; options: readonly T[]; getLabel: (option: T) =&gt; string }&gt;() verwendet T in den Props.</li><li>defineModel&lt;T | null&gt;() und defineEmits&lt;{ change: [option: T | null] }&gt;() geben denselben Typ weiter.</li><li>Der Vergleich der gewählten Option erfolgt über String(option.id), weil der Wert im DOM immer ein String ist. Das Beispiel prüft mit instanceof, dass das Ereignis von einem &lt;select&gt; kommt, statt mit einem Cast zu arbeiten.</li><li>ProjectPicker.vue zeigt die Verwendung. Dank Inferenz ist p im getLabel-Callback ein Project; p.name und p.archived sind geprüft.</li><li>Im selben Template steht ein bewusst falscher Aufruf mit Optionen ohne id, markiert mit dem Kommentar @vue-expect-error. vue-tsc besteht nur, wenn dort wirklich ein Typfehler vorliegt. So bleibt der Vertrag überprüfbar.</li><li>Erkenntnis aus dem Lab: mount() aus @vue/test-utils kann die Generics der Komponente nicht ableiten. Im Test wurde deshalb eine neutrale getLabel-Funktion verwendet; der Typvertrag wird über ProjectPicker und vue-tsc geprüft.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>SelectField.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>components/<wbr>ProjectPicker.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>npx vue-tsc --noEmit        -&gt; keine Fehler (der @vue-expect-error-Fall ist ein erwarteter Fehler)\\nvitest (Block „Slots und generische Komponenten“ / „Typinferenz im Template“): grün\\n - Auswahl \\\"2\\\" liefert Objekt Beta; Auswahl \\\"\\\" liefert null\\n - ProjectPicker rendert und zeigt \\\"Gewählt: Altprojekt\\\"</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> T ohne Einschränkung verwenden und dann option.id lesen.<br><strong>Warum:</strong> TypeScript weiß nicht, dass jeder Typ eine id hat, und meldet einen Fehler. Ein Cast würde das nur überdecken.<br><strong>Besser:</strong> Mit extends { id: string | number } die Mindestform erzwingen.</li><li><strong>Falsch:</strong> Mit „as“ casten, bis der Compiler schweigt (z. B. event.target as HTMLSelectElement).<br><strong>Warum:</strong> Ein Cast verspricht dem Compiler etwas, das niemand prüft. Stimmt es nicht, gibt es einen Laufzeitfehler.<br><strong>Besser:</strong> Mit instanceof oder einer Typprüfung einengen (wie im Beispiel) und Casts nur mit begründetem Hinweis verwenden.</li><li><strong>Falsch:</strong> Zu glauben, TypeScript prüfe Daten zur Laufzeit.<br><strong>Warum:</strong> Typen verschwinden beim Bauen. Daten aus dem Netz sind unknown, bis sie geprüft wurden (siehe Modul js-m3, Zod).<br><strong>Besser:</strong> Typen für die Entwicklungszeit, Schemas für Fremddaten zur Laufzeit.</li><li><strong>Falsch:</strong> Nur vite build auszuführen und Typfehler in Templates nicht zu prüfen.<br><strong>Warum:</strong> Vite baut ohne Typprüfung. Fehler in Templates sieht erst vue-tsc.<br><strong>Besser:</strong> vue-tsc --noEmit in Build und CI aufnehmen (im Lab ist es Teil von npm run build).</li></ul><h2>Praxis</h2><p>Generische Komponenten lohnen sich für wirklich wiederverwendbare Bausteine (Auswahl, Tabelle, Liste). Für einmalige Spezialfälle ist eine konkrete Komponente einfacher. Halte die Einschränkung so klein wie möglich: Je weniger T verlangt, desto vielseitiger bleibt die Komponente.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Verwende SelectField für eine Liste von Personen mit id und name. Beschrifte die Optionen mit „Name (id)“.<br><em>Abnahme:</em> Typgeprüfter Aufruf; vue-tsc ist grün; Auswahl liefert eine Person bzw. null.</li><li><strong>Grenzfall:</strong> Übergib Optionen mit id vom Typ number und andere vom Typ string in einer Liste. Funktioniert der Vergleich? Was passiert bei id 1 und \\\"1\\\"?<br><em>Abnahme:</em> Beide haben dieselbe String-Form; die Doppeldeutigkeit ist erklärt und eine eindeutige id-Regel vorgeschlagen.</li><li><strong>Fehlerfall:</strong> Entferne den Kommentar @vue-expect-error im Template. Was meldet vue-tsc? Stelle den Kommentar wieder her.<br><em>Abnahme:</em> Typfehler zu den Optionen ohne id wird gemeldet; mit Kommentar läuft die Prüfung wieder durch.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/guide/typescript/composition-api.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: TypeScript mit Composition API</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/api/sfc-script-setup.html#generics\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Generic Components (script setup)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>vue-tsc ohne Fehler (inklusive erwartetem @vue-expect-error); Tests im vue-lab grün. Das Verhalten von Typen im Editor (IDE) wurde nicht geprüft.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Generische Komponenten lohnen sich für wirklich wiederverwendbare Bausteine (Auswahl, Tabelle, Liste). Für einmalige Spezialfälle ist eine konkrete Komponente einfacher. Halte die Einschränkung so klein wie möglich: Je weniger T verlangt, desto vielseitiger bleibt die Komponente.\",\"exercises\":[{\"level\":1,\"task\":\"Verwende SelectField für eine Liste von Personen mit id und name. Beschrifte die Optionen mit „Name (id)“.\",\"acceptance\":\"Typgeprüfter Aufruf; vue-tsc ist grün; Auswahl liefert eine Person bzw. null.\"},{\"level\":2,\"task\":\"Grenzfall: Übergib Optionen mit id vom Typ number und andere vom Typ string in einer Liste. Funktioniert der Vergleich? Was passiert bei id 1 und \\\"1\\\"?\",\"acceptance\":\"Beide haben dieselbe String-Form; die Doppeldeutigkeit ist erklärt und eine eindeutige id-Regel vorgeschlagen.\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne den Kommentar @vue-expect-error im Template. Was meldet vue-tsc? Stelle den Kommentar wieder her.\",\"acceptance\":\"Typfehler zu den Optionen ohne id wird gemeldet; mit Kommentar läuft die Prüfung wieder durch.\"}],\"sources\":[{\"url\":\"https://vuejs.org/guide/typescript/composition-api.html\",\"title\":\"Vue: TypeScript mit Composition API\"},{\"url\":\"https://vuejs.org/api/sfc-script-setup.html#generics\",\"title\":\"Vue: Generic Components (script setup)\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"vue-tsc ohne Fehler (inklusive erwartetem @vue-expect-error); Tests im vue-lab grün. Das Verhalten von Typen im Editor (IDE) wurde nicht geprüft.\"},\"quiz\":[{\"q\":\"Was bewirkt generic=\\\"T extends { id: string | number }\\\" an einer Komponente?\",\"options\":[\"Sie akzeptiert jeden Typ T mit mindestens einer id; TypeScript leitet T aus den Props ab.\",\"Die Komponente prüft zur Laufzeit, ob jedes Objekt eine id hat.\",\"Die Komponente akzeptiert nur Objekte, deren id eine Zahl ist.\"],\"correct\":0,\"explain\":\"Generics + Einschränkung geben Typsicherheit für beliebige, aber passende Typen – zur Entwicklungszeit.\",\"rationales\":[\"So funktioniert ein eingeschränkter Typparameter; die Inferenz findet T beim Aufruf.\",\"Typen existieren zur Laufzeit nicht mehr; geprüft wird beim Bauen.\",\"Die Einschränkung erlaubt string und number als id.\"],\"sources\":[\"https://vuejs.org/guide/typescript/composition-api.html\",\"https://vuejs.org/api/sfc-script-setup.html#generics\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Wozu dient der Kommentar <!-- @vue-expect-error --> im Template?\",\"options\":[\"Er unterdrückt jeden Typfehler im Template, damit der Build durchläuft.\",\"Er erwartet an der folgenden Zeile einen Typfehler; fehlt dieser, schlägt vue-tsc fehl.\",\"Er blendet die folgende Zeile im Browser aus, wenn sie fehlerhaft ist.\"],\"correct\":1,\"explain\":\"@vue-expect-error macht Negativfälle der Typen prüfbar.\",\"rationales\":[\"Er unterdrückt nicht pauschal; er verlangt genau einen Fehler.\",\"So wird ein beabsichtigter Typfehler zum überprüfbaren Vertrag.\",\"Er beeinflusst die Darstellung im Browser nicht.\"],\"sources\":[\"https://vuejs.org/guide/typescript/composition-api.html\",\"https://vuejs.org/api/sfc-script-setup.html#generics\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum reicht ein grüner Vite-Build nicht als Nachweis, dass alle Typen in Templates stimmen?\",\"options\":[\"Vite führt keine Typprüfung durch; die übernimmt vue-tsc.\",\"Vite meldet Typfehler grundsätzlich nur als Warnung im Browser.\",\"Vite ignoriert alle .vue-Dateien.\"],\"correct\":0,\"explain\":\"Typprüfung braucht vue-tsc; Vite allein prüft keine Typen.\",\"rationales\":[\"Vite transpiliert ohne Typprüfung; deshalb gehört vue-tsc in den Build.\",\"Vite zeigt keine Typfehler an, weder als Warnung noch als Fehler.\",\"Vite verarbeitet .vue-Dateien normal (mit dem Vue-Plugin), nur eben ohne Typprüfung.\"],\"sources\":[\"https://vuejs.org/guide/typescript/composition-api.html\",\"https://vuejs.org/api/sfc-script-setup.html#generics\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\" generic=\\\"T extends { id: string | number }\\\">\\n// Lektion \\\"Generische Komponenten\\\": T wird aus den Props abgeleitet und fließt in v-model und Events.\\nconst props = defineProps<{\\n  label: string;\\n  options: readonly T[];\\n  getLabel: (option: T) => string;\\n}>();\\nconst selected = defineModel<T | null>({ default: null });\\nconst emit = defineEmits<{ change: [option: T | null] }>();\\n\\nfunction onChange(event: Event) {\\n  if (!(event.currentTarget instanceof HTMLSelectElement)) return;\\n  const id = event.currentTarget.value;\\n  // Vergleich über String(), weil option.value im DOM immer ein String ist.\\n  const option = props.options.find((candidate) => String(candidate.id) === id) ?? null;\\n  selected.value = option;\\n  emit('change', option);\\n}\\n</script>\\n\\n<template>\\n  <label>\\n    {{ label }}\\n    <select :value=\\\"selected === null ? '' : String(selected.id)\\\" @change=\\\"onChange\\\">\\n      <option value=\\\"\\\">– bitte wählen –</option>\\n      <option v-for=\\\"option in options\\\" :key=\\\"option.id\\\" :value=\\\"String(option.id)\\\">{{ getLabel(option) }}</option>\\n    </select>\\n  </label>\\n</template>\",\"codeLang\":\"Vue\",\"code2\":\"<script setup lang=\\\"ts\\\">\\n// Zeigt die Typinferenz: SelectField leitet T = Project ab, deshalb ist p.name im Template geprüft.\\nimport { ref } from 'vue';\\nimport SelectField from './SelectField.vue';\\n\\ninterface Project { id: number; name: string; archived: boolean }\\nconst projects: Project[] = [\\n  { id: 1, name: 'Website', archived: false },\\n  { id: 2, name: 'Altprojekt', archived: true },\\n];\\nconst current = ref<Project | null>(null);\\nconst withoutId = [{ name: 'ohne id' }];\\n</script>\\n\\n<template>\\n  <SelectField v-model=\\\"current\\\" label=\\\"Projekt\\\" :options=\\\"projects\\\" :get-label=\\\"(p) => p.name + (p.archived ? ' (archiviert)' : '')\\\" />\\n  <p v-if=\\\"current\\\">Gewählt: {{ current.name }}</p>\\n  <!-- @vue-expect-error Optionen ohne id verletzen die Einschränkung T extends { id } -->\\n  <SelectField label=\\\"Fehler\\\" :options=\\\"withoutId\\\" :get-label=\\\"(o) => o.name\\\" />\\n</template>\",\"code2Lang\":\"Vue\"}]},{\"id\":\"js-m3\",\"course\":\"javascript\",\"part\":23,\"partTitle\":\"JavaScript & Vue · Vollständiger Lernpfad\",\"title\":\"Vue-Formulare und Serverdaten · Zod, Query-Cache und Mini-Projekt\",\"lessons\":[{\"id\":\"js-m3-l1\",\"title\":\"Formulare mit Zod: ein Schema für Regeln und Typen\",\"minutes\":40,\"objectives\":[\"Erklären, warum ein Schema Regeln und TypeScript-Typen aus einer Quelle ableitet\",\"Ein Zod-4-Schema mit trim, Längen, Datumsformat, Vergleich und transform schreiben\",\"Den Unterschied zwischen Eingabetyp (z.input) und Ausgabetyp (z.output) nennen\",\"Fehler erst nach Blur oder Absenden zeigen, mit aria-invalid, aria-describedby und Fokus auf das erste fehlerhafte Feld\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, warum ein Schema Regeln und TypeScript-Typen aus einer Quelle ableitet</li><li>Ein Zod-4-Schema mit trim, Längen, Datumsformat, Vergleich und transform schreiben</li><li>Den Unterschied zwischen Eingabetyp (z.input) und Ausgabetyp (z.output) nennen</li><li>Fehler erst nach Blur oder Absenden zeigen, mit aria-invalid, aria-describedby und Fokus auf das erste fehlerhafte Feld</li></ul><p><strong>Voraussetzungen:</strong> Lektion „defineModel“ (js-m2-l1); Formulare und Barrierefreiheit (js-m1-l10).</p><h2>In einfachen Worten</h2><p>Ein Formular muss prüfen, was Menschen eintippen: Ist der Titel leer? Liegt das Datum in der Vergangenheit? Diese Regeln stehen oft doppelt im Code – einmal als Prüfung, einmal als TypeScript-Typ – und laufen irgendwann auseinander.</p><p>Zod ist eine Bibliothek, mit der du die Regeln einmal als Schema beschreibst. Aus dem Schema bekommst du zwei Dinge: eine Prüfung, die Fehlermeldungen liefert, und die passenden Typen. Der Typ der Rohwerte (z. B. dueDate ist ein Text, leer erlaubt) unterscheidet sich vom Typ der geprüften Daten (dueDate ist Datum oder null). Zod kennt beide.</p><p>Für Menschen zählt die Bedienung: Fehler erscheinen nicht schon beim ersten Tastendruck, sondern nach dem Verlassen des Felds oder beim Absenden. Beim Absenden springt der Fokus zum ersten fehlerhaften Feld, und die Eingaben bleiben erhalten.</p><h2>Schritt für Schritt</h2><ol><li>z.string().trim().min(1).max(120) entfernt zuerst Leerzeichen und prüft dann Länge. Nur Leerzeichen ergeben also „Titel darf nicht leer sein“.</li><li>Fehlermeldungen setzt du in Zod 4 mit der Option error (statt message in älteren Versionen).</li><li>z.iso.date() prüft das Format JJJJ-MM-TT (Zod 4). Mit z.union([z.literal(\\\"\\\"), …]) darf das Feld auch leer bleiben.</li><li>.refine(...) vergleicht das Datum mit „heute“. today ist ein Parameter, damit Tests nicht von der Systemuhr abhängen. todayIso() bildet das lokale Datum, nicht UTC.</li><li>.transform(...) wandelt \\\"\\\" in null, so wie die API es erwartet. z.input liefert den Rohtyp, z.output den geprüften Typ.</li><li>validateTaskForm nutzt safeParse (wirft nicht) und reduziert die Probleme auf eine Meldung pro Feld: eine Korrektur nach der anderen.</li><li>TaskForm.vue zeigt Fehler erst nach Blur oder Absenden (shown-Menge), verknüpft sie mit aria-describedby, setzt aria-invalid und fokussiert beim Absenden das erste ungültige Feld. novalidate schaltet die Browser-Meldungen ab, damit nur unsere gelten.</li><li>Die Tests prüfen: Normalfall, Grenzfälle (120 vs. 121 Zeichen, heute vs. gestern), Fehlerfälle und die Zugänglichkeits-Attribute.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>forms/<wbr>taskSchema.ts</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>forms/<wbr>TaskForm.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Blöcke „Zod-Schema“ und „TaskForm (Zugänglichkeit)“): 7 Tests grün\\n - Normalfall: \\\"  Einkaufen  \\\" + \\\"\\\" -&gt; { title: \\\"Einkaufen\\\", dueDate: null }\\n - Grenzfälle: 120 Zeichen ok, 121 nicht; heute ok, gestern nicht\\n - Fehlerfälle: nur Leerzeichen, falsches Datumsformat, falsche Typen\\n - Fehler erst nach Blur; aria-invalid und aria-describedby gesetzt; Eingabe bleibt\\n - Absenden mit Fehler: Fokus auf dem ersten ungültigen Feld, kein submit-Ereignis</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Regeln einmal im Schema und noch einmal von Hand im Formular schreiben.<br><strong>Warum:</strong> Beide Stellen laufen auseinander; der Nutzer sieht andere Regeln als der Server verlangt.<br><strong>Besser:</strong> Das Schema als einzige Quelle verwenden und Typen mit z.input/z.output daraus ableiten.</li><li><strong>Falsch:</strong> Fehler schon beim ersten Tastendruck anzeigen.<br><strong>Warum:</strong> Menschen sehen Fehler, bevor sie fertig getippt haben. Das stört und kann Screenreader mit Meldungen überfluten.<br><strong>Besser:</strong> Erst nach Blur oder Absenden zeigen; danach live aktualisieren.</li><li><strong>Falsch:</strong> Fehler nur rot einfärben.<br><strong>Warum:</strong> Farbe allein erreicht nicht alle Menschen und verletzt WCAG 2.2.<br><strong>Besser:</strong> Text, aria-invalid=\\\"true\\\" und aria-describedby verwenden; beim Absenden Fokus auf das erste fehlerhafte Feld setzen.</li><li><strong>Falsch:</strong> Heute mit new Date().toISOString().slice(0, 10) bestimmen.<br><strong>Warum:</strong> toISOString liefert UTC. Abends in Deutschland kann das schon das Datum von morgen sein oder morgens das von gestern.<br><strong>Besser:</strong> Lokale Datumsteile (getFullYear, getMonth, getDate) verwenden, wie todayIso() es tut.</li><li><strong>Falsch:</strong> Der Prüfung im Browser als Schutz vertrauen.<br><strong>Warum:</strong> Clientseitige Validierung ist Komfort. Wer die API direkt aufruft, umgeht sie.<br><strong>Besser:</strong> Der Server prüft immer selbst (siehe Spring-Lab, Fehlervertrag) und der Client zeigt dessen Feldfehler an (Lektion 5).</li></ul><h2>Praxis</h2><p>Formulare sind klein, aber heikel: Beschriftung, Fehlermeldung, Fokus, Eingabe behalten. Prüfe sie immer auch mit der Tastatur. Der Autotest findet nur einen Teil der Probleme; die vollständige Zugänglichkeit braucht einen manuellen Durchgang.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze ein Feld „Priorität“ (niedrig, mittel, hoch) im Schema mit z.enum und gib die Fehlermeldung auf Deutsch aus.<br><em>Abnahme:</em> Ungültiger Wert wird abgelehnt; der Typ TaskFormData enthält die drei Werte als Union.</li><li><strong>Grenzfall:</strong> Teste den Titel mit 120 und 121 Zeichen sowie „ä“ am Ende. Wie zählt Zod die Länge bei Emojis? Notiere die Beobachtung.<br><em>Abnahme:</em> 120 ok, 121 Fehler; Hinweis dokumentiert, dass Länge in UTF-16-Einheiten gezählt wird und ein Emoji mehrere zählt.</li><li><strong>Fehlerfall:</strong> Tippe im Browser einen leeren Titel und sende ab. Prüfe mit der Tastatur: Fokus, Fehlertext, Screenreader-Ansage (falls verfügbar).<br><em>Abnahme:</em> Fokus liegt auf dem Titelfeld; der Fehlertext ist mit dem Feld verknüpft; Beobachtungen aus dem echten Browser notiert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://zod.dev/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Zod: Dokumentation (Grundlagen, Schemas, Fehler)</a> – Zod steht unter MIT-Lizenz; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://www.w3.org/WAI/tutorials/forms/validation/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">W3C: WAI-Tutorial Formulare – Validierung</a> – W3C-Tutorial; nur verlinkt und zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab (zod 4.6.7, Vitest 5.1.0, jsdom) grün; vue-tsc fehlerfrei. Screenreader-Verhalten und echte Tastaturbedienung wurden nicht automatisiert geprüft.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Formulare sind klein, aber heikel: Beschriftung, Fehlermeldung, Fokus, Eingabe behalten. Prüfe sie immer auch mit der Tastatur. Der Autotest findet nur einen Teil der Probleme; die vollständige Zugänglichkeit braucht einen manuellen Durchgang.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze ein Feld „Priorität“ (niedrig, mittel, hoch) im Schema mit z.enum und gib die Fehlermeldung auf Deutsch aus.\",\"acceptance\":\"Ungültiger Wert wird abgelehnt; der Typ TaskFormData enthält die drei Werte als Union.\"},{\"level\":2,\"task\":\"Grenzfall: Teste den Titel mit 120 und 121 Zeichen sowie „ä“ am Ende. Wie zählt Zod die Länge bei Emojis? Notiere die Beobachtung.\",\"acceptance\":\"120 ok, 121 Fehler; Hinweis dokumentiert, dass Länge in UTF-16-Einheiten gezählt wird und ein Emoji mehrere zählt.\"},{\"level\":3,\"task\":\"Fehlerfall: Tippe im Browser einen leeren Titel und sende ab. Prüfe mit der Tastatur: Fokus, Fehlertext, Screenreader-Ansage (falls verfügbar).\",\"acceptance\":\"Fokus liegt auf dem Titelfeld; der Fehlertext ist mit dem Feld verknüpft; Beobachtungen aus dem echten Browser notiert.\"}],\"sources\":[{\"url\":\"https://zod.dev/\",\"title\":\"Zod: Dokumentation (Grundlagen, Schemas, Fehler)\"},{\"url\":\"https://www.w3.org/WAI/tutorials/forms/validation/\",\"title\":\"W3C: WAI-Tutorial Formulare – Validierung\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab (zod 4.6.7, Vitest 5.1.0, jsdom) grün; vue-tsc fehlerfrei. Screenreader-Verhalten und echte Tastaturbedienung wurden nicht automatisiert geprüft.\"},\"quiz\":[{\"q\":\"Was ist der Vorteil, Regeln und Typen aus einem Zod-Schema abzuleiten?\",\"options\":[\"Es gibt nur eine Quelle der Wahrheit; Regeln und Typen können nicht auseinanderlaufen.\",\"Zod macht eine Prüfung auf dem Server überflüssig, weil das Schema ausreicht.\",\"TypeScript prüft die Daten dadurch auch zur Laufzeit im Browser.\"],\"correct\":0,\"explain\":\"Ein Schema vermeidet doppelte Regeln und doppelte Typen.\",\"rationales\":[\"Das Schema liefert Prüfung und Typen gemeinsam.\",\"Der Server muss immer selbst prüfen; Clientprüfung ist nur Komfort.\",\"Typen verschwinden beim Bauen; Zod prüft Werte zur Laufzeit, TypeScript nicht.\"],\"sources\":[\"https://zod.dev/\",\"https://www.w3.org/WAI/tutorials/forms/validation/\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum wird „heute“ in todayIso() mit lokalen Datumsteilen gebildet?\",\"options\":[\"toISOString() liefert UTC; das Datum kann je nach Uhrzeit um einen Tag abweichen.\",\"Lokale Datumsteile sind schneller zu berechnen als ein ISO-String.\",\"Zod verlangt für Datumsprüfungen zwingend lokale Datumsteile.\"],\"correct\":0,\"explain\":\"Für „heute“ des Nutzers zählt das lokale Datum.\",\"rationales\":[\"Rund um Mitternacht fällt UTC und Ortszeit auseinander; die Prüfung wäre falsch.\",\"Geschwindigkeit spielt hier keine Rolle.\",\"Zod verlangt das nicht; es ist eine fachliche Entscheidung.\"],\"sources\":[\"https://zod.dev/\",\"https://www.w3.org/WAI/tutorials/forms/validation/\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Beim Absenden sind mehrere Felder ungültig. Was ist für Tastatur- und Screenreader-Nutzer die beste Reaktion?\",\"options\":[\"Alle fehlerhaften Felder rot einfärben und sonst nichts weiter verändern.\",\"Fokus auf das erste ungültige Feld setzen, Fehlertext per aria-describedby verknüpfen, Eingaben behalten.\",\"Die Seite neu laden, damit das Formular wieder leer und fehlerfrei beginnt.\"],\"correct\":1,\"explain\":\"Fokus, Textfehler und erhaltene Eingaben sind die Grundlage zugänglicher Fehlerbehandlung.\",\"rationales\":[\"Farbe allein ist nicht zugänglich, und der Fokus bleibt irgendwo.\",\"So finden Nutzer den Fehler sofort und können ihn beheben.\",\"Verlorene Eingaben sind eines der größten Ärgernisse in Formularen.\"],\"sources\":[\"https://zod.dev/\",\"https://www.w3.org/WAI/tutorials/forms/validation/\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"import * as z from 'zod';\\n\\n// Lektion \\\"Formulare mit Zod\\\": Das Schema ist die einzige Quelle für Regeln UND Typen.\\nexport function todayIso(now: Date = new Date()): string {\\n  const pad = (value: number) => String(value).padStart(2, '0');\\n  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;   // lokales Datum, nicht UTC\\n}\\n\\nexport function createTaskFormSchema(today: string = todayIso()) {\\n  return z.object({\\n    title: z.string()\\n      .trim()                                                         // Leerzeichen vor der Prüfung entfernen\\n      .min(1, { error: 'Titel darf nicht leer sein' })\\n      .max(120, { error: 'Titel darf höchstens 120 Zeichen haben' }),\\n    dueDate: z.union([z.literal(''), z.iso.date({ error: 'Datum im Format JJJJ-MM-TT eingeben' })])\\n      .refine((value) => value === '' || value >= today, { error: 'Fälligkeit darf nicht in der Vergangenheit liegen' })\\n      .transform((value) => (value === '' ? null : value)),          // \\\"\\\" aus dem Formular wird zu null für die API\\n  });\\n}\\n\\nexport type TaskFormInput = z.input<ReturnType<typeof createTaskFormSchema>>;    // Rohwerte aus den Eingabefeldern\\nexport type TaskFormData = z.output<ReturnType<typeof createTaskFormSchema>>;    // geprüfte Daten für die API\\nexport type FieldErrors = Partial<Record<keyof TaskFormInput, string>>;\\n\\nexport type ValidationResult =\\n  | { ok: true; data: TaskFormData }\\n  | { ok: false; errors: FieldErrors };\\n\\nexport function validateTaskForm(raw: unknown, today?: string): ValidationResult {\\n  const result = createTaskFormSchema(today).safeParse(raw);\\n  if (result.success) return { ok: true, data: result.data };\\n  const errors: FieldErrors = {};\\n  for (const issue of result.error.issues) {\\n    const field = issue.path[0];\\n    // Nur die erste Meldung je Feld zeigen: eine Korrektur nach der anderen.\\n    if ((field === 'title' || field === 'dueDate') && !errors[field]) errors[field] = issue.message;\\n  }\\n  return { ok: false, errors };\\n}\",\"codeLang\":\"TypeScript\",\"code2\":\"<script setup lang=\\\"ts\\\">\\nimport { computed, nextTick, reactive, ref, watch } from 'vue';\\nimport { validateTaskForm, type FieldErrors, type TaskFormData, type TaskFormInput } from './taskSchema';\\n\\nconst props = defineProps<{ submitting?: boolean; serverErrors?: FieldErrors; today?: string }>();\\nconst emit = defineEmits<{ submit: [data: TaskFormData] }>();\\n\\nconst values = reactive<TaskFormInput>({ title: '', dueDate: '' });\\nconst shown = ref(new Set<keyof TaskFormInput>());               // Fehler erst nach Blur oder Submit zeigen\\nconst root = ref<HTMLFormElement | null>(null);\\n\\nconst clientErrors = computed<FieldErrors>(() => {\\n  const result = validateTaskForm(values, props.today);\\n  return result.ok ? {} : result.errors;\\n});\\nconst errors = computed<FieldErrors>(() => {\\n  const visible: FieldErrors = {};\\n  for (const field of ['title', 'dueDate'] as const) {\\n    const message = props.serverErrors?.[field] ?? (shown.value.has(field) ? clientErrors.value[field] : undefined);\\n    if (message) visible[field] = message;\\n  }\\n  return visible;\\n});\\n\\nfunction touch(field: keyof TaskFormInput) { shown.value = new Set(shown.value).add(field); }\\n\\nasync function focusFirstInvalid() {\\n  await nextTick();\\n  root.value?.querySelector<HTMLElement>('[aria-invalid=\\\"true\\\"]')?.focus();\\n}\\n\\nfunction onSubmit() {\\n  touch('title'); touch('dueDate');\\n  const result = validateTaskForm(values, props.today);\\n  if (!result.ok) { void focusFirstInvalid(); return; }          // Eingaben bleiben erhalten\\n  emit('submit', result.data);\\n}\\n\\nwatch(() => props.serverErrors, (next) => { if (next && Object.keys(next).length) void focusFirstInvalid(); });\\n</script>\\n\\n<template>\\n  <form ref=\\\"root\\\" novalidate @submit.prevent=\\\"onSubmit\\\">\\n    <p>\\n      <label for=\\\"task-title\\\">Titel</label>\\n      <input id=\\\"task-title\\\" v-model=\\\"values.title\\\" autocomplete=\\\"off\\\" :aria-invalid=\\\"errors.title ? 'true' : undefined\\\"\\n        :aria-describedby=\\\"errors.title ? 'task-title-error' : undefined\\\" @blur=\\\"touch('title')\\\">\\n      <span v-if=\\\"errors.title\\\" id=\\\"task-title-error\\\">{{ errors.title }}</span>\\n    </p>\\n    <p>\\n      <label for=\\\"task-due\\\">Fällig am (optional)</label>\\n      <input id=\\\"task-due\\\" v-model=\\\"values.dueDate\\\" type=\\\"date\\\" :aria-invalid=\\\"errors.dueDate ? 'true' : undefined\\\"\\n        :aria-describedby=\\\"errors.dueDate ? 'task-due-error' : undefined\\\" @blur=\\\"touch('dueDate')\\\">\\n      <span v-if=\\\"errors.dueDate\\\" id=\\\"task-due-error\\\">{{ errors.dueDate }}</span>\\n    </p>\\n    <button type=\\\"submit\\\" :disabled=\\\"submitting\\\">{{ submitting ? 'Wird gespeichert …' : 'Aufgabe anlegen' }}</button>\\n  </form>\\n</template>\",\"code2Lang\":\"Vue\"},{\"id\":\"js-m3-l2\",\"title\":\"Serverdaten und Query-Cache mit TanStack Query\",\"minutes\":45,\"objectives\":[\"Unterscheiden zwischen Serverzustand (gehört dem Server, kann veralten) und UI-Zustand (gehört der Oberfläche)\",\"Antworten an der Grenze mit einem Schema prüfen und Fehler im RFC-9457-Format in einen ApiError übersetzen\",\"Mit useQuery Daten laden, zwischenspeichern und Schlüssel (queryKey) fachlich benennen\",\"staleTime, placeholderData und Invalidierung nach einer Mutation erklären\"],\"body\":\"<h2>Lernziele</h2><ul><li>Unterscheiden zwischen Serverzustand (gehört dem Server, kann veralten) und UI-Zustand (gehört der Oberfläche)</li><li>Antworten an der Grenze mit einem Schema prüfen und Fehler im RFC-9457-Format in einen ApiError übersetzen</li><li>Mit useQuery Daten laden, zwischenspeichern und Schlüssel (queryKey) fachlich benennen</li><li>staleTime, placeholderData und Invalidierung nach einer Mutation erklären</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Formulare mit Zod“; Promises (js-m1-l4), fetch (js-m1-l5) und API-Zustände (js-m1-l11).</p><h2>In einfachen Worten</h2><p>Daten vom Server sind „geliehen“: Sie können sich jederzeit ändern. Ein Query-Cache wie TanStack Query nimmt dir die lästige Handarbeit ab. Er merkt sich Antworten unter einem Schlüssel, zeigt sofort Gespeichertes an, lädt bei Bedarf im Hintergrund nach und kümmert sich um Lade- und Fehlerzustand.</p><p>Zwei Regeln helfen. Erstens: Jede Antwort ist unknown, bis ein Schema sie bestätigt hat. Ein Server kann sich irren, eine neue Version ausliefern oder ein Proxy kann HTML statt JSON schicken. Zweitens: Der Schlüssel beschreibt die Daten („Aufgaben, Seite 2“), nicht den Aufruf. Ändert sich die Seite, entsteht ein neuer Cache-Eintrag.</p><p>Nach einer Änderung (Aufgabe anlegen) sagst du dem Cache: „Alles zu tasks ist veraltet.“ Er lädt die sichtbaren Daten neu.</p><h2>Schritt für Schritt</h2><ol><li>taskSchema und taskPageSchema beschreiben den Vertrag der API. schema.parse(await response.json()) wirft bei Vertragsbruch; ungeprüfte Antworten werden nie weitergereicht.</li><li>Fehlerantworten (nicht 2xx) werden als RFC-9457-„Problem Details“ gelesen (problemSchema). Daraus entsteht ein ApiError mit status, problem und fieldErrors (erste Meldung je Feld). Das passt zum Spring-Lab (Lektion java-m26-l3).</li><li>createTasksApi(fetcher) bekommt fetch als Parameter. So kann der Test ein In-Memory-„Backend“ (fakeServer.ts) mit echten Response-Objekten einsetzen, ohne Netzwerk.</li><li>taskKeys.page(page) ist ein Schlüssel mit einer ref. Ändert sich page, lädt useQuery automatisch die neue Seite und legt einen neuen Cache-Eintrag an.</li><li>queryFn erhält ein signal (AbortSignal): Wird eine Abfrage überholt, bricht der fetch sauber ab.</li><li>staleTime: 30_000 bedeutet: 30 Sekunden gelten die Daten als frisch; beim Zurücknavigieren gibt es keinen neuen Request.</li><li>placeholderData: keepPreviousData zeigt beim Blättern die alte Seite weiter, bis die neue da ist. Das vermeidet Flackern; isPlaceholderData verrät, dass die Daten noch alt sind.</li><li>useCreateTask ruft nach Erfolg invalidateQueries({ queryKey: taskKeys.all }) auf. Alle Seiten gelten als veraltet; sichtbare werden neu geladen.</li><li>Die Tests belegen: frische Daten kommen aus dem Cache (kein zweiter GET), nach Invalidierung wird neu geladen, RFC-9457-Fehler werden zu ApiError und ein Vertragsbruch wird abgelehnt.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>data/<wbr>tasksApi.ts</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>data/<wbr>queries.ts</code> (Ausschnitt ab „export const taskKeys“)</li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Blöcke „API-Grenze“ und „Query-Cache“): grün\\n - 422 + application/problem+json -&gt; ApiError(status 422, fieldErrors { title: \\\"Titel existiert bereits\\\" })\\n - Antwort { items: [{ id: \\\"x\\\" }] } -&gt; abgelehnt (Vertragsbruch)\\n - frische Daten aus dem Cache: kein zweiter GET; nach Invalidierung: neuer GET</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Serverdaten in einen eigenen Store kopieren und selbst aktuell halten.<br><strong>Warum:</strong> Du baust Cache, Wiederholung, Abbruch und Invalidierung selbst nach – und machst dabei Fehler.<br><strong>Besser:</strong> Serverzustand dem Query-Cache überlassen; UI-Zustand (Dialog offen, Eingabe) bleibt lokal oder im Store.</li><li><strong>Falsch:</strong> Antworten mit „as Task[]“ in einen Typ zu zwingen.<br><strong>Warum:</strong> Ein Cast prüft nichts. Ändert der Server sein Format, bricht die Anwendung später an einer unerwarteten Stelle.<br><strong>Besser:</strong> An der Grenze mit einem Schema parsen und bei Fehler abbrechen.</li><li><strong>Falsch:</strong> Einen Schlüssel wie [\\\"load\\\"] verwenden und die Seite nicht aufnehmen.<br><strong>Warum:</strong> Alle Seiten teilen einen Cache-Eintrag; man sieht falsche Daten.<br><strong>Besser:</strong> Alles, wovon das Ergebnis abhängt, gehört in den Schlüssel (Seite, Filter, Sortierung).</li><li><strong>Falsch:</strong> staleTime: 0 beibehalten und sich über viele Requests wundern.<br><strong>Warum:</strong> Standardmäßig gelten Daten sofort als veraltet und werden bei vielen Ereignissen neu geladen.<br><strong>Besser:</strong> staleTime bewusst wählen: wie lange ist „alt“ fachlich okay? Dann Mutationen gezielt invalidieren.</li><li><strong>Falsch:</strong> Den Fehlerfall nur in der Konsole behandeln.<br><strong>Warum:</strong> Nutzer sehen eine leere Seite oder ewiges Laden.<br><strong>Besser:</strong> Lade-, Fehler- und Leerzustand sichtbar machen (Lektion 5) und ein erneutes Versuchen anbieten.</li></ul><h2>Praxis</h2><p>Frage bei jedem Datum: Wem gehört es? Gehört es dem Server, dann in den Query-Cache. Gehört es der Oberfläche, dann ref/Store. Halte Schlüssel in einer Datei zusammen (taskKeys), damit Invalidierung nicht an Tippfehlern scheitert. Beachte beim Einsatz echter APIs zusätzlich Authentifizierung und CSRF-Schutz auf Serverseite; sie sind nicht Teil dieser Lektion.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Füge der API ein Feld „priority“ hinzu: Schema anpassen, Fake-Server anpassen, Test ergänzen.<br><em>Abnahme:</em> Alte Antworten ohne Feld werden abgelehnt (oder bewusst mit Standardwert akzeptiert); Entscheidung dokumentiert.</li><li><strong>Grenzfall:</strong> Setze staleTime auf 0 und beobachte im Test die Anzahl der GET-Aufrufe beim Zurückblättern. Vergleiche mit 30 s.<br><em>Abnahme:</em> Zahlen der Aufrufe notiert; Zusammenhang zwischen staleTime und Requests erklärt.</li><li><strong>Fehlerfall:</strong> Lass den Fake-Server HTML statt JSON liefern. Was passiert in request()? Welche Meldung sieht der Nutzer?<br><em>Abnahme:</em> Fehler wird abgefangen (kein ungeprüftes Weiterreichen); der Nutzer sieht den Fehlerzustand mit Wiederholungs-Schaltfläche.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://tanstack.com/query/latest/docs/framework/vue/overview\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">TanStack Query (Vue): Überblick und Quick Start</a> – TanStack Query steht unter MIT-Lizenz; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://tanstack.com/query/latest/docs/framework/vue/guides/important-defaults\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">TanStack Query: Important Defaults (staleTime, gcTime)</a> – Offizielle Dokumentation; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://www.rfc-editor.org/rfc/rfc9457.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">RFC 9457: Problem Details for HTTP APIs</a> – IETF-Standard; nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab (@tanstack/vue-query 5.107.1, zod 4.6.7) grün; kein echtes Netzwerk, sondern ein In-Memory-Fake-Server mit echten Response-Objekten.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Frage bei jedem Datum: Wem gehört es? Gehört es dem Server, dann in den Query-Cache. Gehört es der Oberfläche, dann ref/Store. Halte Schlüssel in einer Datei zusammen (taskKeys), damit Invalidierung nicht an Tippfehlern scheitert. Beachte beim Einsatz echter APIs zusätzlich Authentifizierung und CSRF-Schutz auf Serverseite; sie sind nicht Teil dieser Lektion.\",\"exercises\":[{\"level\":1,\"task\":\"Füge der API ein Feld „priority“ hinzu: Schema anpassen, Fake-Server anpassen, Test ergänzen.\",\"acceptance\":\"Alte Antworten ohne Feld werden abgelehnt (oder bewusst mit Standardwert akzeptiert); Entscheidung dokumentiert.\"},{\"level\":2,\"task\":\"Grenzfall: Setze staleTime auf 0 und beobachte im Test die Anzahl der GET-Aufrufe beim Zurückblättern. Vergleiche mit 30 s.\",\"acceptance\":\"Zahlen der Aufrufe notiert; Zusammenhang zwischen staleTime und Requests erklärt.\"},{\"level\":3,\"task\":\"Fehlerfall: Lass den Fake-Server HTML statt JSON liefern. Was passiert in request()? Welche Meldung sieht der Nutzer?\",\"acceptance\":\"Fehler wird abgefangen (kein ungeprüftes Weiterreichen); der Nutzer sieht den Fehlerzustand mit Wiederholungs-Schaltfläche.\"}],\"sources\":[{\"url\":\"https://tanstack.com/query/latest/docs/framework/vue/overview\",\"title\":\"TanStack Query (Vue): Überblick und Quick Start\"},{\"url\":\"https://tanstack.com/query/latest/docs/framework/vue/guides/important-defaults\",\"title\":\"TanStack Query: Important Defaults (staleTime, gcTime)\"},{\"url\":\"https://www.rfc-editor.org/rfc/rfc9457.html\",\"title\":\"RFC 9457: Problem Details for HTTP APIs\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab (@tanstack/vue-query 5.107.1, zod 4.6.7) grün; kein ech";
RP_LITERAL_2_text += "tes Netzwerk, sondern ein In-Memory-Fake-Server mit echten Response-Objekten.\"},\"quiz\":[{\"q\":\"Warum gehört der Seitenwert in den queryKey?\",\"options\":[\"Damit jede Seite einen eigenen Cache-Eintrag hat und bei Änderung automatisch neu geladen wird.\",\"Damit der Schlüssel länger wird und dadurch seltener mit anderen kollidiert.\",\"Weil ohne Seitenwert überhaupt keine Anfrage an den Server gesendet wird.\"],\"correct\":0,\"explain\":\"Alles, wovon das Ergebnis abhängt, gehört in den Schlüssel.\",\"rationales\":[\"Der Schlüssel beschreibt die Daten; Abhängigkeiten gehören hinein.\",\"Länge ist kein Ziel; der Schlüssel beschreibt die Daten.\",\"Anfragen werden auch ohne Seitenwert gesendet, nur mit falscher Zuordnung.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/overview\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/important-defaults\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Was bewirkt staleTime: 30_000?\",\"options\":[\"Daten werden nach 30 Sekunden aus dem Cache gelöscht und neu geladen.\",\"Daten gelten 30 Sekunden als frisch; in dieser Zeit löst Anzeigen keinen neuen Request aus.\",\"Abfragen werden nach dem Auslösen 30 Sekunden verzögert an den Server gesendet.\"],\"correct\":1,\"explain\":\"staleTime legt fest, wie lange Daten als aktuell gelten.\",\"rationales\":[\"Gelöscht werden Daten über gcTime, nicht über staleTime.\",\"So steht es in der Dokumentation: frische Daten werden aus dem Cache bedient.\",\"Verzögert wird nichts; es geht um Frische.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/overview\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/important-defaults\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Ein Server liefert plötzlich ein anderes JSON-Format. Wie verhindert die Schema-Prüfung Folgeschäden?\",\"options\":[\"Sie wandelt die Daten automatisch in das alte Format um.\",\"Sie wirft an der Grenze einen Fehler; die Oberfläche zeigt den Fehlerzustand.\",\"Sie ignoriert unbekannte Antworten und zeigt eine leere Seite.\"],\"correct\":1,\"explain\":\"Schema-Prüfung macht Vertragsbrüche sofort sichtbar.\",\"rationales\":[\"Ein Schema kennt kein altes Format und rät nicht.\",\"Fehler früh und sichtbar zu machen ist der Sinn der Prüfung an der Grenze.\",\"Stilles Ignorieren verschleiert den Fehler.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/overview\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/important-defaults\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"import * as z from 'zod';\\nimport type { TaskFormData } from '../forms/taskSchema';\\n\\n// Lektion \\\"Serverdaten\\\": Fremde Antworten sind unknown, bis ein Schema sie bestätigt.\\nexport const taskSchema = z.object({\\n  id: z.number().int().positive(),\\n  title: z.string().min(1).max(120),\\n  done: z.boolean(),\\n  dueDate: z.iso.date().nullable(),\\n});\\nexport const taskPageSchema = z.object({\\n  items: z.array(taskSchema).max(100),\\n  page: z.number().int().min(1),\\n  totalPages: z.number().int().min(1),\\n});\\nexport type Task = z.infer<typeof taskSchema>;\\nexport type TaskPage = z.infer<typeof taskPageSchema>;\\n\\n// RFC 9457 \\\"Problem Details\\\": Das Spring-Lab (ProblemDetail) liefert genau diese Form.\\nconst problemSchema = z.object({\\n  type: z.string().optional(),\\n  title: z.string().optional(),\\n  status: z.number().optional(),\\n  detail: z.string().optional(),\\n  violations: z.array(z.object({ field: z.string(), message: z.string() })).optional(),\\n});\\nexport type Problem = z.infer<typeof problemSchema>;\\n\\nexport class ApiError extends Error {\\n  constructor(readonly status: number, readonly problem: Problem | null) {\\n    super(problem?.title ?? `HTTP ${status}`);\\n  }\\n  /** Feldbezogene Serverfehler; je Feld die erste Meldung. */\\n  get fieldErrors(): Record<string, string> {\\n    const result: Record<string, string> = {};\\n    for (const { field, message } of this.problem?.violations ?? []) result[field] ??= message;\\n    return result;\\n  }\\n}\\n\\nexport function createTasksApi(fetcher: typeof fetch = fetch, baseUrl = '/api/tasks') {\\n  async function request<S extends z.ZodType>(url: string, init: RequestInit, schema: S): Promise<z.output<S>> {\\n    const response = await fetcher(url, { ...init, headers: { Accept: 'application/json, application/problem+json', ...init.headers } });\\n    if (!response.ok) {\\n      const parsed = problemSchema.safeParse(await response.json().catch(() => null));\\n      throw new ApiError(response.status, parsed.success ? parsed.data : null);\\n    }\\n    return schema.parse(await response.json());                 // wirft bei Vertragsbruch, nie ungeprüft weiterreichen\\n  }\\n  const json = { 'Content-Type': 'application/json' };\\n  return {\\n    list: (page: number, options: { signal?: AbortSignal } = {}) =>\\n      request(`${baseUrl}?page=${page}&size=5`, { signal: options.signal }, taskPageSchema),\\n    create: (data: TaskFormData) =>\\n      request(baseUrl, { method: 'POST', headers: json, body: JSON.stringify(data) }, taskSchema),\\n    setDone: (id: number, done: boolean) =>\\n      request(`${baseUrl}/${id}`, { method: 'PATCH', headers: json, body: JSON.stringify({ done }) }, taskSchema),\\n  };\\n}\\nexport type TasksApi = ReturnType<typeof createTasksApi>;\",\"codeLang\":\"TypeScript\",\"code2\":\"export const taskKeys = {\\n  all: ['tasks'] as const,\\n  page: (page: Ref<number>) => ['tasks', 'page', page] as const,    // ref im Schlüssel: neue Seite = neuer Cache-Eintrag\\n};\\n\\nexport function useTasksQuery(api: TasksApi, page: Ref<number>) {\\n  return useQuery({\\n    queryKey: taskKeys.page(page),\\n    queryFn: ({ signal }) => api.list(page.value, { signal }),\\n    staleTime: 30_000,                          // 30 s gelten als frisch: kein erneuter Request beim Zurücknavigieren\\n    placeholderData: keepPreviousData,          // beim Blättern die alte Seite anzeigen statt Ladeflackern\\n  });\\n}\\n\\nexport function useCreateTask(api: TasksApi) {\\n  const queryClient = useQueryClient();\\n  return useMutation({\\n    mutationFn: (data: TaskFormData) => api.create(data),\\n    onSuccess: () => queryClient.invalidateQueries({ queryKey: taskKeys.all }),   // alle Seiten gelten als veraltet\\n  });\\n}\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m3-l3\",\"title\":\"Mutationen und optimistische Updates mit Rollback\",\"minutes\":40,\"objectives\":[\"Erklären, was ein optimistisches Update ist und wann es sich lohnt\",\"Die vier Schritte nennen: abbrechen, Schnappschuss, sofort anzeigen, bei Fehler zurückrollen\",\"Nach Erfolg oder Fehler mit dem Server abgleichen (onSettled)\",\"Die Tests für Erfolg, Fehler und Verzögerung (Gate-Technik) verstehen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, was ein optimistisches Update ist und wann es sich lohnt</li><li>Die vier Schritte nennen: abbrechen, Schnappschuss, sofort anzeigen, bei Fehler zurückrollen</li><li>Nach Erfolg oder Fehler mit dem Server abgleichen (onSettled)</li><li>Die Tests für Erfolg, Fehler und Verzögerung (Gate-Technik) verstehen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Query-Cache“.</p><h2>In einfachen Worten</h2><p>Wenn du einen Haken setzt, soll er sofort sichtbar sein, auch wenn der Server noch antwortet. Das nennt man ein optimistisches Update: Die Oberfläche tut so, als hätte es geklappt. Klappt es nicht, muss sie ehrlich zum alten Stand zurück und das auch zeigen.</p><p>Dafür braucht es vier Schritte. Erstens: Laufende Abrufe abbrechen, sonst überschreibt deren Antwort deine Änderung. Zweitens: den alten Stand merken (Schnappschuss). Drittens: die Änderung sofort im Cache setzen. Viertens: bei einem Fehler den Schnappschuss zurückschreiben. Am Ende (egal ob Erfolg oder Fehler) lädst du neu, damit Oberfläche und Server wieder übereinstimmen.</p><p>Wichtig: Optimistisch nur dort, wo ein Fehlschlag selten und harmlos ist (Haken setzen). Bei Zahlungen oder Löschungen ist ehrliches Warten besser.</p><h2>Schritt für Schritt</h2><ol><li>useMutation bekommt mutationFn: den eigentlichen Aufruf an die API.</li><li>onMutate läuft vor dem Request. Zuerst cancelQueries: Laufende Abrufe dürfen das optimistische Ergebnis nicht überschreiben.</li><li>getQueriesData holt Schnappschüsse aller betroffenen Cache-Einträge (alle Seiten). Sie werden als context zurückgegeben.</li><li>setQueriesData setzt die Änderung in allen Seiten sofort (neues Objekt, ohne das alte zu verändern).</li><li>onError schreibt die Schnappschüsse mit setQueryData zurück. Der Nutzer sieht den alten Stand wieder.</li><li>onSettled ruft invalidateQueries auf: Egal wie es ausging, der Server hat das letzte Wort.</li><li>Die Tests nutzen ein „Gate“: Ein Promise, das der Test selbst auflöst, hält die Serverantwort an. Dann lässt sich der Zwischenzustand prüfen: Der Haken ist sofort gesetzt, obwohl der Server noch nicht geantwortet hat.</li><li>Im Fehlerfall (failPatch) prüft der Test den Rollback: Nach der 500-Antwort ist der Haken wieder entfernt.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>data/<wbr>queries.ts</code> (Ausschnitt ab „// Lektion \\\"Optimistische Updates\\\"“)</li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>tests/<wbr>data.spec.ts</code> (Ausschnitt ab „it('zeigt das optimistische Update sofort und bestätigt es danach'“)</li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Query-Cache“):\\n - optimistisch: Haken sofort sichtbar, während der Server noch wartet; nach Freigabe bestätigt\\n - Serverfehler 500: Rollback auf den früheren Stand</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Ohne cancelQueries optimistisch aktualisieren.<br><strong>Warum:</strong> Eine ältere, noch laufende Abfrage kann danach eintreffen und das optimistische Ergebnis überschreiben. Der Haken „springt“ zurück.<br><strong>Besser:</strong> In onMutate zuerst cancelQueries aufrufen.</li><li><strong>Falsch:</strong> Den Cache direkt verändern (task.done = true).<br><strong>Warum:</strong> Gemeinsame Objekte werden verändert, Vue und Query-Cache merken Änderungen nicht zuverlässig, und der Schnappschuss ist wertlos.<br><strong>Besser:</strong> Immer neue Objekte erzeugen (Spread, map) – wie im Beispiel.</li><li><strong>Falsch:</strong> Keinen Rollback und keine Rückmeldung bei Fehlern vorsehen.<br><strong>Warum:</strong> Der Nutzer glaubt, es sei gespeichert; nach einem Reload ist es weg.<br><strong>Besser:</strong> Rollback und eine sichtbare Meldung (role=\\\"alert\\\") vorsehen. Das Lab zeigt die Daten korrekt zurück; eine Meldung ist als Übung ergänzt.</li><li><strong>Falsch:</strong> Alles optimistisch machen, auch Bezahlvorgänge.<br><strong>Warum:</strong> Ein „zu früh bestätigtes“ Ergebnis erzeugt Vertrauensverlust oder sogar rechtliche Probleme.<br><strong>Besser:</strong> Optimistisch nur bei harmlosen, leicht umkehrbaren Änderungen; sonst Ladezustand zeigen und warten.</li></ul><h2>Praxis</h2><p>Plane Fehler zuerst: Was sieht der Nutzer, wenn es schiefgeht? Dann erst die schnelle Variante. Teste immer drei Fälle: Erfolg, Fehler, Verzögerung. Ohne Gate-Technik bleibt der Zwischenzustand unsichtbar und der Test beweist wenig.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze in TaskInbox eine Meldung mit role=\\\"alert\\\", wenn das Umschalten fehlschlägt („Änderung konnte nicht gespeichert werden“).<br><em>Abnahme:</em> Bei failPatch erscheint die Meldung; bei Erfolg nicht; Test ergänzt.</li><li><strong>Grenzfall:</strong> Schalte schnell zweimal denselben Haken (an, aus), bevor der Server antwortet. Was passiert mit dem Schnappschuss? Beschreibe das Verhalten.<br><em>Abnahme:</em> Beobachtung dokumentiert; Risiko überlappender Mutationen erklärt (z. B. mutationKey/Serialisierung als Ausweg).</li><li><strong>Fehlerfall:</strong> Entferne cancelQueries und baue im Test einen langsamen GET, der nach dem optimistischen Update eintrifft. Beschreibe das Fehlverhalten.<br><em>Abnahme:</em> Haken springt zurück; Ursache und Fix (cancelQueries) sind erklärt.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://tanstack.com/query/latest/docs/framework/vue/guides/optimistic-updates\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">TanStack Query (Vue): Optimistic Updates</a> – TanStack Query steht unter MIT-Lizenz; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://tanstack.com/query/latest/docs/framework/vue/guides/mutations\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">TanStack Query (Vue): Mutations</a> – Offizielle Dokumentation; Inhalt hier eigenständig zusammengefasst.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Tests im vue-lab grün (Erfolg, Fehler/Rollback, Verzögerung per Gate). Überlappende Mutationen wurden nicht getestet; sie sind als Übung benannt.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Plane Fehler zuerst: Was sieht der Nutzer, wenn es schiefgeht? Dann erst die schnelle Variante. Teste immer drei Fälle: Erfolg, Fehler, Verzögerung. Ohne Gate-Technik bleibt der Zwischenzustand unsichtbar und der Test beweist wenig.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze in TaskInbox eine Meldung mit role=\\\"alert\\\", wenn das Umschalten fehlschlägt („Änderung konnte nicht gespeichert werden“).\",\"acceptance\":\"Bei failPatch erscheint die Meldung; bei Erfolg nicht; Test ergänzt.\"},{\"level\":2,\"task\":\"Grenzfall: Schalte schnell zweimal denselben Haken (an, aus), bevor der Server antwortet. Was passiert mit dem Schnappschuss? Beschreibe das Verhalten.\",\"acceptance\":\"Beobachtung dokumentiert; Risiko überlappender Mutationen erklärt (z. B. mutationKey/Serialisierung als Ausweg).\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne cancelQueries und baue im Test einen langsamen GET, der nach dem optimistischen Update eintrifft. Beschreibe das Fehlverhalten.\",\"acceptance\":\"Haken springt zurück; Ursache und Fix (cancelQueries) sind erklärt.\"}],\"sources\":[{\"url\":\"https://tanstack.com/query/latest/docs/framework/vue/guides/optimistic-updates\",\"title\":\"TanStack Query (Vue): Optimistic Updates\"},{\"url\":\"https://tanstack.com/query/latest/docs/framework/vue/guides/mutations\",\"title\":\"TanStack Query (Vue): Mutations\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Tests im vue-lab grün (Erfolg, Fehler/Rollback, Verzögerung per Gate). Überlappende Mutationen wurden nicht getestet; sie sind als Übung benannt.\"},\"quiz\":[{\"q\":\"Wozu dient cancelQueries in onMutate?\",\"options\":[\"Laufende Abrufe dürfen das optimistische Ergebnis nicht überschreiben.\",\"Es löscht den gesamten Cache.\",\"Es beschleunigt den Request.\"],\"correct\":0,\"explain\":\"Abbrechen verhindert, dass alte Antworten das optimistische Ergebnis überschreiben.\",\"rationales\":[\"Eine ältere Antwort könnte sonst nach dem optimistischen Update eintreffen und es überschreiben.\",\"Der Cache bleibt erhalten, es werden nur laufende Abfragen abgebrochen.\",\"Mit Geschwindigkeit hat es nichts zu tun.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/optimistic-updates\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/mutations\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum werden im Beispiel Schnappschüsse der Cache-Einträge gespeichert?\",\"options\":[\"Damit bei einem Fehler der frühere Stand wiederhergestellt werden kann.\",\"Damit die Daten doppelt vorhanden sind.\",\"Weil Vue es verlangt.\"],\"correct\":0,\"explain\":\"Der Schnappschuss ist die Grundlage des Rollbacks.\",\"rationales\":[\"onError schreibt die Schnappschüsse zurück (Rollback).\",\"Doppelte Daten sind kein Ziel.\",\"Vue verlangt das nicht; es ist Teil des Musters.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/optimistic-updates\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/mutations\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Wann ist ein optimistisches Update eine schlechte Idee?\",\"options\":[\"Beim Setzen eines Hakens in einer Liste, die der Nutzer jederzeit ändern kann.\",\"Bei Zahlungen oder anderen Aktionen, bei denen ein falsch bestätigtes Ergebnis schwerwiegend ist.\",\"Wenn die Liste nur wenige Einträge enthält und selten geändert wird.\"],\"correct\":1,\"explain\":\"Optimistisch nur für harmlose, leicht umkehrbare Änderungen.\",\"rationales\":[\"Hier ist es unkritisch und üblich.\",\"Bei folgenreichen Aktionen ist ehrliches Warten besser als eine vorschnelle Bestätigung.\",\"Die Länge der Liste ist unerheblich.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/optimistic-updates\",\"https://tanstack.com/query/latest/docs/framework/vue/guides/mutations\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"// Lektion \\\"Optimistische Updates\\\": sofort anzeigen, bei Fehler zurückrollen, am Ende mit dem Server abgleichen.\\nexport function useToggleTask(api: TasksApi) {\\n  const queryClient = useQueryClient();\\n  return useMutation({\\n    mutationFn: ({ id, done }: { id: number; done: boolean }) => api.setDone(id, done),\\n    onMutate: async ({ id, done }) => {\\n      await queryClient.cancelQueries({ queryKey: taskKeys.all });  // laufende Abrufe dürfen das Update nicht überschreiben\\n      const snapshots = queryClient.getQueriesData<TaskPage>({ queryKey: taskKeys.all });\\n      queryClient.setQueriesData<TaskPage>({ queryKey: taskKeys.all }, (old) =>\\n        old && { ...old, items: old.items.map((task) => (task.id === id ? { ...task, done } : task)) });\\n      return { snapshots };\\n    },\\n    onError: (_error, _variables, context) => {\\n      for (const [key, data] of context?.snapshots ?? []) queryClient.setQueryData(key, data);\\n    },\\n    onSettled: () => queryClient.invalidateQueries({ queryKey: taskKeys.all }),\\n  });\\n}\",\"codeLang\":\"TypeScript\",\"code2\":\"it('zeigt das optimistische Update sofort und bestätigt es danach', async () => {\\n  const server = createFakeServer(seed);\\n  let release!: () => void; server.behavior.patchGate = new Promise((r) => { release = r; });\\n  const { wrapper } = await mountWithApp(() => h(Probe, { api: createTasksApi(server.fetcher), page: ref(1) })); await flushPromises();\\n  await wrapper.get('#toggle').trigger('click'); await flushPromises();\\n  expect(wrapper.get('#titles').text()).toContain('Aufgabe 1:true');           // Server hat noch nicht geantwortet\\n  release(); await flushPromises();\\n  expect(wrapper.get('#titles').text()).toContain('Aufgabe 1:true');\\n  wrapper.unmount();\\n});\\n\\nit('rollt bei Serverfehler auf den früheren Stand zurück', async () => {\\n  const server = createFakeServer(seed); server.behavior.failPatch = true;\\n  let release!: () => void; server.behavior.patchGate = new Promise((r) => { release = r; });\\n  const { wrapper } = await mountWithApp(() => h(Probe, { api: createTasksApi(server.fetcher), page: ref(1) })); await flushPromises();\\n  await wrapper.get('#toggle').trigger('click'); await flushPromises();\\n  expect(wrapper.get('#titles').text()).toContain('Aufgabe 1:true');\\n  release();\\n  await vi.waitFor(() => expect(wrapper.get('#titles').text()).toContain('Aufgabe 1:false'));   // Rollback + Neuabgleich\\n  wrapper.unmount();\\n});\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m3-l4\",\"title\":\"Die URL als Zustand: teilbare Seitennummer\",\"minutes\":30,\"objectives\":[\"Begründen, warum die Seitennummer in die URL gehört (teilbar, Zurück-Taste, Reload)\",\"Query-Parameter defensiv lesen: Arrays, Text, Zahlen und Unsinn abfangen\",\"Mit computed aus route.query und router.push einen schlanken Zustand bauen\",\"Zusammenspiel mit keepPreviousData erklären (Weiter-Schaltfläche solange gesperrt)\"],\"body\":\"<h2>Lernziele</h2><ul><li>Begründen, warum die Seitennummer in die URL gehört (teilbar, Zurück-Taste, Reload)</li><li>Query-Parameter defensiv lesen: Arrays, Text, Zahlen und Unsinn abfangen</li><li>Mit computed aus route.query und router.push einen schlanken Zustand bauen</li><li>Zusammenspiel mit keepPreviousData erklären (Weiter-Schaltfläche solange gesperrt)</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Query-Cache“; Vue Router (js-m1-l12).</p><h2>In einfachen Worten</h2><p>Auf Seite 3 einer Liste landest du per Link, Reload oder Zurück-Taste. Das funktioniert nur, wenn die Seitennummer in der URL steht (?page=3) und nicht nur in einer Variable. Dann ist die Adresse teilbar und der Browserverlauf macht, was Menschen erwarten.</p><p>Aber: Alles in der URL ist Eingabe von außen. Jemand kann ?page=abc, ?page=-5 oder ?page=1&amp;page=2 schreiben. Dein Code muss das lesen, ohne zu stolpern. Die Regel im Beispiel: Alles, was keine positive ganze Zahl ist, wird zu Seite 1.</p><p>Und die URL ist die einzige Quelle: Die Komponente liest die Seite aus der Route und schreibt sie bei Klick mit router.push zurück.</p><h2>Schritt für Schritt</h2><ol><li>parsePage(raw) nimmt bei mehreren Werten (Array) den ersten, akzeptiert nur Text aus 1 bis 6 Ziffern und liefert sonst 1. Math.max(1, …) verhindert 0.</li><li>Die Obergrenze von sechs Ziffern verhindert absurde Zahlen und damit absurde Abfragen.</li><li>usePageParam() liefert page (computed aus route.query.page) und setPage(next).</li><li>setPage ersetzt nur page und behält andere Query-Parameter: { ...route.query, page: String(...) }.</li><li>router.push erzeugt einen Verlaufseintrag; die Zurück-Taste führt zur vorherigen Seite. Für reine Filter-Tipperei wäre router.replace angebracht.</li><li>In der Oberfläche: „Zurück“ ist bei Seite 1 deaktiviert. „Weiter“ ist deaktiviert, solange isPlaceholderData wahr ist (alte Seite wird noch gezeigt) oder die letzte Seite erreicht ist.</li><li>Ist die Seite größer als totalPages (z. B. ?page=999), antwortet der Server mit einer leeren Liste. Das Beispiel zeigt dann den Leerzustand; eine Weiterleitung auf die letzte Seite wäre eine Verbesserung.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>data/<wbr>usePageParam.ts</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>tests/<wbr>data.spec.ts</code> (Ausschnitt ab „describe('URL-Zustand'“)</li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „URL-Zustand“): grün\\n - \\\"3\\\" -&gt; 3, [\\\"2\\\",\\\"9\\\"] -&gt; 2, \\\"0\\\" / \\\"-3\\\" / \\\"abc\\\" / undefined / \\\"99999999\\\" (zu lang) -&gt; 1</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Number(route.query.page) ohne Prüfung verwenden.<br><strong>Warum:</strong> Das Ergebnis kann NaN, 0, negativ oder eine Kommazahl sein. Die Abfrage geht mit Unsinn an den Server.<br><strong>Besser:</strong> Defensiv parsen und Standardwert definieren (parsePage).</li><li><strong>Falsch:</strong> Die Seite zusätzlich in einer ref halten und mit der URL abgleichen.<br><strong>Warum:</strong> Zwei Quellen laufen auseinander (Zurück-Taste, Reload).<br><strong>Besser:</strong> Die URL ist die einzige Quelle; page ist ein computed.</li><li><strong>Falsch:</strong> Beim Seitenwechsel die anderen Query-Parameter zu verlieren.<br><strong>Warum:</strong> Filter und Sortierung verschwinden beim Blättern.<br><strong>Besser:</strong> { ...route.query, page } verwenden.</li><li><strong>Falsch:</strong> Persönliche oder vertrauliche Daten in Query-Parameter zu schreiben.<br><strong>Warum:</strong> URLs landen in Verlauf, Logs und Weiterleitungs-Headern.<br><strong>Besser:</strong> Nur unkritische Zustände (Seite, Sortierung, Filter) in die URL; keine personenbezogenen Daten.</li></ul><h2>Praxis</h2><p>Frage: Soll jemand diesen Zustand teilen oder per Zurück-Taste erreichen können? Dann URL. Wenn nicht (z. B. geöffnetes Menü), dann lokale ref. Dokumentiere erlaubte Parameter wie eine kleine API.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze Sortierung (?sort=due) als zweiten Parameter. Erlaube nur eine feste Liste von Werten und falle sonst auf den Standard zurück.<br><em>Abnahme:</em> Unbekannte Werte werden zum Standard; setPage behält sort.</li><li><strong>Grenzfall:</strong> Teste parsePage mit \\\"007\\\", \\\"1000000\\\" (sieben Ziffern), \\\" 3\\\" und \\\"３\\\" (volle Breite). Notiere die Ergebnisse.<br><em>Abnahme:</em> \\\"007\\\" → 7; sieben Ziffern → 1; \\\" 3\\\" → 1; volle Breite → 1 (die Regex akzeptiert nur ASCII-Ziffern).</li><li><strong>Fehlerfall:</strong> Öffne ?page=999. Was sieht der Nutzer? Entwirf (ohne Umsetzung) eine bessere Reaktion.<br><em>Abnahme:</em> Leerzustand beobachtet; Vorschlag (Weiterleitung auf letzte Seite oder Hinweis) mit Begründung formuliert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://router.vuejs.org/guide/essentials/navigation.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue Router: Query-Parameter und Navigation</a> – Vue Router steht unter MIT-Lizenz; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">MDN: URL und Query-String (URLSearchParams)</a> – MDN-Webdokumentation (Texte unter CC BY-SA); hier nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Test im vue-lab grün (parsePage). Das Verhalten bei ?page=999 wurde nicht automatisiert geprüft; es ist als Übung beschrieben.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Frage: Soll jemand diesen Zustand teilen oder per Zurück-Taste erreichen können? Dann URL. Wenn nicht (z. B. geöffnetes Menü), dann lokale ref. Dokumentiere erlaubte Parameter wie eine kleine API.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze Sortierung (?sort=due) als zweiten Parameter. Erlaube nur eine feste Liste von Werten und falle sonst auf den Standard zurück.\",\"acceptance\":\"Unbekannte Werte werden zum Standard; setPage behält sort.\"},{\"level\":2,\"task\":\"Grenzfall: Teste parsePage mit \\\"007\\\", \\\"1000000\\\" (sieben Ziffern), \\\" 3\\\" und \\\"３\\\" (volle Breite). Notiere die Ergebnisse.\",\"acceptance\":\"\\\"007\\\" → 7; sieben Ziffern → 1; \\\" 3\\\" → 1; volle Breite → 1 (die Regex akzeptiert nur ASCII-Ziffern).\"},{\"level\":3,\"task\":\"Fehlerfall: Öffne ?page=999. Was sieht der Nutzer? Entwirf (ohne Umsetzung) eine bessere Reaktion.\",\"acceptance\":\"Leerzustand beobachtet; Vorschlag (Weiterleitung auf letzte Seite oder Hinweis) mit Begründung formuliert.\"}],\"sources\":[{\"url\":\"https://router.vuejs.org/guide/essentials/navigation.html\",\"title\":\"Vue Router: Query-Parameter und Navigation\"},{\"url\":\"https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams\",\"title\":\"MDN: URL und Query-String (URLSearchParams)\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Test im vue-lab grün (parsePage). Das Verhalten bei ?page=999 wurde nicht automatisiert geprüft; es ist als Übung beschrieben.\"},\"quiz\":[{\"q\":\"Warum gehört die Seitennummer in die URL?\",\"options\":[\"Die Seite ist teilbar, überlebt einen Reload und die Zurück-Taste funktioniert wie erwartet.\",\"Weil Variablen in Vue nicht gespeichert werden können.\",\"Damit der Server den Seitenwert gar nicht erst erfährt und nichts zählt.\"],\"correct\":0,\"explain\":\"URL-Zustand ist teilbar, reload-fest und verlaufsfähig.\",\"rationales\":[\"Das sind die Vorteile von URL-Zustand.\",\"Variablen funktionieren; sie sind nur nicht teilbar.\",\"Der Server erhält den Parameter ja gerade.\"],\"sources\":[\"https://router.vuejs.org/guide/essentials/navigation.html\",\"https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Was liefert parsePage(\\\"-5\\\")?\",\"options\":[\"-5\",\"1\",\"NaN\"],\"correct\":1,\"explain\":\"Unlesbare Werte werden zu Seite 1.\",\"rationales\":[\"Negative Seiten sind nicht erlaubt.\",\"Die Regex akzeptiert nur Ziffern; alles andere wird zu 1.\",\"Es gibt keinen NaN-Pfad; der Code liefert immer eine gültige Zahl.\"],\"sources\":[\"https://router.vuejs.org/guide/essentials/navigation.html\",\"https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum ist „Weiter“ deaktiviert, solange isPlaceholderData wahr ist?\",\"options\":[\"Damit niemand weiterblättert, solange noch die alte Seite angezeigt wird und die neue lädt.\",\"Weil Platzhalterdaten im Browser grundsätzlich keine Klicks erlauben.\",\"Weil isPlaceholderData wahr ist, sobald ein Fehler aufgetreten ist.\"],\"correct\":0,\"explain\":\"Das Sperren verhindert Seitensprünge auf Basis veralteter Anzeige.\",\"rationales\":[\"Während der alten Daten ist unklar, ob es eine nächste Seite gibt; Springen würde Seiten überspringen.\",\"Technisch wären Klicks möglich; es ist eine bewusste Entscheidung.\",\"Es ist ein normaler Zwischenzustand, kein Fehler.\"],\"sources\":[\"https://router.vuejs.org/guide/essentials/navigation.html\",\"https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"import { computed } from 'vue';\\nimport { useRoute, useRouter } from 'vue-router';\\n\\n// Lektion \\\"URL als Zustand\\\": Die Seite steht in ?page=…, ist teilbar und überlebt einen Reload.\\nexport function parsePage(raw: unknown): number {\\n  const value = Array.isArray(raw) ? raw[0] : raw;\\n  if (typeof value !== 'string' || !/^\\\\d{1,6}$/.test(value)) return 1;   // alles Unlesbare: Seite 1\\n  return Math.max(1, Number(value));\\n}\\n\\nexport function usePageParam() {\\n  const route = useRoute();\\n  const router = useRouter();\\n  const page = computed(() => parsePage(route.query.page));\\n  const setPage = (next: number) => router.push({ query: { ...route.query, page: String(Math.max(1, next)) } });\\n  return { page, setPage };\\n}\",\"codeLang\":\"TypeScript\",\"code2\":\"describe('URL-Zustand', () => {\\n  it('liest page defensiv', () => {\\n    expect([parsePage('3'), parsePage('0'), parsePage('-3'), parsePage('abc'), parsePage(undefined), parsePage(['2', '9']), parsePage('99999999')])\\n      .toEqual([3, 1, 1, 1, 1, 2, 1]);\\n  });\\n});\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m3-l5\",\"title\":\"Mini-Projekt TaskInbox: alles zusammen\",\"minutes\":60,\"objectives\":[\"Formular, Query-Cache, Mutationen und URL-Zustand zu einer kleinen Anwendung verbinden\",\"Lade-, Fehler-, Leer- und Erfolgszustand mit zugänglichen Rollen (status, alert) darstellen\",\"Serverfehler im RFC-9457-Format dem richtigen Formularfeld zuordnen\",\"Die Anwendung gegen einen Fake-Server testen und die Grenzen dieses Tests benennen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Formular, Query-Cache, Mutationen und URL-Zustand zu einer kleinen Anwendung verbinden</li><li>Lade-, Fehler-, Leer- und Erfolgszustand mit zugänglichen Rollen (status, alert) darstellen</li><li>Serverfehler im RFC-9457-Format dem richtigen Formularfeld zuordnen</li><li>Die Anwendung gegen einen Fake-Server testen und die Grenzen dieses Tests benennen</li></ul><p><strong>Voraussetzungen:</strong> Lektionen 1 bis 4 dieses Moduls.</p><h2>In einfachen Worten</h2><p>Jetzt kommt alles zusammen. Die TaskInbox zeigt eine Liste von Aufgaben, lässt neue anlegen, Haken setzen und blättern. Dabei gelten die Regeln der letzten Lektionen: Das Formular prüft mit Zod, die Liste kommt aus dem Query-Cache, der Haken ist optimistisch und die Seite steht in der URL.</p><p>Besonders wichtig sind die vier Zustände, die jede Datenansicht kennen muss: Laden („Lade Aufgaben …“), Fehler (mit Schaltfläche „Erneut versuchen“), leer („Noch keine Aufgaben“) und Daten. Jeder Zustand bekommt eine passende Rolle (status oder alert), damit Screenreader Änderungen melden.</p><p>Und der Server hat das letzte Wort: Meldet er „Titel existiert bereits“ (422), landet diese Meldung am Titelfeld, mit Fokus und Verknüpfung wie bei einer Clientprüfung.</p><h2>Schritt für Schritt</h2><ol><li>TaskInbox erhält die API als Prop (api) – so lässt sich in Tests ein Fake-Server einsetzen. Die Router-Anbindung (usePageParam) und der QueryClient kommen von außen (Plugin/Provider).</li><li>useTasksQuery, useCreateTask und useToggleTask bündeln die Datenlogik; die Komponente bleibt schlank.</li><li>serverErrors wird aus create.error abgeleitet: Nur ApiError mit Status 422 liefert Feldfehler. Alle anderen Fehler erzeugen eine allgemeine Meldung mit role=\\\"alert\\\".</li><li>Die Anzeige verzweigt: isPending → status „Lade Aufgaben …“; isError → alert mit „Erneut versuchen“ (refetch); leere Liste → Leerzustand; sonst Liste mit Checkboxen und Seitennavigation (nav mit aria-label).</li><li>Jede Aufgabe ist ein &lt;label&gt; mit Checkbox: Klickfläche ist die ganze Zeile, der Name ist die Beschriftung.</li><li>Während das Anlegen läuft, ist die Schaltfläche deaktiviert und zeigt „Wird gespeichert …“.</li><li>Die Tests prüfen vier Wege: Laden und Blättern über die URL (mit Ladezustand), Fehlerzustand mit Wiederholung, Leerzustand und Anlegen inklusive Serverfehler am Feld.</li><li>Grenzen: Der Fake-Server ist kein echter Server. Reale Fehler wie Zeitüberschreitungen, CORS, Anmeldung oder CSRF sind nicht abgedeckt. Zusammen mit dem Spring-Lab (java-m26) lässt sich der Vertrag beider Seiten manuell abgleichen.</li></ol><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>data/<wbr>TaskInbox.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>tests/<wbr>data.spec.ts</code> (Ausschnitt ab „it('legt an, aktualisiert die Liste und ordnet Serverfehler dem Feld zu'“)</li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (Block „Mini-Projekt TaskInbox“): 4 Tests grün\\n - lädt, blättert über die URL und zeigt Ladezustand\\n - zeigt einen Fehlerzustand mit Wiederholung\\n - zeigt den Leerzustand\\n - legt an, aktualisiert die Liste und ordnet den 422-Fehler \\\"Titel existiert bereits\\\" dem Titelfeld zu\\nGesamt im vue-lab: 38 Tests grün (6 vorhandene + 32 neue); vue-tsc und vite build ohne Fehler.</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Nur den Erfolgsfall bauen.<br><strong>Warum:</strong> Echte Nutzer erleben Laden, Fehler und leere Listen häufiger, als man denkt.<br><strong>Besser:</strong> Alle vier Zustände entwerfen und testen, bevor die Oberfläche schön gemacht wird.</li><li><strong>Falsch:</strong> Alle Serverfehler gleich behandeln.<br><strong>Warum:</strong> Ein 422 gehört an ein Feld, ein 500 ist eine allgemeine Störung. Gleichbehandlung verwirrt Nutzer.<br><strong>Besser:</strong> Nach Status unterscheiden (422 → Feldfehler, sonst allgemeine Meldung).</li><li><strong>Falsch:</strong> Den Fake-Server mit dem echten Server gleichzusetzen.<br><strong>Warum:</strong> Der Test belegt die eigene Logik, nicht das Zusammenspiel mit echter Technik.<br><strong>Besser:</strong> Zusätzlich einen Ende-zu-Ende-Test gegen eine echte Umgebung vorsehen (z. B. Playwright gegen das Spring-Lab).</li><li><strong>Falsch:</strong> Technische Fehlertexte aus dem Server direkt anzeigen.<br><strong>Warum:</strong> Meldungen können intern oder verwirrend sein und im schlimmsten Fall Details preisgeben.<br><strong>Besser:</strong> Eigene, verständliche Texte anzeigen; Feldmeldungen nur, wenn der Vertrag sie ausdrücklich als nutzerlesbar festlegt.</li></ul><h2>Praxis</h2><p>Ein Mini-Projekt ist ein Prüfstein: Kannst du jede Entscheidung erklären (Warum dieser Schlüssel? Warum diese Rolle?). Notiere in einer kurzen README: Zweck, Zustände, Tests, bekannte Grenzen. So können andere (und du in drei Monaten) es verstehen.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze das Löschen einer Aufgabe (DELETE) mit Bestätigungsdialog aus js-m2-l4 und Invalidierung. Entscheide begründet, ob es optimistisch sein soll.<br><em>Abnahme:</em> Dialog bestätigt; Liste aktualisiert; Entscheidung (nicht optimistisch, weil schwer umkehrbar) begründet.</li><li><strong>Grenzfall:</strong> Lege 6 Aufgaben an (Seitengröße 5). Prüfe, ob die zweite Seite erreichbar ist und die Seitenanzeige stimmt.<br><em>Abnahme:</em> Zweite Seite zeigt 1 Eintrag; „Weiter“ bei Seite 2 deaktiviert; Test ergänzt.</li><li><strong>Fehlerfall:</strong> Lass den Server auf POST mit 500 antworten. Welche Meldung erscheint, bleibt die Eingabe erhalten und ist die Schaltfläche wieder bedienbar?<br><em>Abnahme:</em> Allgemeine Meldung mit role=\\\"alert\\\"; Eingabe erhalten; Schaltfläche wieder aktiv.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://tanstack.com/query/latest/docs/framework/vue/guides/queries\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">TanStack Query (Vue): Queries und Query Keys</a> – TanStack Query steht unter MIT-Lizenz; Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://www.w3.org/TR/wai-aria-1.2/#status\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">W3C ARIA: Rollen status und alert (APG und WAI-ARIA)</a> – W3C-Spezifikation; nur verlinkt.</li><li><a href=\\\"https://www.rfc-editor.org/rfc/rfc9457.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">RFC 9457: Problem Details for HTTP APIs</a> – IETF-Standard; nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Alle Tests im vue-lab grün (38), vue-tsc und vite build fehlerfrei. NICHT geprüft: echte Browserbedienung, Screenreader, Integration mit dem Spring-Lab über das Netzwerk.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Ein Mini-Projekt ist ein Prüfstein: Kannst du jede Entscheidung erklären (Warum dieser Schlüssel? Warum diese Rolle?). Notiere in einer kurzen README: Zweck, Zustände, Tests, bekannte Grenzen. So können andere (und du in drei Monaten) es verstehen.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze das Löschen einer Aufgabe (DELETE) mit Bestätigungsdialog aus js-m2-l4 und Invalidierung. Entscheide begründet, ob es optimistisch sein soll.\",\"acceptance\":\"Dialog bestätigt; Liste aktualisiert; Entscheidung (nicht optimistisch, weil schwer umkehrbar) begründet.\"},{\"level\":2,\"task\":\"Grenzfall: Lege 6 Aufgaben an (Seitengröße 5). Prüfe, ob die zweite Seite erreichbar ist und die Seitenanzeige stimmt.\",\"acceptance\":\"Zweite Seite zeigt 1 Eintrag; „Weiter“ bei Seite 2 deaktiviert; Test ergänzt.\"},{\"level\":3,\"task\":\"Fehlerfall: Lass den Server auf POST mit 500 antworten. Welche Meldung erscheint, bleibt die Eingabe erhalten und ist die Schaltfläche wieder bedienbar?\",\"acceptance\":\"Allgemeine Meldung mit role=\\\"alert\\\"; Eingabe erhalten; Schaltfläche wieder aktiv.\"}],\"sources\":[{\"url\":\"https://tanstack.com/query/latest/docs/framework/vue/guides/queries\",\"title\":\"TanStack Query (Vue): Queries und Query Keys\"},{\"url\":\"https://www.w3.org/TR/wai-aria-1.2/#status\",\"title\":\"W3C ARIA: Rollen status und alert (APG und WAI-ARIA)\"},{\"url\":\"https://www.rfc-editor.org/rfc/rfc9457.html\",\"title\":\"RFC 9457: Problem Details for HTTP APIs\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Alle Tests im vue-lab grün (38), vue-tsc und vite build fehlerfrei. NICHT geprüft: echte Browserbedienung, Screenreader, Integration mit dem Spring-Lab über das Netzwerk.\"},\"quiz\":[{\"q\":\"Welche vier Zustände muss jede Datenansicht abdecken?\",\"options\":[\"Laden, Fehler, leer und Daten.\",\"Hell, dunkel, kontrastreich und Druck.\",\"Entwurf, Prüfung, Freigabe und Archiv.\"],\"correct\":0,\"explain\":\"Laden, Fehler, leer und Daten sind die Grundzustände.\",\"rationales\":[\"Diese Zustände erleben Nutzer tatsächlich; jeder braucht eine sichtbare, zugängliche Darstellung.\",\"Das sind Darstellungsvarianten, keine Datenzustände.\",\"Das sind fachliche Workflow-Stufen.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/queries\",\"https://www.w3.org/TR/wai-aria-";
RP_LITERAL_2_text += "1.2/#status\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Der Server antwortet auf das Anlegen mit 422 und einer Feldmeldung. Wohin gehört sie?\",\"options\":[\"In ein Popup, das nach 3 Sekunden verschwindet.\",\"An das betroffene Feld, verknüpft per aria-describedby, mit Fokus.\",\"In die Browserkonsole.\"],\"correct\":1,\"explain\":\"Feldfehler gehören an das Feld und müssen zugänglich verknüpft sein.\",\"rationales\":[\"Verschwindende Meldungen sind für viele Nutzer nicht zugänglich.\",\"So erreicht die Meldung auch Tastatur- und Screenreader-Nutzer.\",\"Nutzer sehen die Konsole nicht.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/queries\",\"https://www.w3.org/TR/wai-aria-1.2/#status\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Was belegt ein grüner Test mit dem Fake-Server nicht?\",\"options\":[\"Dass die eigene Logik der Komponenten unter Testbedingungen funktioniert.\",\"Dass reale Netzwerkfehler, CORS, Anmeldung und CSRF im echten Zusammenspiel funktionieren.\",\"Dass die Komponenten ihre Props und Ereignisse korrekt verarbeiten.\"],\"correct\":1,\"explain\":\"Fake-Server belegen Logik, nicht die reale Integration.\",\"rationales\":[\"Das belegt der Test sehr wohl.\",\"Der Fake-Server simuliert nur Antworten; reale Umgebung braucht eigene Prüfungen.\",\"Auch das ist durch den Test abgedeckt.\"],\"sources\":[\"https://tanstack.com/query/latest/docs/framework/vue/guides/queries\",\"https://www.w3.org/TR/wai-aria-1.2/#status\",\"https://www.rfc-editor.org/rfc/rfc9457.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\n// Lektion \\\"Mini-Projekt\\\": Formular + Query-Cache + Mutationen + Serverfehler (RFC 9457) im Zusammenspiel.\\nimport { computed } from 'vue';\\nimport TaskForm from '../forms/TaskForm.vue';\\nimport type { FieldErrors, TaskFormData } from '../forms/taskSchema';\\nimport { ApiError, type TasksApi } from './tasksApi';\\nimport { useCreateTask, useTasksQuery, useToggleTask } from './queries';\\nimport { usePageParam } from './usePageParam';\\n\\nconst props = defineProps<{ api: TasksApi; today?: string }>();\\nconst { page, setPage } = usePageParam();\\nconst tasks = useTasksQuery(props.api, page);\\nconst create = useCreateTask(props.api);\\nconst toggle = useToggleTask(props.api);\\n\\nconst serverErrors = computed<FieldErrors>(() => {\\n  const error = create.error.value;\\n  return error instanceof ApiError && error.status === 422 ? error.fieldErrors : {};\\n});\\nconst generalError = computed(() => {\\n  const error = create.error.value;\\n  return error && !(error instanceof ApiError && error.status === 422) ? 'Speichern fehlgeschlagen. Bitte später erneut versuchen.' : '';\\n});\\n\\nfunction onSubmit(data: TaskFormData) { create.mutate(data); }\\n</script>\\n\\n<template>\\n  <section aria-labelledby=\\\"inbox-title\\\">\\n    <h2 id=\\\"inbox-title\\\">Aufgaben</h2>\\n    <TaskForm :submitting=\\\"create.isPending.value\\\" :server-errors=\\\"serverErrors\\\" :today=\\\"today\\\" @submit=\\\"onSubmit\\\" />\\n    <p v-if=\\\"generalError\\\" role=\\\"alert\\\">{{ generalError }}</p>\\n\\n    <p v-if=\\\"tasks.isPending.value\\\" role=\\\"status\\\">Lade Aufgaben …</p>\\n    <div v-else-if=\\\"tasks.isError.value\\\" role=\\\"alert\\\">\\n      <p>Aufgaben konnten nicht geladen werden.</p>\\n      <button type=\\\"button\\\" @click=\\\"tasks.refetch()\\\">Erneut versuchen</button>\\n    </div>\\n    <p v-else-if=\\\"!tasks.data.value?.items.length\\\" role=\\\"status\\\">Noch keine Aufgaben. Lege die erste an.</p>\\n    <template v-else>\\n      <ul>\\n        <li v-for=\\\"task in tasks.data.value.items\\\" :key=\\\"task.id\\\">\\n          <label>\\n            <input type=\\\"checkbox\\\" :checked=\\\"task.done\\\" @change=\\\"toggle.mutate({ id: task.id, done: !task.done })\\\">\\n            {{ task.title }}<span v-if=\\\"task.dueDate\\\"> (fällig {{ task.dueDate }})</span>\\n          </label>\\n        </li>\\n      </ul>\\n      <nav aria-label=\\\"Seiten\\\">\\n        <button type=\\\"button\\\" :disabled=\\\"page <= 1\\\" @click=\\\"setPage(page - 1)\\\">Zurück</button>\\n        <span>Seite {{ page }} von {{ tasks.data.value.totalPages }}</span>\\n        <button type=\\\"button\\\" :disabled=\\\"tasks.isPlaceholderData.value || page >= tasks.data.value.totalPages\\\" @click=\\\"setPage(page + 1)\\\">Weiter</button>\\n      </nav>\\n    </template>\\n  </section>\\n</template>\",\"codeLang\":\"Vue\",\"code2\":\"it('legt an, aktualisiert die Liste und ordnet Serverfehler dem Feld zu', async () => {\\n  const server = createFakeServer(seed.slice(0, 1));\\n  const { wrapper } = await mountWithApp(() => h(TaskInbox, { api: createTasksApi(server.fetcher), today: TODAY }));\\n  await flushPromises();\\n  await wrapper.get('#task-title').setValue('Duplikat'); await wrapper.get('form').trigger('submit'); await flushPromises();\\n  expect(wrapper.get('#task-title-error').text()).toBe('Titel existiert bereits');\\n  expect((wrapper.get('#task-title').element as HTMLInputElement).value).toBe('Duplikat');   // Eingabe bleibt\\n  await wrapper.get('#task-title').setValue('Neue Aufgabe'); await wrapper.get('form').trigger('submit'); await flushPromises();\\n  expect(wrapper.text()).toContain('Neue Aufgabe');\\n  expect(server.calls.filter((c) => c.startsWith('POST'))).toHaveLength(2);\\n  wrapper.unmount();\\n});\",\"code2Lang\":\"TypeScript\"}]},{\"id\":\"js-m4\",\"course\":\"javascript\",\"part\":23,\"partTitle\":\"JavaScript & Vue · Vollständiger Lernpfad\",\"title\":\"Vue für Fortgeschrittene · Router-Schutz, Anmeldung, Reaktivität und Datenmuster\",\"lessons\":[{\"id\":\"js-m4-l1\",\"title\":\"Router-Guards: Zugriffsschutz, Rollen und sicherer Rücksprung\",\"minutes\":45,\"objectives\":[\"Erklären, was ein Navigation Guard ist, wann er läuft und was er zurückgeben darf\",\"Route-Meta mit TypeScript typisieren und damit geschützte Seiten und Rollen beschreiben\",\"Eine Anmeldeumleitung mit Rücksprungziel bauen, ohne Endlosschleife und ohne Login-Flackern nach einem Reload\",\"Das Rücksprungziel als Fremdeingabe behandeln und Open Redirects verhindern; die Grenze von Guards als Sicherheitsmaßnahme benennen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Erklären, was ein Navigation Guard ist, wann er läuft und was er zurückgeben darf</li><li>Route-Meta mit TypeScript typisieren und damit geschützte Seiten und Rollen beschreiben</li><li>Eine Anmeldeumleitung mit Rücksprungziel bauen, ohne Endlosschleife und ohne Login-Flackern nach einem Reload</li><li>Das Rücksprungziel als Fremdeingabe behandeln und Open Redirects verhindern; die Grenze von Guards als Sicherheitsmaßnahme benennen</li></ul><p><strong>Voraussetzungen:</strong> Vue Router, Navigation und Backendgrenzen (js-m1-l12); Promises und async/await (js-m1-l4).</p><h2>In einfachen Worten</h2><p>Stell dir ein Bürogebäude mit Pförtner vor. Bevor jemand eine Tür öffnet, stellt der Pförtner drei Fragen: Wer bist du? Darfst du in diesen Raum? Und wenn nicht: Wohin schicke ich dich, und wie komme ich danach wieder hierher zurück?</p><p>Ein Navigation Guard im Vue Router ist genau dieser Pförtner. Er läuft bei jedem Seitenwechsel, bevor die neue Seite angezeigt wird. Er darf drei Dinge antworten: „Weiter“ (true oder nichts zurückgeben), „Stopp“ (false) oder „Geh stattdessen dorthin“ (eine andere Adresse zurückgeben). So schickst du Besucher ohne Anmeldung zur Anmeldeseite und merkst dir, wo sie eigentlich hinwollten.</p><p>Wichtig ist eine ehrliche Einordnung: Der Pförtner steht im Browser, und den kontrolliert der Besucher. Wer die Entwicklerwerkzeuge öffnet, kann jede Prüfung im Browser umgehen. Guards sind deshalb Bedienkomfort („zeige nichts Unbrauchbares“), keine Sicherheitsmaßnahme. Die eigentliche Zugriffsprüfung muss bei jedem Aufruf der Daten-API auf dem Server passieren.</p><h2>Schritt für Schritt</h2><ol><li>Meta-Felder typisieren: Mit declare module \\\"vue-router\\\" { interface RouteMeta { requiresAuth?: boolean; roles?: readonly Role[]; title?: string } } kennt TypeScript die erlaubten Felder. Ein Tippfehler wie requireAuth fällt dann beim Bauen auf, nicht erst durch eine ungeschützte Seite im Betrieb. Die Datei muss ein Modul sein (mindestens ein export).</li><li>Routen beschreiben, nicht programmieren: /account bekommt meta: { requiresAuth: true }, /admin zusätzlich roles: [\\\"admin\\\"]. Die Regeln stehen an der Route, der Guard liest sie nur. So bleibt der Guard klein, und neue Seiten brauchen keinen neuen Code.</li><li>Die Anmeldung hinter eine Schnittstelle legen: AuthState hat ready (ein Promise), isLoggedIn() und roles(). Der Router kennt damit keine Tokens, Cookies oder Stores. Tests und die echte Sitzung (Lektion 2) liefern dieselbe Form.</li><li>Der Guard läuft in fester Reihenfolge: (1) await auth.ready, (2) wer schon angemeldet ist und /login öffnet, wird zum Rücksprungziel geschickt, (3) öffentliche Seiten sind frei, (4) ohne Anmeldung geht es zu /login mit query.redirect = to.fullPath, (5) fehlt die Rolle, geht es zu /forbidden, (6) sonst true.</li><li>Warum await auth.ready? Nach einem Reload ist der Browser leer: Die Sitzung muss erst wiederhergestellt werden. Ohne das Warten würde der Guard „nicht angemeldet“ sehen und die Anmeldeseite kurz zeigen, obwohl alles in Ordnung ist. Solange das Promise offen ist, bleibt die Navigation „pending“, der Test zeigt das.</li><li>Endlosschleifen vermeiden: /login und /forbidden haben kein requiresAuth. Wären sie selbst geschützt, würde der Guard bei jedem Versuch erneut umleiten. Der Router bricht eine solche Kette nach vielen Umleitungen mit einer Fehlermeldung ab (Übung 3).</li><li>Rückgabewerte im Detail: true oder undefined bestätigt die Navigation. false bricht sie ab; router.push() wirft dann nicht, sondern löst mit einem NavigationFailure auf (isNavigationFailure(result, NavigationFailureType.aborted)), die Anzeige bleibt auf der alten Seite. Eine Adresse (Objekt oder String) ersetzt die Navigation durch eine neue. Ein geworfener Fehler bricht ebenfalls ab und geht an router.onError.</li><li>Das Rücksprungziel prüfen: safeRedirectTarget(raw) nimmt bei einem Array den ersten Eintrag, verlangt einen Text, der mit genau einem \\\"/\\\" beginnt (kein \\\"//\\\" und kein \\\"/\\\\\\\"), höchstens 2048 Zeichen hat und weder Leerraum, Steuerzeichen noch Backslash enthält. Alles andere ergibt den Fallback \\\"/\\\".</li><li>router.afterEach setzt nach jeder Navigation den Dokumenttitel aus meta.title. Das hilft Screenreader-Nutzern, denn bei einer Seite ohne Neuladen ändert sich sonst nichts, was die Hilfstechnik ansagen könnte (Übung 4 ergänzt Fokus und Ansage).</li><li>Die Tests decken acht Fälle ab: Umleitung mit Rücksprungziel, Rollenprüfung, Login-Seite für Angemeldete, Warten auf ready, Abbruch mit false, Titel und zwei Tests für die Rücksprungprüfung (gültig und eine Liste von Angriffswerten).</li></ol><h2>Hintergrund: Warum ist das so?</h2><p>Warum ist ein Guard keine Sicherheit? Der Code der Webanwendung wird vollständig an den Browser ausgeliefert. Wer ihn bedient, kann ihn lesen, verändern oder umgehen, und er kann die Daten-API auch ganz ohne Oberfläche aufrufen. Ein Guard verhindert deshalb nur, dass ehrliche Nutzer in eine Sackgasse laufen. Fehlerhafte Zugriffskontrolle („Broken Access Control“) stand in der OWASP-Top-10-Ausgabe 2021 auf Platz 1; die Prüfung gehört auf den Server, bei jeder Anfrage, mit der Identität aus dem Token oder der Sitzung, nie mit Rollen, die der Browser behauptet.</p><p>Warum das Rücksprungziel Fremdeingabe ist: Die Adresse /login?redirect=… kann jeder in einen Link schreiben, auch ein Angreifer in einer E-Mail. Mit router.push bleibt man innerhalb der Anwendung. Rücksprungziele wandern aber oft weiter, etwa in window.location, in eine serverseitige Weiterleitung oder in Nuxt/SSR-Code. Dort würde \\\"//evil.example\\\" als fremde Adresse gelten, und Nutzer landen nach dem Login auf einer nachgebauten Seite („Open Redirect“, ein klassischer Phishing-Baustein). Darum prüfst du das Ziel an der Stelle, wo du es liest, nicht erst an der Stelle, wo es gefährlich wird.</p><p>Warum Regeln an die Route und nicht in den Guard? Eine Routenliste mit meta lässt sich lesen wie eine Tabelle („wer darf wohin“) und prüfen. Ein Guard mit vielen if-Zweigen pro Pfad wird schnell unübersichtlich, und vergessene Pfade sind unsichtbar. Der Router führt die meta-Felder von Eltern- und Kindrouten zusammen (flach, nicht tief): Kindrouten sollten ihre Regeln deshalb vollständig angeben, wenn sie Werte der Eltern überschreiben.</p><h2>Begriffe auf einen Blick</h2><dl><dt>Navigation Guard</dt><dd>Eine Funktion, die der Router vor (oder nach) einem Seitenwechsel aufruft und die den Wechsel erlauben, abbrechen oder umlenken darf.</dd><dt>Meta-Feld (route.meta)</dt><dd>Frei wählbare Zusatzangaben an einer Route, z. B. requiresAuth. Sie sind im Guard über to.meta lesbar.</dd><dt>Weiterleitung (Redirect)</dt><dd>Statt der gewünschten Seite wird eine andere Adresse geöffnet. Im Guard geschieht das durch Zurückgeben dieser Adresse.</dd><dt>Open Redirect</dt><dd>Eine Weiterleitung, deren Ziel von außen vorgegeben und nicht geprüft wird. Angreifer nutzen sie, um Nutzer auf fremde Seiten zu schicken.</dd><dt>NavigationFailure</dt><dd>Ergebnis eines abgebrochenen oder doppelten Seitenwechsels. router.push wirft dafür keinen Fehler, sondern gibt dieses Objekt zurück.</dd><dt>Pending (offen)</dt><dd>Solange ein Guard noch auf ein Promise wartet, ist die Navigation weder abgeschlossen noch abgebrochen.</dd></dl><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>router/<wbr>guards.ts</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>tests/<wbr>router-guards.spec.ts</code> (Ausschnitt ab „describe('safeRedirectTarget'“)</li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (tests/router-guards.spec.ts): 8 Tests grün\\n - /account?tab=2 ohne Anmeldung -&gt; Route \\\"login\\\", query.redirect = \\\"/account?tab=2\\\"\\n - user: /account ok, /admin -&gt; \\\"forbidden\\\"; admin: /admin ok\\n - angemeldet: /login?redirect=/account -&gt; \\\"/account\\\"; ?redirect=//evil.example -&gt; \\\"/\\\"\\n - ready offen -&gt; Navigation pending; nach ready und Anmeldung -&gt; \\\"account\\\"\\n - Guard mit false -&gt; push liefert NavigationFailure (aborted), Route bleibt \\\"account\\\"\\n - Rücksprung: '/account?tab=2#top' ok; 'https://evil.example', '//evil.example', '/\\\\\\\\evil.example',\\n   'javascript:alert(1)', Zeilenumbruch, Leerraum, relative Pfade, leer, Zahl, null -&gt; \\\"/\\\"</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Den Admin-Bereich nur über einen Guard zu schützen und die Daten-API ungeschützt zu lassen.<br><strong>Warum:</strong> Der Guard läuft im Browser und lässt sich umgehen. Wer die API direkt aufruft, sieht alle Daten.<br><strong>Besser:</strong> Jede API-Anfrage serverseitig prüfen (Identität und Rolle). Der Guard bleibt Komfort: Er blendet Seiten aus, die ohnehin scheitern würden.</li><li><strong>Falsch:</strong> Das Rücksprungziel aus der URL ungeprüft in router.push oder window.location zu übergeben.<br><strong>Warum:</strong> Ein präparierter Link (?redirect=//evil.example) kann Nutzer nach der Anmeldung auf eine fremde Seite lenken.<br><strong>Besser:</strong> Nur Pfade der eigenen Anwendung erlauben (safeRedirectTarget) und alles andere durch einen festen Standardwert ersetzen.</li><li><strong>Falsch:</strong> Die Anmeldeseite selbst mit requiresAuth zu versehen oder /forbidden zu schützen.<br><strong>Warum:</strong> Der Guard leitet bei jeder Navigation wieder auf sich selbst um: eine Endlosschleife, die der Router erst nach vielen Umleitungen abbricht.<br><strong>Besser:</strong> Ausweichseiten (login, forbidden, 404) bleiben öffentlich. Im Guard zusätzlich prüfen, dass das Ziel nicht schon die Ausweichseite ist, wenn die Regeln komplexer werden.</li><li><strong>Falsch:</strong> Nicht auf die Wiederherstellung der Sitzung zu warten.<br><strong>Warum:</strong> Nach einem Reload ist der Zustand leer. Der Guard sieht „nicht angemeldet“, zeigt die Anmeldeseite und leitet erst danach um: sichtbares Flackern und falsche Rücksprungziele.<br><strong>Besser:</strong> In den Guard await auth.ready einbauen, damit die Navigation offen bleibt, bis der Zustand bekannt ist.</li><li><strong>Falsch:</strong> In Guards viele Zweige pro Pfad zu schreiben, statt Regeln an der Route zu beschreiben.<br><strong>Warum:</strong> Neue Seiten werden vergessen, die Regeln sind verstreut und kaum prüfbar.<br><strong>Besser:</strong> meta-Felder typisieren, im Guard nur allgemeine Regeln auswerten und die Routentabelle als Quelle der Wahrheit nutzen.</li></ul><h2>Praxis</h2><p>Plane Zugriffsregeln in zwei Schichten: Server entscheidet verbindlich, die Oberfläche spiegelt das Ergebnis. Halte eine Liste aller Ausweichziele (login, forbidden, notfound) bereit und teste jede Regel mit einem Normalfall, einem Grenzfall (z. B. leere Rollenliste) und einem Fehlerfall. Ergänze nach dem Seitenwechsel für Screenreader eine Ansage oder verschiebe den Fokus auf die Hauptüberschrift; ein geänderter Dokumenttitel allein reicht nicht für alle Hilfstechniken.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Füge eine Route /reports hinzu, die für die Rollen \\\"user\\\" und \\\"admin\\\" erreichbar ist und Anmeldung verlangt. Schreibe Tests für Gast, user und admin.<br><em>Abnahme:</em> Gast wird mit redirect=/reports zur Anmeldung geleitet; user und admin erreichen die Seite; der Titel „Berichte · ROOTPFAD Lab“ steht nach der Navigation.</li><li><strong>Grenzfall:</strong> Lege eine Route mit roles: [] an und sage vorher voraus, wer sie öffnen kann. Prüfe dein Ergebnis mit einem Test.<br><em>Abnahme:</em> Beobachtung: niemand erreicht die Seite (some() auf einer leeren Liste ist false, also /forbidden). Begründung und der Vorschlag, roles: [] als Konfigurationsfehler zu melden, sind notiert.</li><li><strong>Fehlerfall:</strong> Setze requiresAuth: true auf die Route \\\"login\\\" und rufe router.push(\\\"/account\\\") für einen Gast auf. Notiere Fehlermeldung und Verhalten, dann stelle den Code wieder her.<br><em>Abnahme:</em> Der Router bricht die Umleitungskette mit einer Meldung ab; die Ursache (Guard leitet auf eine selbst geschützte Seite um) ist erklärt.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://router.vuejs.org/guide/advanced/navigation-guards.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue Router: Navigation Guards</a> – Offizielle Dokumentation (Vue Router, MIT-Lizenz); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://router.vuejs.org/guide/advanced/meta.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue Router: Route Meta Fields (inkl. TypeScript)</a> – Offizielle Dokumentation (Vue Router, MIT-Lizenz); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">OWASP Top 10 2021: A01 Broken Access Control</a> – Nur verlinkt und zusammengefasst; Rechte liegen bei den jeweiligen Herausgebern.</li><li><a href=\\\"https://cheatsheetseries.owasp.org/cheatsheets/Unvalidated_Redirects_and_Forwards_Cheat_Sheet.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">OWASP Cheat Sheet: Unvalidated Redirects and Forwards</a> – Nur verlinkt und zusammengefasst; Rechte liegen bei den jeweiligen Herausgebern.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Alle Tests im vue-lab (vue-router 5.4.0, Vitest 5.1.0, jsdom) grün; Rückgabewerte, NavigationFailure und Pending-Verhalten wurden beobachtet, nicht nur der Dokumentation entnommen. NICHT geprüft: Verhalten im echten Browser mit History-Modus und Server-Fallback, Fokus- und Screenreader-Ansage nach dem Seitenwechsel, serverseitige Autorisierung (das Lab hat kein Backend mit Rollen).</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Plane Zugriffsregeln in zwei Schichten: Server entscheidet verbindlich, die Oberfläche spiegelt das Ergebnis. Halte eine Liste aller Ausweichziele (login, forbidden, notfound) bereit und teste jede Regel mit einem Normalfall, einem Grenzfall (z. B. leere Rollenliste) und einem Fehlerfall. Ergänze nach dem Seitenwechsel für Screenreader eine Ansage oder verschiebe den Fokus auf die Hauptüberschrift; ein geänderter Dokumenttitel allein reicht nicht für alle Hilfstechniken.\",\"exercises\":[{\"level\":1,\"task\":\"Füge eine Route /reports hinzu, die für die Rollen \\\"user\\\" und \\\"admin\\\" erreichbar ist und Anmeldung verlangt. Schreibe Tests für Gast, user und admin.\",\"acceptance\":\"Gast wird mit redirect=/reports zur Anmeldung geleitet; user und admin erreichen die Seite; der Titel „Berichte · ROOTPFAD Lab“ steht nach der Navigation.\"},{\"level\":2,\"task\":\"Grenzfall: Lege eine Route mit roles: [] an und sage vorher voraus, wer sie öffnen kann. Prüfe dein Ergebnis mit einem Test.\",\"acceptance\":\"Beobachtung: niemand erreicht die Seite (some() auf einer leeren Liste ist false, also /forbidden). Begründung und der Vorschlag, roles: [] als Konfigurationsfehler zu melden, sind notiert.\"},{\"level\":3,\"task\":\"Fehlerfall: Setze requiresAuth: true auf die Route \\\"login\\\" und rufe router.push(\\\"/account\\\") für einen Gast auf. Notiere Fehlermeldung und Verhalten, dann stelle den Code wieder her.\",\"acceptance\":\"Der Router bricht die Umleitungskette mit einer Meldung ab; die Ursache (Guard leitet auf eine selbst geschützte Seite um) ist erklärt.\"}],\"sources\":[{\"url\":\"https://router.vuejs.org/guide/advanced/navigation-guards.html\",\"title\":\"Vue Router: Navigation Guards\"},{\"url\":\"https://router.vuejs.org/guide/advanced/meta.html\",\"title\":\"Vue Router: Route Meta Fields (inkl. TypeScript)\"},{\"url\":\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\",\"title\":\"OWASP Top 10 2021: A01 Broken Access Control\"},{\"url\":\"https://cheatsheetseries.owasp.org/cheatsheets/Unvalidated_Redirects_and_Forwards_Cheat_Sheet.html\",\"title\":\"OWASP Cheat Sheet: Unvalidated Redirects and Forwards\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Alle Tests im vue-lab (vue-router 5.4.0, Vitest 5.1.0, jsdom) grün; Rückgabewerte, NavigationFailure und Pending-Verhalten wurden beobachtet, nicht nur der Dokumentation entnommen. NICHT geprüft: Verhalten im echten Browser mit History-Modus und Server-Fallback, Fokus- und Screenreader-Ansage nach dem Seitenwechsel, serverseitige Autorisierung (das Lab hat kein Backend mit Rollen).\"},\"quiz\":[{\"q\":\"Nach einem Reload zeigt die Anwendung kurz die Anmeldeseite, obwohl die Sitzung noch gültig ist. Was fehlt im Guard am wahrscheinlichsten?\",\"options\":[\"Ein await auf die Wiederherstellung der Sitzung, bevor die Anmeldung geprüft wird.\",\"Ein zusätzliches meta-Feld an der Anmeldeseite, das sie als öffentlich kennzeichnet.\",\"Ein router.afterEach-Hook, der nach dem Seitenwechsel die Anmeldung prüft.\"],\"correct\":0,\"explain\":\"Der Guard muss auf die Sitzungswiederherstellung warten (await auth.ready), sonst entscheidet er mit einem leeren Zustand.\",\"rationales\":[\"Ohne Warten sieht der Guard den leeren Anfangszustand und leitet fälschlich um; mit await bleibt die Navigation offen, bis der Zustand bekannt ist.\",\"Die Anmeldeseite ist ohnehin öffentlich; das erklärt kein Flackern nach einem Reload.\",\"afterEach läuft erst nach dem Wechsel und kann ihn nicht mehr verhindern oder umlenken.\"],\"sources\":[\"https://router.vuejs.org/guide/advanced/navigation-guards.html\",\"https://router.vuejs.org/guide/advanced/meta.html\",\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\",\"https://cheatsheetseries.owasp.org/cheatsheets/Unvalidated_Redirects_and_Forwards_Cheat_Sheet.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Ein Guard schützt /admin mit roles: [\\\"admin\\\"]. Warum ist damit die Verwaltungs-API noch nicht geschützt?\",\"options\":[\"Guards laufen im Browser und lassen sich umgehen; die API muss jede Anfrage selbst prüfen.\",\"Guards prüfen nur Pfade, die mit /admin beginnen, und übersehen Unterseiten wie /admin/users.\",\"Guards dürfen laut Router-Dokumentation keine Rollen auswerten, nur den Anmeldestatus.\"],\"correct\":0,\"explain\":\"Ein Guard ist Bedienkomfort im Browser. Autorisierung muss serverseitig bei jedem Aufruf erfolgen.\",\"rationales\":[\"Wer die Oberfläche kontrolliert (der Nutzer), kann den Guard entfernen oder die API direkt aufrufen; verbindliche Prüfung gehört auf den Server.\",\"Guards laufen für alle passenden Routen, auch für Unterseiten; das Problem liegt nicht in der Pfadabdeckung.\",\"Guards dürfen beliebige Bedingungen prüfen; sie sind nur keine Sicherheitsgrenze.\"],\"sources\":[\"https://router.vuejs.org/guide/advanced/navigation-guards.html\",\"https://router.vuejs.org/guide/advanced/meta.html\",\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\",\"https://cheatsheetseries.owasp.org/cheatsheets/Unvalidated_Redirects_and_Forwards_Cheat_Sheet.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Welcher Wert für ?redirect muss safeRedirectTarget ablehnen, weil er die eigene Anwendung verlässt?\",\"options\":[\"/account?tab=2\",\"/orders/42#top\",\"//evil.example\"],\"correct\":2,\"explain\":\"Nur Werte mit genau einem führenden Schrägstrich sind eigene Pfade; \\\"//host\\\" zeigt auf eine fremde Origin.\",\"rationales\":[\"Ein Pfad der eigenen Anwendung mit Query-Parameter ist ausdrücklich erlaubt.\",\"Ein Pfad mit Fragment (#top) bleibt innerhalb der Anwendung und ist erlaubt.\",\"Zwei Schrägstriche am Anfang bedeuten „gleiches Protokoll, andere Domain“ und sind damit ein Open Redirect.\"],\"sources\":[\"https://router.vuejs.org/guide/advanced/navigation-guards.html\",\"https://router.vuejs.org/guide/advanced/meta.html\",\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\",\"https://cheatsheetseries.owasp.org/cheatsheets/Unvalidated_Redirects_and_Forwards_Cheat_Sheet.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"import { createRouter, createMemoryHistory, type RouteLocationRaw, type Router, type RouterHistory } from 'vue-router';\\nimport { defineComponent, h } from 'vue';\\n\\n// Lektion \\\"Router-Guards\\\": Zugriffsschutz in der Oberfläche ist Komfort, Sicherheit entscheidet das Backend.\\nexport type Role = 'user' | 'admin';\\n\\ndeclare module 'vue-router' {\\n  interface RouteMeta {\\n    requiresAuth?: boolean;      // ohne Anmeldung nicht erreichbar\\n    roles?: readonly Role[];     // mindestens eine dieser Rollen nötig\\n    title?: string;              // Dokumenttitel nach der Navigation\\n  }\\n}\\n\\n/** Was der Guard über die Anmeldung wissen muss. Tests und echte Sitzung implementieren dieselbe Schnittstelle. */\\nexport interface AuthState {\\n  ready: Promise<void>;                  // Sitzung wiederherstellen (z. B. nach Reload), bevor entschieden wird\\n  isLoggedIn(): boolean;\\n  roles(): readonly Role[];\\n}\\n\\n/**\\n * Rücksprungziel nach der Anmeldung. Das Ziel kommt aus der URL und ist damit Fremdeingabe:\\n * Nur Pfade der eigenen Anwendung sind erlaubt, sonst droht ein Open Redirect.\\n */\\nexport function safeRedirectTarget(raw: unknown, fallback = '/'): string {\\n  const value = Array.isArray(raw) ? raw[0] : raw;\\n  if (typeof value !== 'string' || value.length > 2048) return fallback;\\n  if (!value.startsWith('/') || value.startsWith('//') || value.startsWith('/\\\\\\\\')) return fallback;   // \\\"//host\\\" wäre eine andere Origin\\n  if (/[\\\\s\\\\u0000-\\\\u001f\\\\\\\\]/.test(value)) return fallback;                                              // Leerraum, Steuerzeichen, Backslash\\n  return value;\\n}\\n\\nconst page = (name: string) => defineComponent({ name, render: () => h('p', name) });\\n\\nexport function createAppRouter(auth: AuthState, history: RouterHistory = createMemoryHistory()): Router {\\n  const router = createRouter({\\n    history,\\n    routes: [\\n      { path: '/', name: 'home', component: page('Start'), meta: { title: 'Start' } },\\n      { path: '/login', name: 'login', component: page('Anmelden'), meta: { title: 'Anmelden' } },\\n      { path: '/account', name: 'account', component: page('Konto'), meta: { requiresAuth: true, title: 'Mein Konto' } },\\n      { path: '/admin', name: 'admin', component: page('Verwaltung'), meta: { requiresAuth: true, roles: ['admin'], title: 'Verwaltung' } },\\n      { path: '/forbidden', name: 'forbidden', component: page('Kein Zugriff'), meta: { title: 'Kein Zugriff' } },\\n    ],\\n  });\\n\\n  router.beforeEach(async (to) => {\\n    await auth.ready;                                                       // kein Login-Flackern nach einem Reload\\n    if (to.name === 'login' && auth.isLoggedIn()) return safeRedirectTarget(to.query.redirect);\\n    if (!to.meta.requiresAuth) return true;\\n    if (!auth.isLoggedIn()) return { name: 'login', query: { redirect: to.fullPath } } satisfies RouteLocationRaw;\\n    const required = to.meta.roles;\\n    if (required && !required.some((role) => auth.roles().includes(role))) return { name: 'forbidden' };\\n    return true;                                                            // login/forbidden sind nicht geschützt: keine Endlosschleife\\n  });\\n\\n  router.afterEach((to) => {\\n    document.title = to.meta.title ? `${to.meta.title} · ROOTPFAD Lab` : 'ROOTPFAD Lab';\\n  });\\n  return router;\\n}\",\"codeLang\":\"TypeScript\",\"code2\":\"describe('safeRedirectTarget', () => {\\n  it('akzeptiert nur Pfade der eigenen Anwendung', () => {\\n    expect(safeRedirectTarget('/account?tab=2#top')).toBe('/account?tab=2#top');\\n    expect(safeRedirectTarget(['/a', '/b'])).toBe('/a');\\n  });\\n  it('lehnt fremde Ziele, Schemata und Tricks ab (Open Redirect)', () => {\\n    for (const evil of ['https://evil.example', '//evil.example', '/\\\\\\\\evil.example', 'javascript:alert(1)', '/ok\\\\n//evil', '/a b', 'account', '', undefined, 42, null, {}]) {\\n      expect(safeRedirectTarget(evil)).toBe('/');\\n    }\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m4-l2\",\"title\":\"Anmeldung und Token-Erneuerung ohne Endlosschleifen\",\"minutes\":55,\"objectives\":[\"Access-Token und Refresh-Token unterscheiden und begründen, wo jedes gespeichert wird\",\"Einen Fetch-Wrapper bauen, der bei 401 genau einmal erneuert und genau einmal wiederholt („Single Flight“)\",\"Entscheiden, wann eine Sitzung wirklich beendet wird (401/403 bei der Erneuerung) und wann nicht (Netzwerkfehler)\",\"Das Token nur an die eigene Origin senden und die Sitzung beim Start still wiederherstellen\"],\"body\":\"<h2>Lernziele</h2><ul><li>Access-Token und Refresh-Token unterscheiden und begründen, wo jedes gespeichert wird</li><li>Einen Fetch-Wrapper bauen, der bei 401 genau einmal erneuert und genau einmal wiederholt („Single Flight“)</li><li>Entscheiden, wann eine Sitzung wirklich beendet wird (401/403 bei der Erneuerung) und wann nicht (Netzwerkfehler)</li><li>Das Token nur an die eigene Origin senden und die Sitzung beim Start still wiederherstellen</li></ul><p><strong>Voraussetzungen:</strong> Lektion „Router-Guards“; Fehlerzustände und Abbruch bei API-Aufrufen (js-m1-l11); Promises (js-m1-l4).</p><h2>In einfachen Worten</h2><p>Wenn du dich anmeldest, bekommt dein Browser einen „Ausweis“: das Access-Token. Es ist absichtlich kurzlebig (wenige Minuten). Du hältst es bei jeder Anfrage hoch („Authorization: Bearer …“), und der Server weiß, wer du bist. Wird der Ausweis ungültig, antwortet der Server mit 401 („nicht angemeldet“).</p><p>Damit du dich nicht alle paar Minuten neu anmelden musst, gibt es einen zweiten, langlebigen Schlüssel: das Refresh-Token. Es liegt als Cookie beim Browser, aber mit dem Merkmal httpOnly: Dein JavaScript kann es weder lesen noch stehlen. Läuft der Ausweis ab, schickt die Anwendung das Cookie an den Server und bekommt einen frischen Ausweis zurück. Danach wiederholt sie die abgelehnte Anfrage, und der Nutzer merkt nichts.</p><p>Die Kunst liegt in den Randfällen: Was, wenn fünf Anfragen gleichzeitig scheitern? (Nur einmal erneuern!) Was, wenn auch die Erneuerung scheitert? (Dann ist die Sitzung wirklich vorbei.) Was, wenn nur das WLAN weg ist? (Dann nicht ausloggen!) Und: Der Ausweis darf niemals an fremde Server gehen.</p><h2>Schritt für Schritt</h2><ol><li>Das Token lebt nur in einer Variable im Arbeitsspeicher (let accessToken). Es steht weder in localStorage noch in sessionStorage noch in der URL. Der Test prüft, dass nach dem Login kein Eintrag in localStorage steht.</li><li>login(credentials) sendet die Zugangsdaten per POST und liest die Antwort nicht ungeprüft, sondern mit einem Zod-Schema (accessToken: nicht leerer Text). Eine kaputte Antwort wird so zum Fehler statt zu einem undefinierten Token.</li><li>authFetch(url, init) hängt \\\"Authorization: Bearer …\\\" nur an, wenn die URL zur eigenen Origin gehört (isOwnOrigin). Der Test ruft eine fremde Adresse auf und prüft, dass kein Header gesendet wird.</li><li>Kommt 401 zurück, ruft authFetch refresh() auf. refresh() merkt sich das laufende Promise (refreshing ??= …). Alle parallelen Anfragen teilen dieses eine Promise: „Single Flight“. Im Test lösen fünf gleichzeitige Anfragen genau einen Refresh aus.</li><li>Danach folgt genau eine Wiederholung mit dem neuen Token. Bleibt es bei 401, gibt authFetch die Antwort an den Aufrufer zurück, es gibt keine zweite Erneuerung und keine Endlosschleife.</li><li>Wiederholt wird nur, was sich wiederholen lässt: Ein String-Body kann erneut gesendet werden. Ein Stream (ReadableStream) wurde schon verbraucht; er wird nicht automatisch wiederholt, der Aufrufer bekommt die 401.</li><li>Scheitert die Erneuerung mit 401 oder 403, ist das Refresh-Token ungültig: Das Token wird verworfen, onSessionExpired() läuft (z. B. Navigation zur Anmeldung) und ein SessionExpiredError wird geworfen.</li><li>Scheitert sie dagegen mit einem Netzwerkfehler (TypeError aus fetch) oder 5xx, bleibt die Sitzung bestehen: Der Fehler geht an den Aufrufer. Wer im Tunnel kurz offline ist, wird nicht abgemeldet.</li><li>restore() versucht beim Start still, ein Token zu erneuern. createSession nutzt es: Gelingt es, lädt die Sitzung /api/me (Name und Rollen vom Server); misslingt es, bleibt der Nutzer abgemeldet. ready ist ein Promise, das auch bei Fehlern erfüllt wird, damit der Router-Guard nie ewig wartet.</li><li>Im Zusammenspiel mit Lektion 1 zeigen zwei Tests: Mit gültigem Cookie landet ein Reload direkt auf /account ohne Anmeldeseite; ohne Cookie geht es zu /login, und nach dem Login führt das Rücksprungziel zurück.</li></ol><h2>Hintergrund: Warum ist das so?</h2><p>Warum zwei Token? Ein einzelnes, langlebiges Token wäre bequem, aber gefährlich: Wer es einmal abgreift, hat tagelang Zugriff. Das kurzlebige Access-Token begrenzt den Schaden. Das langlebige Refresh-Token ist besser geschützt: Es liegt als httpOnly-Cookie, wird nur an den Erneuerungsendpunkt gesendet und kann vom Server widerrufen werden. Üblich ist außerdem, bei jeder Erneuerung ein neues Refresh-Token auszustellen und das alte zu entwerten („Rotation“). Genau deshalb ist Single Flight keine Schönheitsfrage: Würden fünf Anfragen fünfmal erneuern, könnte der Server die zweite Verwendung eines schon rotierten Tokens als Diebstahl werten und die ganze Sitzung beenden.</p><p>Warum nicht localStorage? Jedes Skript, das in deiner Seite läuft, kann localStorage lesen: eingeschleuster Code (XSS), eine kompromittierte Bibliothek, eine Browsererweiterung mit Seitenzugriff. Ein Wert im Arbeitsspeicher einer Variable ist nicht unangreifbar, aber schwerer abzugreifen und verschwindet beim Schließen des Tabs. Der Preis: Nach einem Reload muss die Sitzung per Refresh-Cookie wiederhergestellt werden (restore).</p><p>Warum braucht der Refresh-Aufruf Schutz gegen CSRF? Cookies sendet der Browser automatisch mit, auch wenn eine fremde Seite die Anfrage auslöst. Der Server muss deshalb den Erneuerungsendpunkt absichern (SameSite-Attribut am Cookie, Prüfung von Origin oder eines benutzerdefinierten Headers wie X-Requested-With, der von fremden Seiten ohne Erlaubnis nicht gesetzt werden kann). Das Lab sendet den Header, den Server dazu baut das Lab nicht: Es hat eine simulierte Gegenseite, keine echte Anmeldung. Eine Alternative für viele Anwendungen ist das „Backend for Frontend“-Muster: Das JavaScript erhält gar kein Token, sondern nur ein Sitzungs-Cookie, und ein eigener Server spricht mit den APIs.</p><p>Warum Rollen vom Server statt aus dem Token lesen? Ein Token lässt sich dekodieren, aber die Oberfläche kann nicht prüfen, ob es echt ist. Rollen aus einem selbst dekodierten Token wären eine ungeprüfte Behauptung. Der Server liefert sie über /api/me, und er setzt sie bei jedem Zugriff selbst durch.</p><h2>Begriffe auf einen Blick</h2><dl><dt>Access-Token</dt><dd>Kurzlebiger Ausweis, der mit jeder API-Anfrage mitgeschickt wird. Läuft er ab, antwortet der Server mit 401.</dd><dt>Refresh-Token</dt><dd>Langlebiger Schlüssel, nur zum Holen neuer Access-Token. Hier als httpOnly-Cookie, also nicht per JavaScript lesbar.</dd><dt>httpOnly-Cookie</dt><dd>Cookie, das der Browser nur mitsendet und das Skripte der Seite nicht lesen können. Schützt vor dem Abgreifen durch XSS.</dd><dt>Bearer</dt><dd>Schema des Authorization-Headers (RFC 6750): „Wer dieses Token vorzeigt, wird bedient“. Deshalb darf es nie an Fremde gehen.</dd><dt>Single Flight</dt><dd>Mehrere gleichzeitige Anforderungen derselben Sache teilen sich einen einzigen laufenden Vorgang.</dd><dt>401 und 403</dt><dd>401: nicht (mehr) angemeldet bzw. Zugangsdaten ungültig. 403: angemeldet, aber nicht berechtigt. Nur 401 am Datenendpunkt löst eine Erneuerung aus.</dd><dt>CSRF</dt><dd>Cross-Site Request Forgery: Eine fremde Seite löst im Namen des Nutzers eine Anfrage aus, weil der Browser Cookies automatisch mitsendet.</dd></dl><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>auth/<wbr>authClient.ts</code> (Ausschnitt ab „export function createAuthClient“)</li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>auth/<wbr>session.ts</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (tests/auth.spec.ts): 13 Tests grün\\n - Login: Token im Speicher, \\\"Authorization: Bearer access-1\\\"; localStorage ohne Token; falsches Passwort -&gt; HttpError 401\\n - Ablauf bei Ablauf des Tokens: GET /api/me (401) -&gt; POST /auth/refresh -&gt; GET /api/me (200, \\\"Bearer access-2\\\")\\n - 5 parallele Anfragen mit abgelaufenem Token -&gt; genau 1 Refresh\\n - Refresh 401 -&gt; SessionExpiredError, onSessionExpired 1x, Token verworfen\\n - Refresh Netzwerkfehler -&gt; TypeError an den Aufrufer, Sitzung bleibt\\n - dauerhaft 401 -&gt; nur 1 Refresh, Antwort 401 an den Aufrufer (keine Schleife)\\n - String-Body wird mit gleichem Inhalt wiederholt; Stream-Body nicht\\n - fremde Origin -&gt; kein Authorization-Header\\n - Reload mit Cookie -&gt; /account ohne Anmeldeseite, Nutzer \\\"Ada\\\"; ohne Cookie -&gt; /login, nach Login Rücksprung</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> Das Access-Token in localStorage zu speichern, „damit es den Reload überlebt“.<br><strong>Warum:</strong> Jedes Skript der Seite kann localStorage lesen. Ein einziger XSS-Fehler oder eine kompromittierte Bibliothek genügt, um das Token zu stehlen.<br><strong>Besser:</strong> Token im Arbeitsspeicher halten und die Sitzung beim Start über das httpOnly-Refresh-Cookie wiederherstellen (restore).</li><li><strong>Falsch:</strong> Bei jeder 401-Antwort einzeln zu erneuern.<br><strong>Warum:</strong> Fünf parallele Anfragen lösen fünf Erneuerungen aus. Bei rotierenden Refresh-Token ist die zweite Verwendung ein Verdachtsfall, und der Server kann die Sitzung beenden.<br><strong>Besser:</strong> Ein laufendes Promise merken und teilen (Single Flight), danach jede Anfrage genau einmal wiederholen.</li><li><strong>Falsch:</strong> Nach der Wiederholung bei erneutem 401 wieder zu erneuern.<br><strong>Warum:</strong> Es entsteht eine Endlosschleife (401 → Refresh → 401 → …), die den Server und die Anmeldeseite flutet.<br><str";
RP_LITERAL_2_text += "ong>Besser:</strong> Genau eine Wiederholung; bleibt es bei 401, gibt der Aufrufer die Entscheidung (z. B. „keine Berechtigung“).</li><li><strong>Falsch:</strong> Jeden Fehler bei der Erneuerung als Abmeldung zu behandeln.<br><strong>Warum:</strong> Ein kurzer Netzausfall oder ein 503 meldet den Nutzer ab, obwohl die Sitzung gültig ist. Das ist ärgerlich und kann Eingaben vernichten.<br><strong>Besser:</strong> Nur 401 und 403 beenden die Sitzung. Netzwerk- und Serverfehler gehen als Fehler weiter; die Oberfläche bietet „Erneut versuchen“ an.</li><li><strong>Falsch:</strong> Das Token an jede URL zu hängen, auch an fremde.<br><strong>Warum:</strong> Ein Bearer-Token gilt für jeden, der es vorzeigt. Ein Drittanbieter, der es erhält, kann sich damit ausgeben.<br><strong>Besser:</strong> Vor dem Senden die Origin vergleichen (isOwnOrigin) und nur an eigene API-Adressen anhängen.</li><li><strong>Falsch:</strong> Rollen aus dem dekodierten Token zu lesen und der Oberfläche zu vertrauen.<br><strong>Warum:</strong> Die Oberfläche kann ein Token nicht beglaubigen. Manipulierte Anzeigewerte führen zu falschen Menüs; schlimmer ist der Eindruck, damit sei etwas geschützt.<br><strong>Besser:</strong> Rollen vom Server per /api/me holen; Berechtigungen prüft der Server bei jedem Zugriff.</li></ul><h2>Praxis</h2><p>Lege dir für jede Anmeldelösung eine Liste an: Wo liegt welches Token? Wer kann es lesen? Wie lange gilt es? Was passiert bei 401, 403, 5xx und Netzwerkfehler? Diese Tabelle gehört in die Projektdokumentation und in die Tests. Bei neuen Projekten lohnt die Frage, ob ein Sitzungs-Cookie mit „Backend for Frontend“ nicht einfacher und sicherer ist als Tokens im Browser. Schreibe nie Token oder Cookies in Logs, URLs oder Fehlermeldungen.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze einen Test für logout(): Nach dem Abmelden lehnt der Server /api/me ab, hasToken ist false, und eine erneute Wiederherstellung (restore) schlägt fehl.<br><em>Abnahme:</em> Nach logout() ist hasToken false; restore() liefert false, weil das Refresh-Cookie am Server verworfen ist.</li><li><strong>Grenzfall:</strong> Lasse zehn Anfragen gleichzeitig mit abgelaufenem Token laufen und starte zusätzlich eine elfte Anfrage 5 ms später, während die Erneuerung noch läuft. Zähle die Refresh-Aufrufe.<br><em>Abnahme:</em> Genau ein Refresh; die späte Anfrage nutzt dieselbe Erneuerung. Der Ablauf ist in einem Zeitdiagramm skizziert.</li><li><strong>Fehlerfall:</strong> Lasse /auth/refresh mit 500 antworten und rufe authFetch auf. Welche Ausnahme kommt an, bleibt die Sitzung bestehen, und was zeigt die Oberfläche? Entscheide, ob 500 eine Abmeldung rechtfertigt.<br><em>Abnahme:</em> HttpError mit Status 500, onSessionExpired läuft nicht; begründete Entscheidung („Serverfehler beenden die Sitzung nicht“) und ein „Erneut versuchen“-Konzept sind notiert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">OWASP Cheat Sheet: Session Management</a> – Nur verlinkt und zusammengefasst; Rechte liegen bei den jeweiligen Herausgebern.</li><li><a href=\\\"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">OWASP Cheat Sheet: CSRF Prevention</a> – Nur verlinkt und zusammengefasst; Rechte liegen bei den jeweiligen Herausgebern.</li><li><a href=\\\"https://www.rfc-editor.org/rfc/rfc6750.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">RFC 6750: The OAuth 2.0 Bearer Token Usage</a> – IETF-Standard; nur verlinkt.</li><li><a href=\\\"https://datatracker.ietf.org/doc/draft-ietf-oauth-browser-based-apps/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">IETF-Entwurf: OAuth 2.0 for Browser-Based Applications</a> – Entwurf (Draft), kein endgültiger Standard; Inhalt kann sich ändern.</li><li><a href=\\\"https://developer.mozilla.org/en-US/docs/Web/API/Request/credentials\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">MDN: Fetch API, Option credentials</a> – MDN-Webdokumentation (Texte unter CC BY-SA); hier nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Alle Tests im vue-lab grün (13 Tests, simulierter Server mit ablaufenden Tokens und simuliertem Refresh-Cookie; Zod 4.6.7). NICHT geprüft: ein echter Server mit httpOnly-Cookies, SameSite-Verhalten, CORS-Konfiguration, Rotation von Refresh-Token und CSRF-Schutz (das Lab hat nur den Client und eine Fake-Gegenseite); das Spring-Lab dieses Pfads enthält keine Anmeldung. Der IETF-Entwurf ist noch nicht final.</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Lege dir für jede Anmeldelösung eine Liste an: Wo liegt welches Token? Wer kann es lesen? Wie lange gilt es? Was passiert bei 401, 403, 5xx und Netzwerkfehler? Diese Tabelle gehört in die Projektdokumentation und in die Tests. Bei neuen Projekten lohnt die Frage, ob ein Sitzungs-Cookie mit „Backend for Frontend“ nicht einfacher und sicherer ist als Tokens im Browser. Schreibe nie Token oder Cookies in Logs, URLs oder Fehlermeldungen.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze einen Test für logout(): Nach dem Abmelden lehnt der Server /api/me ab, hasToken ist false, und eine erneute Wiederherstellung (restore) schlägt fehl.\",\"acceptance\":\"Nach logout() ist hasToken false; restore() liefert false, weil das Refresh-Cookie am Server verworfen ist.\"},{\"level\":2,\"task\":\"Grenzfall: Lasse zehn Anfragen gleichzeitig mit abgelaufenem Token laufen und starte zusätzlich eine elfte Anfrage 5 ms später, während die Erneuerung noch läuft. Zähle die Refresh-Aufrufe.\",\"acceptance\":\"Genau ein Refresh; die späte Anfrage nutzt dieselbe Erneuerung. Der Ablauf ist in einem Zeitdiagramm skizziert.\"},{\"level\":3,\"task\":\"Fehlerfall: Lasse /auth/refresh mit 500 antworten und rufe authFetch auf. Welche Ausnahme kommt an, bleibt die Sitzung bestehen, und was zeigt die Oberfläche? Entscheide, ob 500 eine Abmeldung rechtfertigt.\",\"acceptance\":\"HttpError mit Status 500, onSessionExpired läuft nicht; begründete Entscheidung („Serverfehler beenden die Sitzung nicht“) und ein „Erneut versuchen“-Konzept sind notiert.\"}],\"sources\":[{\"url\":\"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html\",\"title\":\"OWASP Cheat Sheet: Session Management\"},{\"url\":\"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html\",\"title\":\"OWASP Cheat Sheet: CSRF Prevention\"},{\"url\":\"https://www.rfc-editor.org/rfc/rfc6750.html\",\"title\":\"RFC 6750: The OAuth 2.0 Bearer Token Usage\"},{\"url\":\"https://datatracker.ietf.org/doc/draft-ietf-oauth-browser-based-apps/\",\"title\":\"IETF-Entwurf: OAuth 2.0 for Browser-Based Applications\"},{\"url\":\"https://developer.mozilla.org/en-US/docs/Web/API/Request/credentials\",\"title\":\"MDN: Fetch API, Option credentials\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Alle Tests im vue-lab grün (13 Tests, simulierter Server mit ablaufenden Tokens und simuliertem Refresh-Cookie; Zod 4.6.7). NICHT geprüft: ein echter Server mit httpOnly-Cookies, SameSite-Verhalten, CORS-Konfiguration, Rotation von Refresh-Token und CSRF-Schutz (das Lab hat nur den Client und eine Fake-Gegenseite); das Spring-Lab dieses Pfads enthält keine Anmeldung. Der IETF-Entwurf ist noch nicht final.\"},\"quiz\":[{\"q\":\"Fünf Anfragen scheitern gleichzeitig mit 401. Wie viele Aufrufe von /auth/refresh sendet authFetch?\",\"options\":[\"Fünf, damit jede Anfrage ihr eigenes frisches Token bekommt und unabhängig bleibt.\",\"Genau einen: Die Anfragen teilen sich dieselbe laufende Erneuerung und werden danach wiederholt.\",\"Keinen, weil bei einem 401 die Sitzung immer sofort beendet und zur Anmeldung gewechselt wird.\"],\"correct\":1,\"explain\":\"Single Flight verhindert mehrfache Erneuerungen und schützt rotierende Refresh-Token.\",\"rationales\":[\"Fünf Erneuerungen verschwenden Anfragen und können bei rotierenden Refresh-Token die Sitzung beenden.\",\"So funktioniert Single Flight: ein Promise wird gemerkt und geteilt; der Test belegt genau einen Aufruf.\",\"Ein 401 am Datenendpunkt löst zuerst eine Erneuerung aus; nur wenn sie mit 401/403 scheitert, endet die Sitzung.\"],\"sources\":[\"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html\",\"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html\",\"https://www.rfc-editor.org/rfc/rfc6750.html\",\"https://datatracker.ietf.org/doc/draft-ietf-oauth-browser-based-apps/\",\"https://developer.mozilla.org/en-US/docs/Web/API/Request/credentials\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Wo wird das Access-Token in diesem Entwurf gespeichert, und warum?\",\"options\":[\"In einer Variable im Arbeitsspeicher, weil Skripte der Seite localStorage lesen können und Tokens dort leichter gestohlen werden.\",\"In localStorage, weil es nur dort einen Reload übersteht und deshalb am bequemsten und sichersten ist.\",\"In der URL als Query-Parameter, weil Links dann überall und ohne Cookie funktionieren.\"],\"correct\":0,\"explain\":\"Ein Token im Arbeitsspeicher ist schwerer abzugreifen als eines in localStorage; der Preis ist die Wiederherstellung beim Start.\",\"rationales\":[\"Der Speicherort begrenzt die Angriffsfläche; die Sitzung wird beim Start per httpOnly-Cookie wiederhergestellt.\",\"localStorage ist für jedes Skript der Seite lesbar; Bequemlichkeit ist hier kein Sicherheitsargument.\",\"URLs landen in Verlauf, Logs und Referer-Headern; Token gehören nie dorthin.\"],\"sources\":[\"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html\",\"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html\",\"https://www.rfc-editor.org/rfc/rfc6750.html\",\"https://datatracker.ietf.org/doc/draft-ietf-oauth-browser-based-apps/\",\"https://developer.mozilla.org/en-US/docs/Web/API/Request/credentials\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Die Erneuerung scheitert mit einem Netzwerkfehler (TypeError aus fetch). Was ist die richtige Reaktion?\",\"options\":[\"Sofort abmelden und zur Anmeldeseite wechseln, damit die Sitzung sicher beendet ist.\",\"Die Anfrage unbegrenzt wiederholen, bis das Netz wieder erreichbar ist.\",\"Den Fehler an den Aufrufer geben und die Sitzung behalten; die Oberfläche bietet „Erneut versuchen“ an.\"],\"correct\":2,\"explain\":\"Netzwerkfehler sind vorübergehend: Sitzung behalten, Fehler melden, Wiederholung anbieten.\",\"rationales\":[\"Ein Netzausfall sagt nichts über die Gültigkeit der Sitzung; Abmelden würde Eingaben unnötig vernichten.\",\"Unbegrenzte Wiederholung erzeugt eine Dauerschleife und belastet das Gerät und später den Server.\",\"Nur 401/403 bei der Erneuerung beenden die Sitzung; alles andere ist ein vorübergehendes Problem.\"],\"sources\":[\"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html\",\"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html\",\"https://www.rfc-editor.org/rfc/rfc6750.html\",\"https://datatracker.ietf.org/doc/draft-ietf-oauth-browser-based-apps/\",\"https://developer.mozilla.org/en-US/docs/Web/API/Request/credentials\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"export function createAuthClient({ fetcher = fetch, origin = location.origin, onSessionExpired }: AuthClientOptions = {}) {\\n  let accessToken: string | null = null;\\n  let refreshing: Promise<string> | null = null;      // \\\"Single Flight\\\": parallele 401er teilen sich EINE Erneuerung\\n\\n  const isOwnOrigin = (url: string) => new URL(url, origin).origin === new URL(origin).origin;\\n\\n  async function requestToken(path: string, init: RequestInit): Promise<string> {\\n    const response = await fetcher(path, { ...init, credentials: 'include', headers: { 'Content-Type': 'application/json', ...init.headers } });\\n    if (!response.ok) throw new HttpError(response.status);\\n    return tokenResponseSchema.parse(await response.json()).accessToken;     // Fremdantwort erst prüfen, dann benutzen\\n  }\\n\\n  function refresh(): Promise<string> {\\n    refreshing ??= requestToken('/auth/refresh', { method: 'POST', headers: { 'X-Requested-With': 'fetch' } })   // Header erschwert CSRF\\n      .then((token) => { accessToken = token; return token; })\\n      .finally(() => { refreshing = null; });\\n    return refreshing;\\n  }\\n\\n  function expire(): never {\\n    accessToken = null;\\n    onSessionExpired?.();\\n    throw new SessionExpiredError();\\n  }\\n\\n  /** Wie fetch, aber mit Token, einmaliger Erneuerung bei 401 und genau einer Wiederholung. */\\n  async function authFetch(url: string, init: RequestInit = {}): Promise<Response> {\\n    const withToken = (token: string | null): RequestInit =>\\n      token && isOwnOrigin(url) ? { ...init, headers: { ...init.headers, Authorization: `Bearer ${token}` } } : init;\\n\\n    const first = await fetcher(url, withToken(accessToken));\\n    if (first.status !== 401 || !isOwnOrigin(url)) return first;\\n    // Ein Stream-Body kann nicht zweimal gesendet werden: dann nicht automatisch wiederholen.\\n    if (init.body !== undefined && init.body !== null && typeof init.body !== 'string') return first;\\n\\n    let fresh: string;\\n    try {\\n      fresh = await refresh();\\n    } catch (error) {\\n      if (error instanceof HttpError && (error.status === 401 || error.status === 403)) expire();   // Refresh-Token ungültig\\n      throw error;                                                                                  // Netzwerkfehler: Sitzung behalten\\n    }\\n    return fetcher(url, withToken(fresh));                  // genau eine Wiederholung, danach entscheidet der Aufrufer\\n  }\\n\\n  return {\\n    async login(credentials: { email: string; password: string }) {\\n      accessToken = await requestToken('/auth/login', { method: 'POST', body: JSON.stringify(credentials) });\\n    },\\n    /** Stille Wiederherstellung beim Start: gibt es noch ein gültiges Refresh-Cookie? */\\n    async restore(): Promise<boolean> {\\n      try { await refresh(); return true; }\\n      catch (error) {\\n        if (error instanceof HttpError && (error.status === 401 || error.status === 403)) return false;\\n        throw error;\\n      }\\n    },\\n    async logout() {\\n      accessToken = null;\\n      await fetcher('/auth/logout', { method: 'POST', credentials: 'include', headers: { 'X-Requested-With': 'fetch' } });\\n    },\\n    authFetch,\\n    get hasToken() { return accessToken !== null; },\\n  };\\n}\\nexport type AuthClient = ReturnType<typeof createAuthClient>;\",\"codeLang\":\"TypeScript\",\"code2\":\"import * as z from 'zod';\\nimport type { AuthState, Role } from '../router/guards';\\nimport { HttpError, type AuthClient } from './authClient';\\n\\n// Die Rollen kommen vom Server (/api/me), nie aus einem selbst dekodierten Token: Die Oberfläche\\n// darf Rollen anzeigen und Menüs filtern, die Berechtigung prüft immer das Backend.\\nconst meSchema = z.object({ id: z.number().int(), name: z.string(), roles: z.array(z.enum(['user', 'admin'])) });\\nexport type Me = z.infer<typeof meSchema>;\\n\\nexport interface Session extends AuthState {\\n  user(): Me | null;\\n  login(credentials: { email: string; password: string }): Promise<void>;\\n  logout(): Promise<void>;\\n  clear(): void;\\n}\\n\\nexport function createSession(client: AuthClient): Session {\\n  let me: Me | null = null;\\n\\n  async function loadMe() {\\n    const response = await client.authFetch('/api/me');\\n    if (!response.ok) throw new HttpError(response.status);\\n    me = meSchema.parse(await response.json());\\n  }\\n\\n  // Beim Start still versuchen, die Sitzung wiederherzustellen. Fehler dürfen den Start nicht blockieren.\\n  const ready = client.restore().then((restored) => (restored ? loadMe() : undefined)).catch(() => undefined);\\n\\n  return {\\n    ready,\\n    isLoggedIn: () => me !== null,\\n    roles: () => (me?.roles ?? []) as readonly Role[],\\n    user: () => me,\\n    async login(credentials) { await client.login(credentials); await loadMe(); },\\n    async logout() { me = null; await client.logout(); },\\n    clear() { me = null; },\\n  };\\n}\",\"code2Lang\":\"TypeScript\"},{\"id\":\"js-m4-l3\",\"title\":\"Moderne Vue-3.5-APIs: useId, useTemplateRef, defineExpose und Attribute\",\"minutes\":45,\"objectives\":[\"Mit useId eindeutige, SSR-stabile ids für Beschriftung, Hinweis und Fehlermeldung erzeugen\",\"Mit useTemplateRef typisierte Template-Refs verwenden und erklären, wie sie sich von der älteren Schreibweise unterscheiden\",\"Mit defineExpose bewusst festlegen, was eine Komponente nach außen freigibt (z. B. focus())\",\"Mit defineOptions({ inheritAttrs: false }) Attribute gezielt an das Eingabefeld statt an den Wrapper leiten und Props reaktiv destrukturieren\"],\"body\":\"<h2>Lernziele</h2><ul><li>Mit useId eindeutige, SSR-stabile ids für Beschriftung, Hinweis und Fehlermeldung erzeugen</li><li>Mit useTemplateRef typisierte Template-Refs verwenden und erklären, wie sie sich von der älteren Schreibweise unterscheiden</li><li>Mit defineExpose bewusst festlegen, was eine Komponente nach außen freigibt (z. B. focus())</li><li>Mit defineOptions({ inheritAttrs: false }) Attribute gezielt an das Eingabefeld statt an den Wrapper leiten und Props reaktiv destrukturieren</li></ul><p><strong>Voraussetzungen:</strong> Lektion „defineModel“ (js-m2-l1); Props, Emits, Slots und zugängliche Formulare (js-m1-l10).</p><h2>In einfachen Worten</h2><p>Ein gutes Formularfeld besteht aus mehr als einem &lt;input&gt;: Es hat eine Beschriftung, vielleicht einen Hinweis („Wir senden nur eine Bestätigung“) und im Fehlerfall eine Fehlermeldung. Damit Screenreader das zusammen vorlesen, müssen diese Teile über ids miteinander verbunden sein: label for=…, aria-describedby=…. Wenn du dieselbe Komponente zehnmal verwendest, braucht jedes Feld seine eigene, eindeutige id. Das erledigt useId für dich.</p><p>Dazu kommen drei Fragen, die jede wiederverwendbare Komponente beantworten muss. Erstens: Welche Attribute gehören wohin? Ein class gehört an den äußeren Rahmen, aber type=\\\"email\\\" und autocomplete gehören an das Eingabefeld. Zweitens: Wie kommt der Elternteil an das Feld, um es zu fokussieren? Die Antwort: nur über das, was die Komponente ausdrücklich freigibt (defineExpose). Drittens: Wie bekomme ich das &lt;input&gt; selbst in die Hand, ohne document.querySelector? Mit einer Template-Ref.</p><p>Alle vier Werkzeuge (useId, useTemplateRef, defineExpose, inheritAttrs) sind klein. Zusammen machen sie aus einem Eingabefeld einen sauberen Baustein, den du in jedem Formular wiederverwenden kannst.</p><h2>Schritt für Schritt</h2><ol><li>defineOptions({ inheritAttrs: false }) schaltet das automatische Durchreichen von Attributen an das Wurzelelement ab. Ohne das würden type, autocomplete und data-* am äußeren &lt;div&gt; landen, wo sie nichts bewirken.</li><li>const { label, hint, error } = defineProps&lt;…&gt;() destrukturiert die Props. Seit Vue 3.5 schreibt der Compiler das so um, dass die Werte reaktiv bleiben: Ändert der Elternteil error, aktualisiert sich das Template. (Vor 3.5 wäre das eine Momentaufnahme gewesen.)</li><li>const model = defineModel&lt;string&gt;({ default: \\\"\\\" }) bildet v-model ab (Lektion js-m2-l1).</li><li>const id = useId() liefert eine id, die pro Aufruf eindeutig ist und beim Server-Rendering und im Browser dieselbe ist. Aus ihr werden drei Namen: id (Feld), `${id}-hint` und `${id}-error`. useId gehört in setup, nicht in computed (die Doku warnt davor).</li><li>describedBy ist ein computed, das nur die ids der tatsächlich vorhandenen Texte zusammensetzt. Gibt es weder Hinweis noch Fehler, entfällt aria-describedby ganz, ebenso aria-invalid. Leere Verweise auf nicht existierende ids sind selbst ein Fehler.</li><li>const input = useTemplateRef&lt;HTMLInputElement&gt;(\\\"input\\\") liefert eine typisierte Ref auf das Element, dessen Attribut ref=\\\"input\\\" lautet. Der Name im String ist die Verbindung, es muss keine gleichnamige Variable geben (das war die ältere Schreibweise). Vor dem Einhängen ist der Wert null.</li><li>inputAttrs() trennt class und style ab (sie gehören an den Wrapper) und gibt alle übrigen Attribute an das &lt;input&gt;. Es ist eine Funktion im Template statt ein computed, weil $attrs laut Vue-Doku nicht reaktiv ist: Ein computed würde sich nicht aktualisieren.</li><li>defineExpose({ focus }) gibt als einziges frei, dass der Elternteil focus() aufrufen darf. Komponenten mit script setup sind sonst „geschlossen“: Eine Ref des Elternteils sieht nichts von dem, was drinnen passiert.</li><li>SignupForm.vue nutzt FormField zweimal und holt die Instanzen mit useTemplateRef&lt;InstanceType&lt;typeof FormField&gt;&gt;(\\\"nameField\\\"). Beim Absenden fokussiert sie das erste fehlerhafte Feld über die freigegebene focus()-Methode.</li><li>Die Tests prüfen: Verknüpfung von Label, Hinweis und Fehler; unterschiedliche ids bei mehreren Instanzen; Wegfall der aria-Attribute; Aufteilung von class und type; reaktive Props; dass nur focus() freigegeben ist; und die Fokusreihenfolge im Elternformular.</li></ol><h2>Hintergrund: Warum ist das so?</h2><p>Warum useId statt eigenem Zähler oder Math.random? Bei Server-Side-Rendering (SSR) wird das HTML zuerst auf dem Server erzeugt und im Browser „übernommen“ (Hydration). Wenn der Browser andere ids berechnet als der Server, passen Beschriftung und Feld nicht mehr zusammen, und Vue meldet einen Hydration-Mismatch. useId ist so gebaut, dass Server und Browser dieselben Werte bekommen. Gleichzeitig sind die Werte pro Anwendung eindeutig. Laufen auf einer Seite mehrere getrennte Vue-Apps, können deren ids kollidieren; dafür gibt es app.config.idPrefix. Mit Präfix sehen die ids anders aus (z. B. \\\"myApp:0\\\"); der Doppelpunkt muss in CSS-Selektoren maskiert werden (im Test mit CSS.escape).</p><p>Warum sind Komponenten standardmäßig „geschlossen“? Wenn Eltern in das Innere greifen könnten, wäre jede Umbenennung einer internen Variable ein Bruch für alle Verwender. Mit defineExpose legst du einen kleinen, öffentlichen Vertrag fest (hier: focus). Alles andere darfst du frei ändern. Das ist dasselbe Prinzip wie bei privaten Methoden in einer Klasse.</p><p>Warum Attribute teilen? Ein Eingabefeld hat zwei Ebenen: Der Rahmen (div mit class, Abständen, Layout) und das eigentliche Feld (type, autocomplete, inputmode, data-testid, required). Verwender wollen beides beeinflussen, ohne die Interna zu kennen. Mit inheritAttrs: false entscheidest du selbst, wohin welches Attribut geht, statt dich auf die Voreinstellung (alles an das Wurzelelement) zu verlassen.</p><p>Eine Falle am Rande: Ein HTML-Kommentar vor dem Wurzelelement im Template macht die Komponente im Entwicklungs- und Testmodus zu einem Fragment mit mehreren Wurzeln. Im Lab ist genau das beim ersten Test aufgefallen (wrapper.element zeigte auf den Kommentar). Kommentare gehören deshalb in den Script-Teil.</p><h2>Begriffe auf einen Blick</h2><dl><dt>useId()</dt><dd>Erzeugt eine pro Anwendung eindeutige id, die bei Server- und Browser-Rendering gleich ist. Gedacht für Beschriftungen und ARIA-Verweise.</dd><dt>Template-Ref</dt><dd>Verbindung zwischen einem Element oder einer Komponente im Template und einer Variable im Script. Mit useTemplateRef („name“) typisiert und ohne gleichnamige Variable lesbar.</dd><dt>Fallthrough-Attribute</dt><dd>Attribute, die ein Elternteil an eine Komponente setzt, die diese aber nicht als Prop deklariert. Standardmäßig landen sie am Wurzelelement.</dd><dt>aria-describedby</dt><dd>Verweist auf Elemente (per id), deren Text das Feld zusätzlich beschreibt, z. B. Hinweis und Fehlermeldung. Screenreader lesen sie nach der Beschriftung vor.</dd><dt>Hydration</dt><dd>Das „Lebendigmachen“ von serverseitig erzeugtem HTML im Browser. Dafür müssen erzeugte Werte (wie ids) auf beiden Seiten übereinstimmen.</dd><dt>defineExpose</dt><dd>Legt fest, welche Werte und Funktionen eine script-setup-Komponente per Template-Ref nach außen zeigt. Ohne Aufruf bleibt sie komplett geschlossen.</dd></dl><h2>Der Code</h2><p>Die Beispiele stammen aus dem getesteten Lab im Projektordner und sind nicht aus fremden Quellen kopiert:</p><ul><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>modern/<wbr>FormField.vue</code></li><li><code>content/<wbr>examples/<wbr>vue-lab/<wbr>src/<wbr>lessons/<wbr>modern/<wbr>SignupForm.vue</code></li></ul>\",\"body2\":\"<h2>Ausgabe und Beleg</h2><pre><code>vitest (tests/modern-apis.spec.ts): 9 Tests grün\\n - label for == input id; aria-describedby nennt zwei vorhandene ids; aria-invalid=\\\"true\\\"\\n - zwei Instanzen: unterschiedliche ids; ohne Hinweis/Fehler: weder aria-describedby noch aria-invalid\\n - class/style am Wrapper; type, autocomplete, data-testid am input; input hat keine class\\n - setProps({ label: \\\"Neu\\\", error: \\\"Fehler\\\" }) aktualisiert Beschriftung und Fehlertext (reaktives Destructuring)\\n - exposed Schlüssel: [\\\"focus\\\"]; focus() setzt document.activeElement auf das input\\n - SignupForm: erster Submit -&gt; Fokus Name, zweiter -&gt; Fokus E-Mail; gültige Daten werden gesendet</code></pre><h2>Typische Fehler</h2><ul><li><strong>Falsch:</strong> ids von Hand zu erzeugen (Zähler, Math.random, feste Namen wie \\\"email\\\").<br><strong>Warum:</strong> Feste Namen kollidieren bei mehrfacher Verwendung, Zufallswerte erzeugen Hydration-Fehler beim Server-Rendering. Doppelte ids brechen die Zuordnung von Label und Feld.<br><strong>Besser:</strong> useId() verwenden, daraus Teil-ids ableiten (`${id}-hint`) und bei mehreren Apps app.config.idPrefix setzen.</li><li><strong>Falsch:</strong> useId() innerhalb von computed() aufzurufen.<br><strong>Warum:</strong> Die Vue-Dokumentation warnt davor: Es kann zu Instanzkonflikten kommen, weil der Aufruf an die Komponenteninstanz gebunden ist.<br><strong>Besser:</strong> Einmal in setup aufrufen und den Wert im computed nur lesen (wie describedBy).</li><li><strong>Falsch:</strong> useAttrs() in einem computed zu nutzen und dann auf Änderungen zu warten.<br><strong>Warum:</strong> Die Attributobjekte sind laut Doku nicht reaktiv. Ein computed wertet nur einmal aus und bleibt veraltet.<br><strong>Besser:</strong> Direkt im Template lesen oder eine Funktion im Template aufrufen (inputAttrs()). Für Reaktivität eine Prop deklarieren.</li><li><strong>Falsch:</strong> Per Elternkomponente auf Interna der Kindkomponente zuzugreifen (child.$refs.input) statt eine Methode freizugeben.<br><strong>Warum:</strong> Jede interne Umbenennung bricht alle Verwender. Außerdem sind script-setup-Komponenten ohne defineExpose ohnehin geschlossen: der Zugriff liefert nichts.<br><strong>Besser:</strong> Einen kleinen Vertrag mit defineExpose festlegen (focus) und im Test prüfen, dass nur diese Schlüssel sichtbar sind.</li><li><strong>Falsch:</strong> Vor onMounted auf eine Template-Ref zuzugreifen oder sie nie auf null zu prüfen.<br><strong>Warum:</strong> Bis zum Einhängen ist der Wert null; bei v-if kann das Element auch später wieder verschwinden. Der Zugriff wirft sonst einen Fehler.<br><strong>Besser:</strong> Mit optionaler Verkettung (input.value?.focus()) arbeiten und den Zugriff erst nach dem Einhängen auslösen.</li><li><strong>Falsch:</strong> Kommentare vor das Wurzelelement im Template zu setzen.<br><strong>Warum:</strong> Im Entwicklungsmodus zählt der Kommentar als weiterer Wurzelknoten. Die Komponente wird zum Fragment, und Tests oder Attribut-Weitergabe verhalten sich anders als in der Produktion.<br><strong>Besser:</strong> Kommentare in den Script-Teil oder innerhalb des Wurzelelements setzen.</li></ul><h2>Praxis</h2><p>Zugängliche Formularbausteine sind der Ort, wo sich Sorgfalt am meisten auszahlt: Jede Komponente einmal richtig bauen, dann überall wiederverwenden. Prüfe das Ergebnis mit der Tastatur (Tab, Fokusreihenfolge, Sprung zum ersten Fehler) und mit einem Screenreader, wenn möglich. Halte den freigegebenen Vertrag klein (focus, eventuell select), dokumentiere ihn in einem Satz und teste ihn, damit niemand versehentlich Interna freigibt.</p><h2>Drei Übungen</h2><ol><li><strong>Normalfall:</strong> Ergänze eine Möglichkeit, das Feld als Pflichtfeld zu kennzeichnen: Das Attribut required soll am &lt;input&gt; ankommen, und die Beschriftung zeigt ein sichtbares „(Pflicht)“. Schreibe einen Test.<br><em>Abnahme:</em> required steht am input (nicht am Wrapper); die Beschriftung enthält den Hinweis als Text, nicht nur durch Farbe oder ein Symbol.</li><li><strong>Grenzfall:</strong> Mounte zwei getrennte Vue-Apps mit je einem FormField auf derselben Seite und vergleiche die ids. Setze danach app.config.idPrefix und vergleiche erneut.<br><em>Abnahme:</em> Beobachtung dokumentiert (ohne Präfix können gleiche ids entstehen, mit Präfix nicht); Maskierung des Doppelpunkts im Selektor ist beachtet.</li><li><strong>Fehlerfall:</strong> Entferne defineOptions({ inheritAttrs: false }) und übergib type und data-testid. Wohin gehen die Attribute, und welche Warnung oder welches Verhalten beobachtest du?<br><em>Abnahme:</em> Die Attribute landen am Wrapper-Element, nicht am Feld; type=\\\"email\\\" wirkt nicht; die Beobachtung und die Wiederherstellung des Codes sind notiert.</li></ol><h2>Quellen und Lizenzen</h2><ul><li><a href=\\\"https://vuejs.org/api/composition-api-helpers.html#useid\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: useId() (Composition API Helpers)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/guide/essentials/template-refs.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Template Refs (useTemplateRef, v-for, Funktions-Refs)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/guide/components/attrs.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Fallthrough Attributes ($attrs, inheritAttrs)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://vuejs.org/guide/components/props.html#reactive-props-destructure\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">Vue: Props (Reactive Props Destructure, Vue 3.5)</a> – Offizielle Vue-Dokumentation (CC BY 4.0, © Evan You und Mitwirkende); Inhalt hier eigenständig zusammengefasst.</li><li><a href=\\\"https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA1.html\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">W3C WCAG 2.2: Technik ARIA1 – aria-describedby</a> – W3C-Technik; nur verlinkt.</li></ul><h2>Was geprüft wurde und was nicht</h2><p>Alle Tests im vue-lab (Vue 3.5.45, @vue/test-utils 2.4.11, jsdom) grün; vue-tsc fehlerfrei (inklusive InstanceType der Komponente). NICHT geprüft: Server-Rendering/Hydration (kein SSR-Lab), Screenreader-Ansage, mehrere Vue-Apps mit idPrefix (nur aus der Vue-Dokumentation).</p><p class=\\\"rail-fuss\\\">Stand: 12.11.2026. Versionen und Verhalten können sich ändern; prüfe die verlinkten Quellen, bevor du in ein Produktivsystem übernimmst.</p>\",\"order\":[\"body\",\"code\",\"code2\",\"body2\"],\"tip\":\"Zugängliche Formularbausteine sind der Ort, wo sich Sorgfalt am meisten auszahlt: Jede Komponente einmal richtig bauen, dann überall wiederverwenden. Prüfe das Ergebnis mit der Tastatur (Tab, Fokusreihenfolge, Sprung zum ersten Fehler) und mit einem Screenreader, wenn möglich. Halte den freigegebenen Vertrag klein (focus, eventuell select), dokumentiere ihn in einem Satz und teste ihn, damit niemand versehentlich Interna freigibt.\",\"exercises\":[{\"level\":1,\"task\":\"Ergänze eine Möglichkeit, das Feld als Pflichtfeld zu kennzeichnen: Das Attribut required soll am <input> ankommen, und die Beschriftung zeigt ein sichtbares „(Pflicht)“. Schreibe einen Test.\",\"acceptance\":\"required steht am input (nicht am Wrapper); die Beschriftung enthält den Hinweis als Text, nicht nur durch Farbe oder ein Symbol.\"},{\"level\":2,\"task\":\"Grenzfall: Mounte zwei getrennte Vue-Apps mit je einem FormField auf derselben Seite und vergleiche die ids. Setze danach app.config.idPrefix und vergleiche erneut.\",\"acceptance\":\"Beobachtung dokumentiert (ohne Präfix können gleiche ids entstehen, mit Präfix nicht); Maskierung des Doppelpunkts im Selektor ist beachtet.\"},{\"level\":3,\"task\":\"Fehlerfall: Entferne defineOptions({ inheritAttrs: false }) und übergib type und data-testid. Wohin gehen die Attribute, und welche Warnung oder welches Verhalten beobachtest du?\",\"acceptance\":\"Die Attribute landen am Wrapper-Element, nicht am Feld; type=\\\"email\\\" wirkt nicht; die Beobachtung und die Wiederherstellung des Codes sind notiert.\"}],\"sources\":[{\"url\":\"https://vuejs.org/api/composition-api-helpers.html#useid\",\"title\":\"Vue: useId() (Composition API Helpers)\"},{\"url\":\"https://vuejs.org/guide/essentials/template-refs.html\",\"title\":\"Vue: Template Refs (useTemplateRef, v-for, Funktions-Refs)\"},{\"url\":\"https://vuejs.org/guide/components/attrs.html\",\"title\":\"Vue: Fallthrough Attributes ($attrs, inheritAttrs)\"},{\"url\":\"https://vuejs.org/guide/components/props.html#reactive-props-destructure\",\"title\":\"Vue: Props (Reactive Props Destructure, Vue 3.5)\"},{\"url\":\"https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA1.html\",\"title\":\"W3C WCAG 2.2: Technik ARIA1 – aria-describedby\"}],\"editorialRevision\":\"2026-11-12\",\"knowledgeAsOf\":\"2026-11-12\",\"quality\":{\"execution\":\"lab-run\",\"scope\":\"Alle Tests im vue-lab (Vue 3.5.45, @vue/test-utils 2.4.11, jsdom) grün; vue-tsc fehlerfrei (inklusive InstanceType der Komponente). NICHT geprüft: Server-Rendering/Hydration (kein SSR-Lab), Screenreader-Ansage, mehrere Vue-Apps mit idPrefix (nur aus der Vue-Dokumentation).\"},\"quiz\":[{\"q\":\"Warum nutzt FormField useId() statt einer selbst gebauten Zufallszahl?\",\"options\":[\"Zufallszahlen sind in Vue verboten und lösen beim Bauen einen Fehler aus.\",\"useId liefert pro Anwendung eindeutige Werte, die beim Server- und Browser-Rendering übereinstimmen.\",\"useId erzeugt kürzere ids, wodurch das HTML kleiner und die Seite schneller wird.\"],\"correct\":1,\"explain\":\"useId ist eindeutig und SSR-stabil; selbstgebaute Werte können beim Hydrieren abweichen.\",\"rationales\":[\"Zufallswerte sind erlaubt; sie führen aber beim Server-Rendering zu Abweichungen.\",\"Das verhindert Hydration-Mismatches und doppelte ids; so steht es in der Vue-Dokumentation.\",\"Länge oder Geschwindigkeit sind nicht der Grund; es geht um Eindeutigkeit und Stabilität.\"],\"sources\":[\"https://vuejs.org/api/composition-api-helpers.html#useid\",\"https://vuejs.org/guide/essentials/template-refs.html\",\"https://vuejs.org/guide/components/attrs.html\",\"https://vuejs.org/guide/components/props.html#reactive-props-destructure\",\"https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA1.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Warum ist inputAttrs() eine Funktion im Template und kein computed?\",\"options\":[\"Ein computed darf keine Objekte zurückgeben, nur einfache Werte wie Zahlen oder Text.\",\"Funktionen im Template laufen schneller als computed-Werte und sparen deshalb Rechenzeit.\",\"useAttrs() ist laut Vue-Doku nicht reaktiv; ein computed würde sich bei geänderten Attributen nicht aktualisieren.\"],\"correct\":2,\"explain\":\"$attrs/useAttrs sind nicht reaktiv; die Aufteilung muss bei jedem Rendern neu erfolgen.\",\"rationales\":[\"computed kann beliebige Werte zurückgeben, auch Objekte.\",\"Der Unterschied ist nicht die Geschwindigkeit, sondern die Aktualität der Werte.\",\"Die Attribute ändern sich außerhalb des Reaktivitätssystems; die Funktion wird bei jedem Rendern neu ausgewertet.\"],\"sources\":[\"https://vuejs.org/api/composition-api-helpers.html#useid\",\"https://vuejs.org/guide/essentials/template-refs.html\",\"https://vuejs.org/guide/components/attrs.html\",\"https://vuejs.org/guide/components/props.html#reactive-props-destructure\",\"https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA1.html\"],\"revision\":\"2026-11-12-java-vue-v1\"},{\"q\":\"Eine Elternkomponente hält eine Ref auf FormField und ruft focus() auf. Was ist dafür in FormField nötig?\",\"options\":[\"defineExpose({ focus }), denn script-setup-Komponenten geben ohne diese Freigabe nichts nach außen.\",\"Nichts, denn Eltern können in Vue immer jede interne Variable ihrer Kinder lesen.\",\"Eine Prop namens focus, die der Elternteil auf true setzt, damit das Feld den Fokus nimmt.\"],\"correct\":0,\"explain\":\"Ohne defineExpose bleibt eine script-setup-Komponente geschlossen; der Vertrag wird bewusst klein gehalten.\",\"rationales\":[\"Der Vertrag wird ausdrücklich freigegeben; im Test sind nur \\\"focus\\\" und sonst nichts sichtbar.\",\"Komponenten mit script setup sind standardmäßig geschlossen.\",\"Eine Prop würde einen Zustand beschreiben, kein einmaliges Kommando; „true setzen“ löst bei zweitem Aufruf nichts aus.\"],\"sources\":[\"https://vuejs.org/api/composition-api-helpers.html#useid\",\"https://vuejs.org/guide/essentials/template-refs.html\",\"https://vuejs.org/guide/components/attrs.html\",\"https://vuejs.org/guide/components/props.html#reactive-props-destructure\",\"https://www.w3.org/WAI/WCAG22/Techniques/aria/ARIA1.html\"],\"revision\":\"2026-11-12-java-vue-v1\"}],\"code\":\"<script setup lang=\\\"ts\\\">\\nimport { computed, useAttrs, useId, useTemplateRef } from 'vue';\\n\\n// Lektion \\\"Moderne Vue-3.5-APIs\\\": ein wiederverwendbares, zugängliches Eingabefeld.\\ndefineOptions({ inheritAttrs: false });     // Attribute gehören dem <input>, nicht dem äußeren <div>\\n\\n// Seit Vue 3.5 bleibt destrukturiertes defineProps reaktiv; Standardwerte stehen direkt im Destructuring.\\nconst { label, hint, error } = defineProps<{ label: string; hint?: string; error?: string }>();\\nconst model = defineModel<string>({ default: '' });\\n\\nconst id = useId();                                          // eindeutig je Aufruf, stabil bei Server-Rendering\\nconst attrs = useAttrs();\\nconst input = useTemplateRef<HTMLInputElement>('input');     // typisierte Template-Ref\\n\\nconst describedBy = computed(() => [hint && `${id}-hint`, error && `${id}-error`].filter(Boolean).join(' ') || undefined);\\n\\n// class und style gehören zum Wrapper, alle übrigen Attribute (type, autocomplete, data-*) zum Eingabefeld.\\n// $attrs ist nicht reaktiv, daher wird die Aufteilung bei jedem Rendern neu berechnet (Funktion statt computed).\\nfunction inputAttrs() {\\n  const { class: _class, style: _style, ...rest } = attrs;\\n  return rest;\\n}\\n\\n// Hinweis: Ein Kommentar vor dem Wurzelelement im Template würde im Entwicklungsmodus ein Fragment erzeugen\\n// und das Durchreichen von Attributen verändern. useAttrs() liefert unknown; class/style gehen unverändert an den Wrapper.\\n\\n// Die Komponente ist standardmäßig \\\"geschlossen\\\": Eltern sehen nur, was hier ausdrücklich freigegeben wird.\\ndefineExpose({ focus: () => input.value?.focus() });\\n</script>\\n\\n<template>\\n  <div :class=\\\"attrs.class\\\" :style=\\\"attrs.style as string | undefined\\\">\\n    <label :for=\\\"id\\\">{{ label }}</label>\\n    <input :id=\\\"id\\\" ref=\\\"input\\\" v-model=\\\"model\\\" v-bind=\\\"inputAttrs()\\\" :aria-invalid=\\\"error ? 'true' : undefined\\\" :aria-describedby=\\\"describedBy\\\">\\n    <small v-if=\\\"hint\\\" :id=\\\"`${id}-hint`\\\">{{ hint }}</small>\\n    <span v-if=\\\"error\\\" :id=\\\"`${id}-error`\\\">{{ error }}</span>\\n  </div>\\n</template>\",\"codeLang\":\"Vue\",\"code2\":\"<script setup lang=\\\"ts\\\">\\nimport { reactive, ref, useTemplateRef } from 'vue';\\nimport FormField from './FormField.vue';\\n\\n// Elternkomponente: nutzt die freigegebene focus()-Methode, um den Fokus auf das erste fehlerhafte Feld zu setzen.\\nconst emit = defineEmits<{ submit: [value: { name: string; email: string }] }>();\\nconst values = reactive({ name: '', email: '' });\\nconst errors = ref<{ name?: string; email?: string }>({});\\nconst nameField = useTemplateRef<InstanceType<typeof FormField>>('nameField');\\nconst emailField = useTemplateRef<InstanceType<typeof FormField>>('emailField');\\n\\nfunction onSubmit() {\\n  errors.value = {\\n    ...(values.name.trim() ? {} : { name: '";
